INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85730, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示原因或理由，常与“所以”配合使用。", "primary_collocate": null, "pronunciation": "yīn wèi", "ipa": "in˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "因为下雨，所以我们没去公园。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为他很努力，所以成绩很好。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为昨天睡得太晚，所以我今天很累。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为路上堵车，所以我迟到了。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为她会说中文，所以公司请她工作。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为太忙，所以他没有给我打电话。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气冷，所以大家都穿着厚衣服。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为这家店便宜，所以人很多。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为妈妈生病了，所以我回家照顾她。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为想学汉语，所以他来到了中国。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "因为：与“所以”配合，先说原因再说结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 睡得 (Zipf 3.28), 太晚 (Zipf 3.5), 很累 (Zipf 3.45)']::text[], '8d3283c2-c3c9-456b-a54d-b3cbf61747b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如果", "is_correct": false, "explanation": "语义：“如果”引出假设，而句子说的是已经发生的事，与“所以我们没去公园”不符。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”需要与“还”“却”等呼应，不与“所以”搭配。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”表示让步，与后句“所以”表示的因果关系相矛盾。"}, {"text": "因为", "is_correct": true, "explanation": "“因为”引出原因，与“所以”搭配，说明没去公园的原因。"}], "explanations": {"如果": "语义：“如果”引出假设，而句子说的是已经发生的事，与“所以我们没去公园”不符。", "尽管": "搭配：“尽管”需要与“还”“却”等呼应，不与“所以”搭配。", "虽然": "搭配：“虽然”表示让步，与后句“所以”表示的因果关系相矛盾。", "因为": "“因为”引出原因，与“所以”搭配，说明没去公园的原因。"}, "sentence_index": 0, "correct_answer": "因为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "因为他很努力，所以他没有成功。", "explanation": "这里应该用〈虽然〉。“努力”与“没有成功”是转折关系，要用“虽然……但是”；“因为……所以”表示顺接的因果，这里不通。"}, {"text": "他工作很努力，因为得到了升职。", "explanation": "这里应该用〈因此〉。“因为”引出原因，升职是努力的结果，应说“因此得到了升职”。"}, {"text": "因为天气很冷，他还是出去跑步了。", "explanation": "这里应该用〈虽然〉。“还是”要与让步的“虽然”呼应，用“因为”会使前后句意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只要", "is_correct": false, "explanation": "语义：“只要”引出条件，句子说的是已经发生的雨，不能用条件来表述。"}, {"text": "根据", "is_correct": false, "explanation": "搭配：“根据”后接依据，不能用于引出“冷”这样的原因，且后句“大家都穿着厚衣服”与之不搭。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，与“所以大家都穿着厚衣服”的因果关系相反。"}, {"text": "因为", "is_correct": true, "explanation": "“因为”引出“天气冷”这一原因，与“所以”配合，说明大家穿厚衣服的理由。"}], "explanations": {"只要": "语义：“只要”引出条件，句子说的是已经发生的雨，不能用条件来表述。", "根据": "搭配：“根据”后接依据，不能用于引出“冷”这样的原因，且后句“大家都穿着厚衣服”与之不搭。", "然而": "语义：“然而”表示转折，与“所以大家都穿着厚衣服”的因果关系相反。", "因为": "“因为”引出“天气冷”这一原因，与“所以”配合，说明大家穿厚衣服的理由。"}, "sentence_index": 6, "correct_answer": "因为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "因为你努力，就能成功。", "explanation": "这里应该用〈只要〉。“只要”表示条件，有了这一条件就有结果；“因为”只能引出已经发生的原因。"}, {"text": "这杯茶很苦，因为很甜。", "explanation": "这里应该用〈但是〉。“苦”与“甜”相反，表示转折；“因为”只能引出原因，不能这样连接相反的两项。"}, {"text": "天气很好，因为我们没去公园。", "explanation": "这里应该用〈然而〉。前后是转折：天气很好却没去公园，应说“然而”；“因为”表示原因，不能把转折说成因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "因为天气不好，因为我们取消了比赛。", "corrected_sentence": "因为天气不好，所以我们取消了比赛。", "error_description": "连词误用：前一分句已用“因为”引出原因，结果分句应用“所以”，不能再用“因为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "因为风太大，所以所以我们没出门。", "corrected_sentence": "因为风太大，所以我们没出门。", "error_description": "连词重复：“所以”只用一次，句中不应出现两个“所以”，应说“因为风太大，所以我们没出门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
