INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85733, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "“不是”是说不对，这个东西不是那个东西。", "primary_collocate": null, "pronunciation": "bú shì", "ipa": "pu˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这不是我的书，是他的。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那只狗不是黑色的。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不是我的老师。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天不是星期五。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这不是水，是白酒。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你拿的不是我的杯子。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个人不是小王。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里不是图书馆。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不是学生，我是老师。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条鱼不是活的。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "是不是", "label": "正反疑问形式"}], "register": "通用", "sense_fingerprint": "否定两个事物相同，说明这个东西不是那个东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae0a5167-b7a0-4535-b648-c4ab11c8f416') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85733, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不是", "is_correct": true, "explanation": "“不是”表示否定判断，与后面“是他的”相呼应。"}, {"text": "不吃", "is_correct": false, "explanation": "语义：“吃”的对象不能是书，“这不吃我的书”不通。"}, {"text": "不要", "is_correct": false, "explanation": "语义：“不要”表示不想要，与“是他的”的判断语气不搭配。"}, {"text": "不会", "is_correct": false, "explanation": "搭配：“不会”是能愿动词，不能直接带“我的书”作宾语来表示判断。"}], "explanations": {"不是": "“不是”表示否定判断，与后面“是他的”相呼应。", "不吃": "语义：“吃”的对象不能是书，“这不吃我的书”不通。", "不要": "语义：“不要”表示不想要，与“是他的”的判断语气不搭配。", "不会": "搭配：“不会”是能愿动词，不能直接带“我的书”作宾语来表示判断。"}, "sentence_index": 0, "correct_answer": "不是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家不是一台电视。", "explanation": "表示没有某物应用“没有”，“不是”只用于判断，“我家不是一台电视”讲不通，应说“我家没有电视”。"}, {"text": "教室里不是一个学生。", "explanation": "表示没有人应用“没有”，“不是”只用于判断，这里应说“教室里没有学生”。"}, {"text": "他今天不是病了。", "explanation": "表示今天没有生病应用“没”，“不是”只用于判断，这里应说“他今天没生病”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不是", "is_correct": true, "explanation": "“不是”表示否定判断，与“那个人”和“小王”构成判断关系。"}, {"text": "不写", "is_correct": false, "explanation": "配价：“写”要求书写的对象是文字，“那个人不写小王”不通。"}, {"text": "不跑", "is_correct": false, "explanation": "语义：“跑”是动作，不能和“小王”构成否定判断，句意不通。"}, {"text": "不做", "is_correct": false, "explanation": "搭配：“做”带人作宾语须指可担任的身份（如“做老师”），“做小王”不通。"}], "explanations": {"不是": "“不是”表示否定判断，与“那个人”和“小王”构成判断关系。", "不写": "配价：“写”要求书写的对象是文字，“那个人不写小王”不通。", "不跑": "语义：“跑”是动作，不能和“小王”构成否定判断，句意不通。", "不做": "搭配：“做”带人作宾语须指可担任的身份（如“做老师”），“做小王”不通。"}, "sentence_index": 6, "correct_answer": "不是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天不是吃饭了。", "explanation": "表示过去没吃饭应用“没”，“不是”不能与“了”搭配否定动作，这里应说“我昨天没吃饭”。"}, {"text": "你不是说话，安静一点。", "explanation": "表示禁止某事应用“不要”或“别”，“不是”不能用于禁止。"}, {"text": "我不是会游泳。", "explanation": "表示不会做某事应用“不会”或“不能”，“不是”只表示判断，这里应说“我不会游泳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这不不是我的书。", "corrected_sentence": "这不是我的书。", "error_description": "错误：“不是”前多写了一个“不”，成了“不不是”。判断句的否定只用一个“不”，应说“这不是我的书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很不是中国人。", "corrected_sentence": "他不是中国人。", "error_description": "错误：副词“很”不能放在“不是”前面。判断句的否定直接用“不是”，应说“他不是中国人”，不能说“他很不是中国人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
