INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85734, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "动词，表示否定判断，不等于，与“是”相对。", "primary_collocate": null, "pronunciation": "bú shì", "ipa": "pu˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "她不是医生，是护士。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在不是睡觉的时候。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说的不是真话。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买书不是我今天的目的。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个办法不是最好的办法。", "target_word": "不是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不是坏人，请你放心。", "target_word": "不是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看电视不是学习。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京不是中国最大的城市。", "target_word": "不是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这不是你的错。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钱不是最重要的东西。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "是不是", "label": "正反疑问形式"}], "register": "通用", "sense_fingerprint": "否定判断动词，与“是”相对，表示不等于、不属于", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae0a5167-b7a0-4535-b648-c4ab11c8f416') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85734, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不是", "is_correct": true, "explanation": "正确答案：不是（bú shì），表示否定判断。"}, {"text": "不识", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是“不认识”。"}, {"text": "不使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是“不使用”。"}, {"text": "不失", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是“没有失去”。"}, {"text": "部室", "is_correct": false, "explanation": "“部”读 bù（第四声），与“不是”的“不”（bú，第二声）声调不同，意思是部门的办公室。"}], "explanations": {"不是": "正确答案：不是（bú shì），表示否定判断。", "不识": "shí（第二声）与 shì（第四声）声调不同，意思是“不认识”。", "不使": "shǐ（第三声）与 shì（第四声）声调不同，意思是“不使用”。", "不失": "shī（第一声）与 shì（第四声）声调不同，意思是“没有失去”。", "部室": "“部”读 bù（第四声），与“不是”的“不”（bú，第二声）声调不同，意思是部门的办公室。"}, "sentence_index": null, "correct_answer": "不是"}, "level_3": {"options": [{"text": "不是", "is_correct": true, "explanation": "正确：“不是”否定“医生”这一身份判断，与后句“是护士”形成对比。"}, {"text": "变成", "is_correct": false, "explanation": "语义：“变成”表示发生变化，与“是护士”的身份判断相矛盾，前后语义不通。"}, {"text": "当", "is_correct": false, "explanation": "搭配：“当”后接的职务表示担任，与后句“是护士”的身份判断冲突，两者不能并列。"}, {"text": "有", "is_correct": false, "explanation": "配价：“有”带的是所有物，不能直接用“医生”这类身份名词来说明“她是……”。"}], "explanations": {"不是": "正确：“不是”否定“医生”这一身份判断，与后句“是护士”形成对比。", "变成": "语义：“变成”表示发生变化，与“是护士”的身份判断相矛盾，前后语义不通。", "当": "搭配：“当”后接的职务表示担任，与后句“是护士”的身份判断冲突，两者不能并列。", "有": "配价：“有”带的是所有物，不能直接用“医生”这类身份名词来说明“她是……”。"}, "sentence_index": 0, "correct_answer": "不是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上不是一本书。", "explanation": "表示存在或没有某物应用“没有”，“不是”只用于判断，这里应说“桌子上没有书”。"}, {"text": "你不是说话，安静一点。", "explanation": "表示禁止某事应用“不要”或“别”，“不是”不能用于禁止，这里应说“你别说话，安静一点”。"}, {"text": "他刚才不是跑步了。", "explanation": "表示刚才没有做某事应用“没”，“不是”不能与“了”搭配否定动作，这里应说“他刚才没跑步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85734, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不是", "is_correct": true, "explanation": "正确答案：不是（bú shì），表示否定判断。"}, {"text": "博士", "is_correct": false, "explanation": "bó 与 bú 韵母不同（o 与 u），意思是学位“博士”。"}, {"text": "不时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是“时常”。"}, {"text": "不似", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），声调相同，意思是“不像”。"}, {"text": "不致", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），声调相同，意思是“不会导致”。"}], "explanations": {"不是": "正确答案：不是（bú shì），表示否定判断。", "博士": "bó 与 bú 韵母不同（o 与 u），意思是学位“博士”。", "不时": "shí（第二声）与 shì（第四声）声调不同，意思是“时常”。", "不似": "sì 与 shì 声母不同（s 与 sh），声调相同，意思是“不像”。", "不致": "zhì 与 shì 声母不同（zh 与 sh），声调相同，意思是“不会导致”。"}, "sentence_index": null, "correct_answer": "不是"}, "level_3": {"options": [{"text": "不是", "is_correct": true, "explanation": "正确：“不是”否定“看电视”属于“学习”，与句意一致。"}, {"text": "成为", "is_correct": false, "explanation": "语义：“成为”表示转变为某种状态，“看电视”与“学习”之间不存在转变关系。"}, {"text": "讨厌", "is_correct": false, "explanation": "搭配：“讨厌”要求有情感的人作主语，“看电视”作主语无法表达厌恶。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”需要有意志的主体，“看电视”不能对“学习”表示反对。"}], "explanations": {"不是": "正确：“不是”否定“看电视”属于“学习”，与句意一致。", "成为": "语义：“成为”表示转变为某种状态，“看电视”与“学习”之间不存在转变关系。", "讨厌": "搭配：“讨厌”要求有情感的人作主语，“看电视”作主语无法表达厌恶。", "反对": "语义：“反对”需要有意志的主体，“看电视”不能对“学习”表示反对。"}, "sentence_index": 6, "correct_answer": "不是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里不是一个人。", "explanation": "表示没有人应用“没有”，“不是”只用于判断，这里应说“屋里没有人”。"}, {"text": "我今天不是迟到了。", "explanation": "表示没有迟到应用“没”，“不是”不能与“了”搭配否定动作，这里应说“我今天没迟到”。"}, {"text": "他不是会跑步。", "explanation": "表示不会做某事应用“不会”或“不能”，“不是”只表示判断，这里应说“他不会跑步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不是是中国人。", "corrected_sentence": "他不是中国人。", "error_description": "错误：“是”多写了一遍，成了“不是是”。应为“不是中国人”，判断句的否定只用一个“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不是了学生。", "corrected_sentence": "我不是学生。", "error_description": "错误：“不是”后面不能加“了”，“不是”是否定判断的固定格式。应说“我不是学生”，不能说“我不是了学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "“过去”指说话时刻之前的时间，与“现在”构成时间上的反义关系。"}, {"text": "清晨", "is_correct": false, "explanation": "“清晨”指一天中早上的时段，与“现在”不构成相对关系。"}, {"text": "深夜", "is_correct": false, "explanation": "“深夜”指夜深的时段，与“现在”没有时间上的相对关系。"}, {"text": "傍晚", "is_correct": false, "explanation": "“傍晚”指太阳快落山的时段，与“现在”不构成反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "“过去”指说话时刻之前的时间，与“现在”构成时间上的反义关系。", "清晨": "“清晨”指一天中早上的时段，与“现在”不构成相对关系。", "深夜": "“深夜”指夜深的时段，与“现在”没有时间上的相对关系。", "傍晚": "“傍晚”指太阳快落山的时段，与“现在”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "将来", "is_correct": true, "explanation": "“将来”指说话之后的时间，与“现在”构成时间上的反义关系。"}, {"text": "凌晨", "is_correct": false, "explanation": "“凌晨”指天亮前的一段时间，与“现在”没有相对关系。"}, {"text": "午后", "is_correct": false, "explanation": "“午后”指中午以后的时段，与“现在”不构成反义关系。"}, {"text": "午夜", "is_correct": false, "explanation": "“午夜”指夜间十二点前后，与“现在”不构成相对关系。"}], "correct_answer": "将来", "explanations": {"将来": "“将来”指说话之后的时间，与“现在”构成时间上的反义关系。", "凌晨": "“凌晨”指天亮前的一段时间，与“现在”没有相对关系。", "午后": "“午后”指中午以后的时段，与“现在”不构成反义关系。", "午夜": "“午夜”指夜间十二点前后，与“现在”不构成相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“现在”是说说话的这个时候。", "primary_collocate": null, "pronunciation": "xiàn zài", "ipa": "ɕjɛn˥˩ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "现在几点了？", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在在学校，不在家。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他现在不忙，你可以来。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在天气很冷，要多穿衣服。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在在做什么？", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在住在北京。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做好了，现在我们去吃吧。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸现在正在家看书。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在是晚上八点。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她现在很累，想回家休息。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現在", "label": "繁体"}], "register": "通用", "sense_fingerprint": "说话的这个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027318f4-2b33-4396-a5c8-0febbc57a5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现在", "is_correct": true, "explanation": "“现在”指说话的此刻，与“几点了”的询问相符。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指前一天，与询问当前钟点的“几点了”冲突。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指第二天，无法用来询问说话时刻的钟点。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指上一年，是时间名词，不能用来询问说话时刻的钟点，与“几点了”不能搭配。"}], "explanations": {"现在": "“现在”指说话的此刻，与“几点了”的询问相符。", "昨天": "语义：“昨天”指前一天，与询问当前钟点的“几点了”冲突。", "明天": "语义：“明天”指第二天，无法用来询问说话时刻的钟点。", "去年": "语义：“去年”指上一年，是时间名词，不能用来询问说话时刻的钟点，与“几点了”不能搭配。"}, "sentence_index": 0, "correct_answer": "现在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "1990年，我现在在上海读书。", "explanation": "这里应该用〈当时〉。“现在”指说话的这一时刻，不能用来指1990年这样的过去时间。"}, {"text": "明天，我现在出发去北京。", "explanation": "这里的时间只应由〈明天〉表示。“现在”指说话的此刻，与“明天”这样的未来时间冲突，应去掉“现在”。"}, {"text": "去年，我们现在决定搬家。", "explanation": "这里应只保留〈去年〉表示过去的时间，去掉“现在”。“现在”指说话的此刻，不能与“去年”同时指示同一事件的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现在", "is_correct": true, "explanation": "“现在”指说话的此刻，饭已做好，正适合此刻去吃。"}, {"text": "以前", "is_correct": false, "explanation": "语义：“以前”指过去，与“饭做好了”后提议去吃的语境不符。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指不久前，与“饭做好了”后提议去吃的语境不符。"}, {"text": "早先", "is_correct": false, "explanation": "语义：“早先”指很早以前，与“饭做好了”的当下语境冲突。"}], "explanations": {"现在": "“现在”指说话的此刻，饭已做好，正适合此刻去吃。", "以前": "语义：“以前”指过去，与“饭做好了”后提议去吃的语境不符。", "刚才": "语义：“刚才”指不久前，与“饭做好了”后提议去吃的语境不符。", "早先": "语义：“早先”指很早以前，与“饭做好了”的当下语境冲突。"}, "sentence_index": 6, "correct_answer": "现在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小时候，我现在很怕狗。", "explanation": "这里不能用〈现在〉。“现在”指说话的此刻，与表示过去的“小时候”冲突，应只保留〈小时候〉，去掉“现在”。"}, {"text": "上个月，他现在生病了。", "explanation": "这里不能用〈现在〉。“现在”指说话时刻，不能指上个月发生的事，应只用〈上个月〉。"}, {"text": "以后，我现在去上海工作。", "explanation": "这里不能用〈现在〉。“现在”指说话时刻，与表示将来的〈以后〉冲突，应只保留〈以后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹在现在睡觉，别吵她。", "corrected_sentence": "妹妹现在在睡觉，别吵她。", "error_description": "时间词“现在”作状语，应放在主语后、“在”之前。错误形式“在现在睡觉”把“现在”与“在”的顺序颠倒，应说“妹妹现在在睡觉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子现在的在写作业。", "corrected_sentence": "孩子现在在写作业。", "error_description": "“现在”作状语修饰动词时不带“的”，“的”只用于“现在的”后接名词作定语，如“现在的孩子”。错误形式“现在的在写作业”不成立，应说“孩子现在在写作业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "“过去”指说话时刻之前的时间，与“现在”构成时间上的反义关系。"}, {"text": "黎明", "is_correct": false, "explanation": "“黎明”指天将亮的时候，与“现在”不构成相对关系。"}, {"text": "中午", "is_correct": false, "explanation": "“中午”指一天中午前后的时段，与“现在”不是反义关系。"}, {"text": "夜间", "is_correct": false, "explanation": "“夜间”指夜里的时段，与“现在”不构成时间上的相对关系。"}], "correct_answer": "过去", "explanations": {"过去": "“过去”指说话时刻之前的时间，与“现在”构成时间上的反义关系。", "黎明": "“黎明”指天将亮的时候，与“现在”不构成相对关系。", "中午": "“中午”指一天中午前后的时段，与“现在”不是反义关系。", "夜间": "“夜间”指夜里的时段，与“现在”不构成时间上的相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "将来", "is_correct": true, "explanation": "“将来”指说话之后的时间，与“过去”“现在”构成时间上的对照。"}, {"text": "黄昏", "is_correct": false, "explanation": "“黄昏”指日落前后的时段，与“现在”不构成相对关系。"}, {"text": "下午", "is_correct": false, "explanation": "“下午”指中午到晚上之间的时段，与“现在”没有反义关系。"}, {"text": "半夜", "is_correct": false, "explanation": "“半夜”指深夜的一段时间，与“现在”不构成相对关系。"}], "correct_answer": "将来", "explanations": {"将来": "“将来”指说话之后的时间，与“过去”“现在”构成时间上的对照。", "黄昏": "“黄昏”指日落前后的时段，与“现在”不构成相对关系。", "下午": "“下午”指中午到晚上之间的时段，与“现在”没有反义关系。", "半夜": "“半夜”指深夜的一段时间，与“现在”不构成相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指当前这一阶段、如今，与“过去”“将来”相对。", "primary_collocate": null, "pronunciation": "xiàn zài", "ipa": "ɕjɛn˥˩ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "以前他很瘦，现在很胖。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去我喜欢跑步，现在喜欢游泳。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在不学，将来会后悔。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我住乡下，现在住城里。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年他还不会说汉语，现在说得很好。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去的事别想了，想想现在吧。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前没有手机，现在的孩子都有。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在工作很忙，以后会有时间。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前这里是田，现在是学校。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他过去在上海，现在在广州。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現在", "label": "繁体"}], "register": "通用", "sense_fingerprint": "与过去、将来相对的当前阶段或如今", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027318f4-2b33-4396-a5c8-0febbc57a5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现在", "is_correct": true, "explanation": "“现在”与“以前”构成对照，表示当下的状态，填入后句意通顺。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指前一天，与“以前”重复表示过去，且不能对照当下的“很胖”。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“以前他很瘦”对照时句意矛盾。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：“刚才”指不久前，不能用来引出“很胖”这一状态的对照。"}], "explanations": {"现在": "“现在”与“以前”构成对照，表示当下的状态，填入后句意通顺。", "昨天": "语义：“昨天”指前一天，与“以前”重复表示过去，且不能对照当下的“很胖”。", "明天": "语义：“明天”指将来，与“以前他很瘦”对照时句意矛盾。", "刚才": "搭配：“刚才”指不久前，不能用来引出“很胖”这一状态的对照。"}, "sentence_index": 0, "correct_answer": "现在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那时的现在，我很害怕。", "explanation": "这里不能用〈现在〉。“现在”指说话的这一时刻，不能用来指过去的时间，应改用〈当时〉。"}, {"text": "过去我现在喜欢跑步。", "explanation": "这里应只用〈过去〉。“现在”与“过去”指向不同时间，不能同时修饰“喜欢跑步”。"}, {"text": "我现在将来要当医生。", "explanation": "这里应只用〈将来〉。“现在”指说话时刻，与“将来”同时修饰同一动作，时间指向冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现在", "is_correct": true, "explanation": "“现在的孩子”指当今的孩子，与“以前没有手机”形成对照。"}, {"text": "清早", "is_correct": false, "explanation": "语义：“清早”指一天的早晨，无法与“以前没有手机”的对照语境搭配，句意不通。"}, {"text": "傍晚", "is_correct": false, "explanation": "语义：“傍晚”指白天将尽的时段，与“以前没有手机”的对照语境不通。"}, {"text": "夜里", "is_correct": false, "explanation": "语义：“夜里”指夜间，不能作为“孩子”的时间定语来对照“以前”。"}], "explanations": {"现在": "“现在的孩子”指当今的孩子，与“以前没有手机”形成对照。", "清早": "语义：“清早”指一天的早晨，无法与“以前没有手机”的对照语境搭配，句意不通。", "傍晚": "语义：“傍晚”指白天将尽的时段，与“以前没有手机”的对照语境不通。", "夜里": "语义：“夜里”指夜间，不能作为“孩子”的时间定语来对照“以前”。"}, "sentence_index": 6, "correct_answer": "现在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去年他现在在广州。", "explanation": "这里不能用〈现在〉。“现在”指说话时刻，与表示过去的〈去年〉冲突，应只保留〈去年〉。"}, {"text": "上周他现在在广州。", "explanation": "这里不能用〈现在〉。“现在”指说话时刻，不能指上周发生的状况。"}, {"text": "当时他现在在广州。", "explanation": "这里不能用〈现在〉。“当时”指过去的某一时间，与“现在”同时使用时时间指向冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们以前住在山里，在现在城里住。", "corrected_sentence": "我们以前住在山里，现在在城里住。", "error_description": "“现在”作时间状语，应放在主语后、“在”之前。错误形式“在现在城里住”把“在”放到“现在”前，语序不通，应说“现在在城里住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前很胖，现在我的很瘦。", "corrected_sentence": "我以前很胖，现在的我很瘦。", "error_description": "“现在的”修饰代词“我”，“的”应紧跟在“现在”后。错误形式把“的”放到“我”后，成了“现在我的很瘦”，句子不通。应说“现在的我很瘦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
