INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "方位词，表示在某个范围或空间之内，与“外”相对。", "primary_collocate": null, "pronunciation": "lǐ", "ipa": "li˨˩˦", "syllable_count": 1, "sentences": [{"text": "学校里有很多树。", "target_word": "里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个城市里有三百万人。", "target_word": "里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "教室里很安静，大家都在看书。", "target_word": "里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的院子里种着很多花。", "target_word": "里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有人在跳舞。", "target_word": "里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间里太热，我想开窗。", "target_word": "里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "图书馆里不能大声说话。", "target_word": "里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "超市里的东西比网上贵。", "target_word": "里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天晚上，这座山里下了大雪。", "target_word": "里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在我们公司里，大家都叫他老王。", "target_word": "里", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "里面", "label": "复合"}, {"form": "里头", "label": "复合"}, {"form": "裡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "里|方位词|某个范围或空间之内，与外相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d46218-0b69-4845-8d22-7c88f2e3105e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85742, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "里", "is_correct": true, "explanation": "里（lǐ，第三声）表示在某个范围之内，是本题的正确答案。"}, {"text": "力", "is_correct": false, "explanation": "力（lì，第四声）与 lǐ 声调不同，意思是力量。"}, {"text": "离", "is_correct": false, "explanation": "离（lí，第二声）与 lǐ 声调不同，意思是离开、距离。"}, {"text": "你", "is_correct": false, "explanation": "你（nǐ）与 lǐ 声母不同，n 与 l 相混，意思是你。"}], "explanations": {"里": "里（lǐ，第三声）表示在某个范围之内，是本题的正确答案。", "力": "力（lì，第四声）与 lǐ 声调不同，意思是力量。", "离": "离（lí，第二声）与 lǐ 声调不同，意思是离开、距离。", "你": "你（nǐ）与 lǐ 声母不同，n 与 l 相混，意思是你。"}, "sentence_index": null, "correct_answer": "里"}, "level_3": {"options": [{"text": "里", "is_correct": true, "explanation": "里：表示在学校这个范围之内，与“有很多树”搭配，正确。"}, {"text": "上", "is_correct": false, "explanation": "语义：“上”表示接触某个平面，学校不是平面，“学校上有很多树”不通。"}, {"text": "下", "is_correct": false, "explanation": "语义：“下”表示位于某物底下，与学校的空间关系不符，“学校下有很多树”不通。"}, {"text": "间", "is_correct": false, "explanation": "搭配：“间”不能单独接在“学校”后作方位词，此处应说“学校里”。"}], "explanations": {"里": "里：表示在学校这个范围之内，与“有很多树”搭配，正确。", "上": "语义：“上”表示接触某个平面，学校不是平面，“学校上有很多树”不通。", "下": "语义：“下”表示位于某物底下，与学校的空间关系不符，“学校下有很多树”不通。", "间": "搭配：“间”不能单独接在“学校”后作方位词，此处应说“学校里”。"}, "sentence_index": 0, "correct_answer": "里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "黑板里写着今天的作业。", "explanation": "这里应该用〈上〉。“上”表示在某物的表面，黑板是平面，应说“黑板上写着”；“里”表示在某个范围之内，不用于平面。"}, {"text": "我和他俩里的关系一直很好。", "explanation": "这里应该用〈之间〉。“之间”用于说明两者之间的关系，“里”表示在某个范围之内，不能用来说两人的关系。"}, {"text": "他明天里要回国。", "explanation": "这里应该去掉〈里〉。「里」表示空间范围，不表示时间，说明天的事直接用「明天」，应为「他明天要回国」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85742, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "里", "is_correct": true, "explanation": "里（lǐ，第三声）表示在某个范围之内，是本题的正确答案。"}, {"text": "利", "is_correct": false, "explanation": "利（lì，第四声）与 lǐ 声调不同，意思是利益、锋利。"}, {"text": "梨", "is_correct": false, "explanation": "梨（lí，第二声）与 lǐ 声调不同，意思是水果梨子。"}, {"text": "旅", "is_correct": false, "explanation": "旅（lǚ，第三声）与 lǐ 韵母不同（ü 与 i），意思是旅行。"}], "explanations": {"里": "里（lǐ，第三声）表示在某个范围之内，是本题的正确答案。", "利": "利（lì，第四声）与 lǐ 声调不同，意思是利益、锋利。", "梨": "梨（lí，第二声）与 lǐ 声调不同，意思是水果梨子。", "旅": "旅（lǚ，第三声）与 lǐ 韵母不同（ü 与 i），意思是旅行。"}, "sentence_index": null, "correct_answer": "里"}, "level_3": {"options": [{"text": "里", "is_correct": true, "explanation": "里：表示在图书馆这个范围之内，规定只适用于馆内，正确。"}, {"text": "顶", "is_correct": false, "explanation": "语义：“顶”指物体的最上部，规定针对的是空间，“图书馆顶不能大声说话”不通。"}, {"text": "底", "is_correct": false, "explanation": "搭配：“底”多用于物体的底部，不用于建筑物的空间，“图书馆底”不成立。"}, {"text": "侧", "is_correct": false, "explanation": "搭配：“侧”不能直接接在“图书馆”后作方位词，此处应说“图书馆里”。"}], "explanations": {"里": "里：表示在图书馆这个范围之内，规定只适用于馆内，正确。", "顶": "语义：“顶”指物体的最上部，规定针对的是空间，“图书馆顶不能大声说话”不通。", "底": "搭配：“底”多用于物体的底部，不用于建筑物的空间，“图书馆底”不成立。", "侧": "搭配：“侧”不能直接接在“图书馆”后作方位词，此处应说“图书馆里”。"}, "sentence_index": 6, "correct_answer": "里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐在我身里，一句话也不说。", "explanation": "这里应该用〈旁〉。“身旁”表示在身边，“身里”不是固定说法，“里”不表示身边。"}, {"text": "学校对面里有一家书店。", "explanation": "这里应该去掉〈里〉。「对面」本身已标示方位，再加「里」叠用；且学校对面的店不在学校范围之内，“学校对面里”不通，应为「学校对面有一家书店」。"}, {"text": "他站在门外里等你。", "explanation": "这里应该用〈门口〉。“门外”表示在门的外侧，“里”表示在某个范围之内，两者方向相反，“门外里”自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箱子面里放着很多衣服。", "corrected_sentence": "箱子里放着很多衣服。", "error_description": "错误：「箱子面里」中多加了「面」，「面里」不成词。正确：方位词「里」直接接在「箱子」后，应为「箱子里放着很多衣服」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司在里有很多年轻人。", "corrected_sentence": "公司里有很多年轻人。", "error_description": "错误：「公司在里」中多加了「在」，与方位词「里」叠用。「里」已表示方位，正确：应为「公司里有很多年轻人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
