INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85743, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“及”可以把几个人或几样东西连在一起。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "桌子上放着书、笔及本子。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师及同学们都来参加晚会。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有大人及孩子。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请带好身份证及学生证。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理及他的朋友明天到北京。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里卖水果、蔬菜及牛奶。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师及李老师都很喜欢她。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口有很多自行车及汽车。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有爸爸、妈妈及哥哥。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生及护士一直在工作。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "及：把几个人或几样东西并列连接，相当于“和”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d3283c2-c3c9-456b-a54d-b3cbf61747b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85743, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "及", "is_correct": true, "explanation": "及（jí）：并列连接，相当于“和”。"}, {"text": "记", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是记住。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}, {"text": "季", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是季节。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是机器。"}], "explanations": {"及": "及（jí）：并列连接，相当于“和”。", "记": "jì（第四声）与 jí（第二声）声调不同，意思是记住。", "鸡": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。", "季": "jì（第四声）与 jí（第二声）声调不同，意思是季节。", "机": "jī（第一声）与 jí（第二声）声调不同，意思是机器。"}, "sentence_index": null, "correct_answer": "及"}, "level_3": {"options": [{"text": "及", "is_correct": true, "explanation": "及：把“书、笔”和“本子”并列连接，相当于“和”。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，要连接分句，这里只是并列列举，意思说不通。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，前后意思要相反，这里没有转折关系。"}, {"text": "而", "is_correct": false, "explanation": "搭配：“而”一般连接动词或形容词，不能连接名词“笔”和“本子”。"}], "explanations": {"及": "及：把“书、笔”和“本子”并列连接，相当于“和”。", "因为": "语义：“因为”表示原因，要连接分句，这里只是并列列举，意思说不通。", "但是": "语义：“但是”表示转折，前后意思要相反，这里没有转折关系。", "而": "搭配：“而”一般连接动词或形容词，不能连接名词“笔”和“本子”。"}, "sentence_index": 0, "correct_answer": "及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们及星期一开会。", "explanation": "这里应该用〈在〉。及不能表示时间，“在星期一开会”要用〈在〉。"}, {"text": "我及老师说了这件事。", "explanation": "这里应该用〈跟〉。及不能引出说话的对象，“跟老师说”要用〈跟〉。"}, {"text": "我们及教室里学习。", "explanation": "这里应该用〈在〉。及是连词，不能表示动作发生的地点，“在教室里”要用〈在〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85743, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "及", "is_correct": true, "explanation": "及（jí）：并列连接，相当于“和”。"}, {"text": "技", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是技术。"}, {"text": "基", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是基础。"}, {"text": "己", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。"}, {"text": "继", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是继续。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是拥挤。"}, {"text": "积", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是积累。"}], "explanations": {"及": "及（jí）：并列连接，相当于“和”。", "技": "jì（第四声）与 jí（第二声）声调不同，意思是技术。", "基": "jī（第一声）与 jí（第二声）声调不同，意思是基础。", "己": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。", "继": "jì（第四声）与 jí（第二声）声调不同，意思是继续。", "挤": "jǐ（第三声）与 jí（第二声）声调不同，意思是拥挤。", "积": "jī（第一声）与 jí（第二声）声调不同，意思是积累。"}, "sentence_index": null, "correct_answer": "及"}, "level_3": {"options": [{"text": "及", "is_correct": true, "explanation": "及：把“王老师”和“李老师”并列连接，相当于“和”。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，“都很喜欢她”前后没有对立，不能用转折词。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，前一部分并不是后一部分的原因。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”“却”等配合，不能直接连接两个名词。"}], "explanations": {"及": "及：把“王老师”和“李老师”并列连接，相当于“和”。", "然而": "语义：“然而”表示转折，“都很喜欢她”前后没有对立，不能用转折词。", "因此": "语义：“因此”表示因果，前一部分并不是后一部分的原因。", "虽然": "搭配：“虽然”要与“但是”“却”等配合，不能直接连接两个名词。"}, "sentence_index": 6, "correct_answer": "及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他及北京来。", "explanation": "这里应该用〈从〉。及不能表示动作的起点，“从北京来”要用〈从〉。"}, {"text": "请及筷子吃饭。", "explanation": "这里应该用〈用〉。及不能引出工具，“用筷子吃饭”要用〈用〉。"}, {"text": "我们明天及北京。", "explanation": "这里应该用〈去〉。及不能表示前往某地，“去北京”要用〈去〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
