INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85757, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词，用在动词前，与动词组成名词性短语，相当于“……的人或事物”；也用于“据……所知”等固定格式。", "primary_collocate": null, "pronunciation": "suǒ", "ipa": "suɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "据我所知，他今天不在家。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我所希望的结果。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把所学的知识都用上了。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们所住的地方很安静。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请说出你所想的。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些就是我所知道的。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她所做的一切都是为了孩子。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我所喜欢的老师姓王。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我所需要的东西都带来了。", "target_word": "所", "complexity_tier": "T3", "furigana": "wǒ suǒ xūyào de dōng xi dōu dài lái le", "sentence_source": "generated"}, {"text": "我把所写的内容都发给了老师。", "target_word": "所", "complexity_tier": "T3", "furigana": "wǒ bǎ suǒ xiě de nèi róng dōu fā gěi le lǎo shī", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "助词：放在动词前，使动作成为名词性成分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d3283c2-c3c9-456b-a54d-b3cbf61747b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85757, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "所", "is_correct": true, "explanation": "所（suǒ）：助词，用在动词前，使动作成为名词性成分。"}, {"text": "缩", "is_correct": false, "explanation": "suō（第一声）与 suǒ（第三声）声调不同，意思是收缩。"}, {"text": "梭", "is_correct": false, "explanation": "suō（第一声）与 suǒ（第三声）声调不同，意思是梭子。"}, {"text": "左", "is_correct": false, "explanation": "zuǒ 与 suǒ 声母不同（z 与 s），意思是左边。"}], "explanations": {"所": "所（suǒ）：助词，用在动词前，使动作成为名词性成分。", "缩": "suō（第一声）与 suǒ（第三声）声调不同，意思是收缩。", "梭": "suō（第一声）与 suǒ（第三声）声调不同，意思是梭子。", "左": "zuǒ 与 suǒ 声母不同（z 与 s），意思是左边。"}, "sentence_index": null, "correct_answer": "所"}, "level_3": {"options": [{"text": "所", "is_correct": true, "explanation": "所：与“据”配合，构成“据……所知”的固定格式。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”要接在形容词或副词后，“据我地知”不成立。"}, {"text": "过", "is_correct": false, "explanation": "体貌：“过”表示经历，不能放在“据我”和“知”之间。"}, {"text": "的", "is_correct": false, "explanation": "搭配：“的”要连接名词性成分，“据我的知”不成立。"}], "explanations": {"所": "所：与“据”配合，构成“据……所知”的固定格式。", "地": "搭配：“地”要接在形容词或副词后，“据我地知”不成立。", "过": "体貌：“过”表示经历，不能放在“据我”和“知”之间。", "的": "搭配：“的”要连接名词性成分，“据我的知”不成立。"}, "sentence_index": 0, "correct_answer": "所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们所很安静。", "explanation": "这里应该去掉〈所〉。“所”后要接动词，“很安静”是形容词短语，不能用“所”。"}, {"text": "我们的所住地方很安静。", "explanation": "这里应该把〈所〉放在动词“住”之前，说“我们所住的地方”。“所”不能放在“的”之后。"}, {"text": "这是我所的朋友。", "explanation": "这里应该去掉〈所〉。“的”之前需要动词，“朋友”不是动作，不能用“所”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所", "is_correct": true, "explanation": "所：用在动词前，与“做的一切”构成名词性短语。"}, {"text": "了", "is_correct": false, "explanation": "体貌：“了”表示完成，不能放在动词“做”之前。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”表示持续状态，不能放在动词“做”之前构成名词性短语。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问语气，句中不能使用。"}], "explanations": {"所": "所：用在动词前，与“做的一切”构成名词性短语。", "了": "体貌：“了”表示完成，不能放在动词“做”之前。", "着": "体貌：“着”表示持续状态，不能放在动词“做”之前构成名词性短语。", "吗": "语义：“吗”表示疑问语气，句中不能使用。"}, "sentence_index": 6, "correct_answer": "所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他所走得很慢。", "explanation": "这里应该去掉〈所〉。“所”后面要接动词，“走得很慢”是补语结构，不能直接放在“所”后。"}, {"text": "这部电影所十分好看。", "explanation": "这里应该去掉〈所〉。“所”后要接动词，“十分好看”是形容词短语，不能用“所”。"}, {"text": "我所的书很多。", "explanation": "这里应该去掉〈所〉。“所”后面要接动词，“的书”结构不能直接用“所”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他所希望事情都实现了。", "corrected_sentence": "他所希望的事情都实现了。", "error_description": "错误：“所”与动词组成的结构后漏了“的”。正确：“所希望的”构成名词性短语，应写作“他所希望的事情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买所的东西都很便宜。", "corrected_sentence": "他所买的东西都很便宜。", "error_description": "错误：“所”放在了“买”和“的”之间。正确：“所”应放在动词“买”之前，写作“所买的东西”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
