INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85758, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词，用在动词前，与“为”“被”等配合，或与动词构成名词性短语。", "primary_collocate": null, "pronunciation": "suǒ", "ipa": "suɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他不为金钱所动。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们为他的勇气所感动。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都为这个消息所吸引。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他所说的话我都记住了。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这就是我所想的办法。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我所认识的人都很好。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你所看到的不是全部。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师所教的内容我听懂了。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是他所买的书。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为这件事所累。", "target_word": "所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "助词：与“为”配合或用在动词前构成名词性短语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d3283c2-c3c9-456b-a54d-b3cbf61747b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85758, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "所", "is_correct": true, "explanation": "所（suǒ）：助词，用在“为……所”结构中表被动，或用在动词前构成名词性短语。"}, {"text": "缩", "is_correct": false, "explanation": "suō（第一声）与 suǒ（第三声）声调不同，意思是收缩。"}, {"text": "梭", "is_correct": false, "explanation": "suō（第一声）与 suǒ（第三声）声调不同，意思是梭子。"}, {"text": "左", "is_correct": false, "explanation": "zuǒ 与 suǒ 声母不同（z 与 s），意思是左边。"}], "explanations": {"所": "所（suǒ）：助词，用在“为……所”结构中表被动，或用在动词前构成名词性短语。", "缩": "suō（第一声）与 suǒ（第三声）声调不同，意思是收缩。", "梭": "suō（第一声）与 suǒ（第三声）声调不同，意思是梭子。", "左": "zuǒ 与 suǒ 声母不同（z 与 s），意思是左边。"}, "sentence_index": null, "correct_answer": "所"}, "level_3": {"options": [{"text": "所", "is_correct": true, "explanation": "所：用在“为……所”结构中，表示被动。"}, {"text": "了", "is_correct": false, "explanation": "体貌：“了”不能插在“为……”与动词之间，“不为金钱了动”不成立。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”表示持续状态，不能插在“为……”与动词之间，“不为金钱着动”不成立。"}, {"text": "的", "is_correct": false, "explanation": "搭配：“的”要连接名词性成分，“金钱的动”不成立。"}], "explanations": {"所": "所：用在“为……所”结构中，表示被动。", "了": "体貌：“了”不能插在“为……”与动词之间，“不为金钱了动”不成立。", "着": "体貌：“着”表示持续状态，不能插在“为……”与动词之间，“不为金钱着动”不成立。", "的": "搭配：“的”要连接名词性成分，“金钱的动”不成立。"}, "sentence_index": 0, "correct_answer": "所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为这件事烦恼所。", "explanation": "这里应该去掉〈所〉，说“他为这件事烦恼”。“所”不能放在句末，后面必须接动词。"}, {"text": "我们所这个方法很好。", "explanation": "这里应该去掉〈所〉，说“我们这个方法很好”。“所”后要紧接动词，“这个方法”是名词短语。"}, {"text": "这件事所很重要。", "explanation": "这里应该去掉〈所〉，说“这件事很重要”。“所”后要接动词，“很重要”是形容词短语，不能用“所”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所", "is_correct": true, "explanation": "所：用在动词前，与“你看到的”构成名词性短语。"}, {"text": "过", "is_correct": false, "explanation": "体貌：“过”表示经历，放在“你”之后说不通。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”要接在形容词或副词后，不能直接跟在代词“你”后面。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问语气，句中不能充当定语。"}], "explanations": {"所": "所：用在动词前，与“你看到的”构成名词性短语。", "过": "体貌：“过”表示经历，放在“你”之后说不通。", "地": "搭配：“地”要接在形容词或副词后，不能直接跟在代词“你”后面。", "吗": "语义：“吗”表示疑问语气，句中不能充当定语。"}, "sentence_index": 6, "correct_answer": "所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他所很快地说话。", "explanation": "这里应该去掉〈所〉。“所”后要接动词，“很快”是副词短语，不能直接放在“所”后。"}, {"text": "她对这件事所累。", "explanation": "这里应该用〈为〉。“所”与“为”配合表示被动，“对”不能与“所”组成被动结构。"}, {"text": "她所为这件事累。", "explanation": "这里应该去掉〈所〉，说“她为这件事累”。“所”不能放在介词“为”之前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这件事所困扰。", "corrected_sentence": "他为这件事所困扰。", "error_description": "错误：“为……所”被动结构漏掉了“为”。正确：应说“他为这件事所困扰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题为大家了所关注。", "corrected_sentence": "这个问题为大家所关注。", "error_description": "错误：“了”插在了“为大家”与“所”之间，破坏了“为……所”结构。正确：应去掉“了”，写作“这个问题为大家所关注。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
