INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85760, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，指示性质、状态、方式或程度。", "primary_collocate": null, "pronunciation": "zhè yàng", "ipa": "ʈʂɤ˥˩ iɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "不要这样说话。", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他为什么这样生气？", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样的天气适合出去玩。", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我从来没见过这样大的鱼。", "target_word": "这样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做，别人会不高兴。", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说话总是这样快，我听不懂。", "target_word": "这样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样的人很少见。", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水果这样便宜，多买一点吧。", "target_word": "这样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这样努力，一定会成功。", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我也想这样学汉语，每天写一页。", "target_word": "这样", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "这样子", "label": "变体"}, {"form": "這樣", "label": "繁体"}], "register": "口语", "sense_fingerprint": "指示代词这样：修饰动词或形容词，指示方式、状态、程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '978170ba-3e1a-45cc-a780-edc5c61ec137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这样", "is_correct": true, "explanation": "“这样”指示说话的方式，“不要这样说话”表示禁止这种说法，语义通顺。"}, {"text": "这些", "is_correct": false, "explanation": "搭配：“这些”只能修饰名词，不能直接修饰动词“说话”。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是问人的疑问代词，不能表示说话的方式，句子不通。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问处所，不能用来指说话的方式，句子不通。"}], "explanations": {"这样": "“这样”指示说话的方式，“不要这样说话”表示禁止这种说法，语义通顺。", "这些": "搭配：“这些”只能修饰名词，不能直接修饰动词“说话”。", "谁": "语义：“谁”是问人的疑问代词，不能表示说话的方式，句子不通。", "哪儿": "语义：“哪儿”问处所，不能用来指说话的方式，句子不通。"}, "sentence_index": 0, "correct_answer": "这样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这样点钱，怎么够用？", "explanation": "这里应该用〈这么点〉。“这样”不与“点”组合表示少量，说钱少要用固定说法“这么点”。"}, {"text": "我们这样不常下雨。", "explanation": "这里应该用〈这里〉。“这样”指性质或做法，不表示地点，说“我们这里”要用“这里”。"}, {"text": "这样都是我的朋友。", "explanation": "这里应该用〈这些〉。“这样”不能指代一群人，指复数要用“这些”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这样", "is_correct": true, "explanation": "“这样的人”指这一类人，修饰名词“人”，句子自然。"}, {"text": "这么", "is_correct": false, "explanation": "搭配：“这么”后要接形容词作程度修饰，如“这么好的人”，不能说“这么的人”。"}, {"text": "那些", "is_correct": false, "explanation": "搭配：“那些”后直接接名词，不能加“的”组成“那些的人”。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样”是疑问代词，问性质，用在陈述句里表示不了“这一类”的意思，句子不通。"}], "explanations": {"这样": "“这样的人”指这一类人，修饰名词“人”，句子自然。", "这么": "搭配：“这么”后要接形容词作程度修饰，如“这么好的人”，不能说“这么的人”。", "那些": "搭配：“那些”后直接接名词，不能加“的”组成“那些的人”。", "怎样": "语义：“怎样”是疑问代词，问性质，用在陈述句里表示不了“这一类”的意思，句子不通。"}, "sentence_index": 6, "correct_answer": "这样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我也想在这样学汉语，每天写一页。", "explanation": "这里应该用〈这里〉。“这样”表示方式，不能表示地点，地点要说“在这里”。"}, {"text": "他这样是老师。", "explanation": "“这样”指示性质或做法，不能用来说明人的身份，这里的用法不对。"}, {"text": "我也想这样八点学汉语。", "explanation": "“这样”表示方式，不表示时刻，说几点要直接说“八点”，这里的用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑这样快，我追不上。", "corrected_sentence": "他跑得这样快，我追不上。", "error_description": "错误：“这样”作程度补语时，动词和补语之间要用“得”连接，漏掉“得”，说成“跑这样快”不通。正确：“跑得这样快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有这样朋友，很幸运。", "corrected_sentence": "她有这样的朋友，很幸运。", "error_description": "错误：“这样”修饰名词时中间要加“的”，应说“这样的朋友”，漏掉“的”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
