INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85766, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "语气助词，用在句末，表示建议、请求、同意或不确定的语气。", "primary_collocate": null, "pronunciation": "ba", "ipa": "pa", "syllable_count": 1, "sentences": [{"text": "你再等一会儿吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好吧，我听你的。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我拿一下书吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服不太贵吧？", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你累了就休息吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就这样吧，我同意。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把门关上吧，外面很吵。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他应该知道这件事吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你给我打个电话吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那就明天再说吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句末语气助词，表示建议、请求、同意或不确定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '978170ba-3e1a-45cc-a780-edc5c61ec137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85766, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吧", "is_correct": true, "explanation": "“吧”（轻声）是句末语气助词，用来表示建议、请求、同意或不确定。"}, {"text": "八", "is_correct": false, "explanation": "bā（第一声）与 ba（轻声）声调不同，意思是数字八。"}, {"text": "爸", "is_correct": false, "explanation": "bà（第四声）与 ba（轻声）声调不同，意思是爸爸。"}, {"text": "把", "is_correct": false, "explanation": "bǎ（第三声）与 ba（轻声）声调不同，意思是拿、握，如“把门关上”。"}, {"text": "吗", "is_correct": false, "explanation": "m 与 b 声母不同，ma 意思是疑问语气助词“吗”。"}], "explanations": {"吧": "“吧”（轻声）是句末语气助词，用来表示建议、请求、同意或不确定。", "八": "bā（第一声）与 ba（轻声）声调不同，意思是数字八。", "爸": "bà（第四声）与 ba（轻声）声调不同，意思是爸爸。", "把": "bǎ（第三声）与 ba（轻声）声调不同，意思是拿、握，如“把门关上”。", "吗": "m 与 b 声母不同，ma 意思是疑问语气助词“吗”。"}, "sentence_index": null, "correct_answer": "吧"}, "level_3": {"options": [{"text": "吧", "is_correct": true, "explanation": "“吧”表示请求或建议，与“你再等一会儿”搭配，语气自然。"}, {"text": "地", "is_correct": false, "explanation": "语义：“地”用于动词前作状语，放在“一会儿”后面不能表示语气，句子不通。"}, {"text": "过", "is_correct": false, "explanation": "体貌：“过”表示曾经发生，不表示劝请，“等一会儿过”不通。"}, {"text": "得", "is_correct": false, "explanation": "配价：“得”后要接补语，“等一会儿得”不能结束句子，不通。"}], "explanations": {"吧": "“吧”表示请求或建议，与“你再等一会儿”搭配，语气自然。", "地": "语义：“地”用于动词前作状语，放在“一会儿”后面不能表示语气，句子不通。", "过": "体貌：“过”表示曾经发生，不表示劝请，“等一会儿过”不通。", "得": "配价：“得”后要接补语，“等一会儿得”不能结束句子，不通。"}, "sentence_index": 0, "correct_answer": "吧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚安吧。", "explanation": "“晚安”是道别的固定用语，不表示建议或不确定，这里加上“吧”不通。"}, {"text": "早上好吧。", "explanation": "“吧”表示建议、请求、同意或不确定，“早上好”是问候语，不表达这些语气，加上“吧”不通。"}, {"text": "欢迎光临吧。", "explanation": "“吧”表示建议、请求、同意或不确定，“欢迎光临”是迎客的固定用语，不表达这些语气，这里用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85766, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吧", "is_correct": true, "explanation": "“吧”（轻声）是句末语气助词，用来表示建议、请求、同意或不确定。"}, {"text": "巴", "is_correct": false, "explanation": "bā（第一声）与 ba（轻声）声调不同，意思是盼望，如“巴不得”。"}, {"text": "拔", "is_correct": false, "explanation": "bá（第二声）与 ba（轻声）声调不同，意思是拔出、拉起。"}, {"text": "霸", "is_correct": false, "explanation": "bà（第四声）与 ba（轻声）声调不同，意思是霸占、强横。"}, {"text": "嘛", "is_correct": false, "explanation": "m 与 b 声母不同，ma 意思是语气助词“嘛”，表示显而易见。"}], "explanations": {"吧": "“吧”（轻声）是句末语气助词，用来表示建议、请求、同意或不确定。", "巴": "bā（第一声）与 ba（轻声）声调不同，意思是盼望，如“巴不得”。", "拔": "bá（第二声）与 ba（轻声）声调不同，意思是拔出、拉起。", "霸": "bà（第四声）与 ba（轻声）声调不同，意思是霸占、强横。", "嘛": "m 与 b 声母不同，ma 意思是语气助词“嘛”，表示显而易见。"}, "sentence_index": null, "correct_answer": "吧"}, "level_3": {"options": [{"text": "吧", "is_correct": true, "explanation": "“吧”表示请求，与“把门关上”搭配，语气自然。"}, {"text": "的", "is_correct": false, "explanation": "语义：“的”不表示语气，“把门关上的”不能构成完整句子，句末不能用“的”。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”表示持续状态，“把门关上着”不通，应说“关着门”。"}, {"text": "得", "is_correct": false, "explanation": "配价：“得”后要接补语，“把门关上得”不能结束句子，不通。"}], "explanations": {"吧": "“吧”表示请求，与“把门关上”搭配，语气自然。", "的": "语义：“的”不表示语气，“把门关上的”不能构成完整句子，句末不能用“的”。", "着": "体貌：“着”表示持续状态，“把门关上着”不通，应说“关着门”。", "得": "配价：“得”后要接补语，“把门关上得”不能结束句子，不通。"}, "sentence_index": 6, "correct_answer": "吧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "谢谢你吧。", "explanation": "表示感谢时不能用“吧”，“吧”表示建议或不确定，应直接说“谢谢你”。"}, {"text": "新年快乐吧。", "explanation": "“吧”表示建议、请求、同意或不确定，“新年快乐”是祝福用语，不表达这些语气，这里用法不对。"}, {"text": "欢迎你吧。", "explanation": "“吧”表示建议、请求、同意或不确定，“欢迎你”是迎接用语，不表达这些语气，加上“吧”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "咱们明天再见面吧了。", "corrected_sentence": "咱们明天再见面吧。", "error_description": "错误：语气助词“吧”后不能再加“了”，“见面吧了”不通。正确：句末只用“吧”，写作“再见面吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天见吧吧。", "corrected_sentence": "我们明天见吧。", "error_description": "错误：句末只用一个“吧”，重复“吧吧”不通。正确：“我们明天见吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a69b8e87-d6cb-486b-8d28-ce325000b2d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
