INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85767, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“如果”是说一件还没有发生的事，要是发生了会怎样。", "primary_collocate": null, "pronunciation": "rú guǒ", "ipa": "ɻu˧˥ kwo˨˩˦", "syllable_count": 2, "sentences": [{"text": "如果明年我有假期，会去日本旅行。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果下个月的考试很难，我会多复习。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果明天我迟到了，请你先开会。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果你忘了带钥匙，可以给我打电话。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果有一天我变成了鸟，会飞到你家。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果太阳明天不出来，会怎么样？", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果孩子明天发烧，我们要马上去医院。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果你把水倒在电脑上，电脑会坏的。", "target_word": "如果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果下班后还有时间，我想去超市买菜。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果电话响了，你先别接，等我回来。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "如果说", "label": "复合"}], "register": "中性", "sense_fingerprint": "如果|连词|还没发生的事，要是发生了会怎样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d46218-0b69-4845-8d22-7c88f2e3105e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如果", "is_correct": true, "explanation": "如果：表示还没发生的假设，引出“明年有假期”这个条件，正确。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，前后应有转折，“有假期”与“去旅行”之间没有让步关系。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”需接在原因分句之后，句首直接用“所以明年我有假期”不成立。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，前文没有需要对比的内容，此句不通。"}], "explanations": {"如果": "如果：表示还没发生的假设，引出“明年有假期”这个条件，正确。", "虽然": "语义：“虽然”表示让步，前后应有转折，“有假期”与“去旅行”之间没有让步关系。", "所以": "搭配：“所以”需接在原因分句之后，句首直接用“所以明年我有假期”不成立。", "但是": "语义：“但是”表示转折，前文没有需要对比的内容，此句不通。"}, "sentence_index": 0, "correct_answer": "如果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如果他昨天迟到了，所以老师生气了。", "explanation": "这里应该用〈因为〉。“如果”表示尚未发生的假设，“昨天迟到了”已经发生，说明原因要用“因为”。"}, {"text": "如果天气很好，所以我们去了公园。", "explanation": "这里应该用〈因为〉。“如果”表示假设，“天气很好”已经成为事实，说明原因要用“因为”，不能与“所以”配合。"}, {"text": "她每天练琴，如果琴技很高，因此被选中了。", "explanation": "这里应该用〈因为〉。“如果”表示假设，“琴技很高”是已经具备的事实，应说“因为琴技很高，所以被选中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "如果", "is_correct": true, "explanation": "如果：表示还没发生的假设，引出“孩子明天发烧”这个条件，正确。"}, {"text": "然而", "is_correct": false, "explanation": "语域：“然而”偏书面，口语中这样用不自然，且前文没有需要转折的内容。"}, {"text": "因此", "is_correct": false, "explanation": "搭配：“因此”引出结果，前文需是原因，“孩子明天发烧”不是前面事件的结果，句子不通。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示转折或补充，句首没有可对比的内容，此句不通。"}], "explanations": {"如果": "如果：表示还没发生的假设，引出“孩子明天发烧”这个条件，正确。", "然而": "语域：“然而”偏书面，口语中这样用不自然，且前文没有需要转折的内容。", "因此": "搭配：“因此”引出结果，前文需是原因，“孩子明天发烧”不是前面事件的结果，句子不通。", "不过": "语义：“不过”表示转折或补充，句首没有可对比的内容，此句不通。"}, "sentence_index": 6, "correct_answer": "如果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很累，如果还在工作。", "explanation": "这里应该用〈但是〉。“但是”表示转折，“他很累”是已知情况，“如果”不能用来引出与之相对的事实。"}, {"text": "他昨天下班后，如果做了晚饭。", "explanation": "这里应该用〈然后〉。“如果”表示假设，“做了晚饭”是已经发生的事，连接先后动作应用“然后”。"}, {"text": "他昨天没有带伞，如果淋湿了，所以感冒了。", "explanation": "这里应该用〈因为〉。“如果”表示假设，“淋湿了”若已发生，导致感冒的原因应用“因为”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "如果我明天没赶上车，所以打车去公司。", "corrected_sentence": "如果我明天没赶上车，就打车去公司。", "error_description": "“如果”与“就”搭配，表示假设及其结果；“所以”表示因果，不能与“如果”配合。正确的是“如果……，就……”，“所以”应改为“就”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "如果你不同意，我们就换过个办法。", "corrected_sentence": "如果你不同意，我们就换个办法。", "error_description": "“换过”带“过”表示已经有过的经历，与尚未发生的假设不合。这里应直接说“就换个办法”，去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
