INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85768, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85768, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示假设，引出一种假定的条件。", "primary_collocate": null, "pronunciation": "rú guǒ", "ipa": "ɻu˧˥ kwo˨˩˦", "syllable_count": 2, "sentences": [{"text": "如果你有时间，请给我打电话。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果明天下雨，我们在家看电影。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果天气好，我们可以去公园玩。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果你不舒服，应该去看医生。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果我有一百万，会先买一套房子。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果你同意这个办法，请在这里写名字。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我会帮你，如果你需要的话。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果不早点儿出发，我们会迟到。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果你住在北京，可以常常来我家吃饭。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果这件衣服太贵，你可以再看看别的。", "target_word": "如果", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "如果说", "label": "复合"}], "register": "中性", "sense_fingerprint": "如果|连词|表示假设，引出假定的条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d46218-0b69-4845-8d22-7c88f2e3105e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如果", "is_correct": true, "explanation": "如果：表示假设，引出“有时间”这个条件，正确。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，前后应有转折，“有时间”与“请打电话”之间没有让步关系。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，“有时间”不是“请打电话”的原因，逻辑不通。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”前面需要有原因分句，句首直接用“所以你有时间”不成立。"}], "explanations": {"如果": "如果：表示假设，引出“有时间”这个条件，正确。", "虽然": "语义：“虽然”表示让步，前后应有转折，“有时间”与“请打电话”之间没有让步关系。", "因为": "语义：“因为”引出原因，“有时间”不是“请打电话”的原因，逻辑不通。", "所以": "搭配：“所以”前面需要有原因分句，句首直接用“所以你有时间”不成立。"}, "sentence_index": 0, "correct_answer": "如果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如果他生病没去，所以错过了比赛。", "explanation": "这里应该用〈因为〉。“如果”表示假设，“生病没去”已经发生，说明原因应用“因为”。"}, {"text": "我昨天不舒服，如果去看了医生。", "explanation": "这里应该用〈就〉。“如果”引出假设，“去看了医生”是已经发生的事，前半句的事实之后应接“就”。"}, {"text": "他每天都很努力，如果成绩很好。", "explanation": "这里应该用〈因此〉。“如果”引出假设条件，不能引出已经发生的结果；“每天都很努力”是事实，结果应用“因此”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "如果", "is_correct": true, "explanation": "如果：表示假设，引出“你需要”这个条件，正确。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，前文“我会帮你”没有需要转折的内容，此句不通。"}, {"text": "然而", "is_correct": false, "explanation": "语域：“然而”偏书面，口语中这样用不自然，且前后没有转折关系。"}, {"text": "因此", "is_correct": false, "explanation": "搭配：“因此”引出结果，前文需是原因，“我会帮你”不能是“你需要”的结果。"}], "explanations": {"如果": "如果：表示假设，引出“你需要”这个条件，正确。", "但是": "语义：“但是”表示转折，前文“我会帮你”没有需要转折的内容，此句不通。", "然而": "语域：“然而”偏书面，口语中这样用不自然，且前后没有转折关系。", "因此": "搭配：“因此”引出结果，前文需是原因，“我会帮你”不能是“你需要”的结果。"}, "sentence_index": 6, "correct_answer": "如果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气很冷，如果大家都很高兴。", "explanation": "这里应该用〈但是〉。“但是”表示转折，“天气很冷”是事实，“如果”只用于假设，不能引出相反的事实。"}, {"text": "他昨天去了超市，如果买了很多东西。", "explanation": "这里应该用〈并且〉。“如果”表示假设，“买了很多东西”是已经发生的事，两件事并列应用“并且”。"}, {"text": "他很累，如果还在坚持。", "explanation": "这里应该用〈不过〉。“不过”表示转折，“很累”是已知情况，“如果”不能表示与此相对的事实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "如果明天下雨，我们如果就在家休息。", "corrected_sentence": "如果明天下雨，我们就在家休息。", "error_description": "错误：主句「我们如果就在家休息」中多用了一个「如果」。「如果」只用于假设分句，主句不再重复。正确：应为「如果明天下雨，我们就在家休息」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "如果你觉得累，所以先休息一下。", "corrected_sentence": "如果你觉得累，就先休息一下。", "error_description": "错误：「所以」表示因果，不能与假设连词「如果」配合。「如果」应与副词「就」呼应，表示假设及其结果。正确：应为「如果你觉得累，就先休息一下」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22909aee-8ab6-4564-b54a-a5aaac9fc24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
