INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85773, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“只”用来数小鸟、小猫这样的小动物。", "primary_collocate": null, "pronunciation": "zhī", "ipa": "ʈʂɨ˥", "syllable_count": 1, "sentences": [{"text": "树上有一只小鸟。", "target_word": "只", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家有两只小猫。", "target_word": "只", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "草地上跑着一只小兔子。", "target_word": "只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天买了三只小鸡。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗台上停着一只蝴蝶。", "target_word": "只", "complexity_tier": "T3", "furigana": "chuāng tái shàng tíng zhe yì zhī hú dié", "sentence_source": "generated"}, {"text": "墙角有一只小老鼠。", "target_word": "只", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "池塘边有一只小青蛙。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一只小蚂蚁爬到我的手上。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只小猫在沙发上睡觉。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院子里有五只小鸭子。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "隻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "量词，用于数小鸟、小猫等小动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fb035c5-9777-447c-8d06-6c17b4aedd72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85773, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "只", "is_correct": true, "explanation": "只（zhī，第一声）：量词，用于数小鸟、小猫等小动物，是正确答案。"}, {"text": "纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸张。"}, {"text": "指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是手指。"}, {"text": "志", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是志向。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是笔直。"}, {"text": "吃", "is_correct": false, "explanation": "chī 与 zhī 声母不同（ch 与 zh），声调相同，意思是吃。"}, {"text": "资", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是资源。"}], "explanations": {"只": "只（zhī，第一声）：量词，用于数小鸟、小猫等小动物，是正确答案。", "纸": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸张。", "指": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是手指。", "志": "zhì（第四声）与 zhī（第一声）声调不同，意思是志向。", "直": "zhí（第二声）与 zhī（第一声）声调不同，意思是笔直。", "吃": "chī 与 zhī 声母不同（ch 与 zh），声调相同，意思是吃。", "资": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是资源。"}, "sentence_index": null, "correct_answer": "只"}, "level_3": {"options": [{"text": "只", "is_correct": true, "explanation": "只：量词，用于小鸟等小动物，与“一只小鸟”搭配，是正确答案。"}, {"text": "棵", "is_correct": false, "explanation": "搭配：“棵”用于树木、植物，不能用来数小鸟。"}, {"text": "朵", "is_correct": false, "explanation": "搭配：“朵”多用于花、云，与小鸟不搭。"}, {"text": "位", "is_correct": false, "explanation": "语义：“位”表示对人的敬称，小鸟不是人，此处意思不合。"}], "explanations": {"只": "只：量词，用于小鸟等小动物，与“一只小鸟”搭配，是正确答案。", "棵": "搭配：“棵”用于树木、植物，不能用来数小鸟。", "朵": "搭配：“朵”多用于花、云，与小鸟不搭。", "位": "语义：“位”表示对人的敬称，小鸟不是人，此处意思不合。"}, "sentence_index": 0, "correct_answer": "只"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天买了三只书。", "explanation": "这里应该用〈本〉。书用量词“本”，“只”只用于小动物或成对物品中的一个。"}, {"text": "他昨天买了三只电脑。", "explanation": "这里应该用〈台〉。电脑用量词“台”，“只”不能用于电脑。"}, {"text": "他昨天买了三只椅子。", "explanation": "这里应该用〈把〉。椅子用量词“把”，“只”不能用于椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85773, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "只", "is_correct": true, "explanation": "只（zhī，第一声）：量词，用于数池塘边的青蛙等小动物，是正确答案。"}, {"text": "止", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是停止。"}, {"text": "至", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是到达。"}, {"text": "职", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是职业。"}, {"text": "诗", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是诗歌。"}, {"text": "师", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是老师。"}, {"text": "失", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是丢失。"}], "explanations": {"只": "只（zhī，第一声）：量词，用于数池塘边的青蛙等小动物，是正确答案。", "止": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是停止。", "至": "zhì（第四声）与 zhī（第一声）声调不同，意思是到达。", "职": "zhí（第二声）与 zhī（第一声）声调不同，意思是职业。", "诗": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是诗歌。", "师": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是老师。", "失": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是丢失。"}, "sentence_index": null, "correct_answer": "只"}, "level_3": {"options": [{"text": "只", "is_correct": true, "explanation": "只：量词，用于青蛙等小动物，与“一只小青蛙”搭配，是正确答案。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西、鱼蛇等，不能用来数小青蛙。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”用于书籍，青蛙不是书，此处意思不合。"}, {"text": "座", "is_correct": false, "explanation": "体貌：“座”指大型、固定不动的东西，与小而会跳的青蛙不合。"}], "explanations": {"只": "只：量词，用于青蛙等小动物，与“一只小青蛙”搭配，是正确答案。", "条": "搭配：“条”用于细长的东西、鱼蛇等，不能用来数小青蛙。", "本": "语义：“本”用于书籍，青蛙不是书，此处意思不合。", "座": "体貌：“座”指大型、固定不动的东西，与小而会跳的青蛙不合。"}, "sentence_index": 6, "correct_answer": "只"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一只很好的老师。", "explanation": "这里应该用〈个〉。指人要用量词“个”，“只”只用于小动物或成对物品中的一个。"}, {"text": "他买了一只裤子。", "explanation": "这里应该用〈条〉。裤子用量词“条”，“只”不能用于裤子。"}, {"text": "我家门口有一只树。", "explanation": "这里应该用〈棵〉。树用量词“棵”，“只”只用于小动物或成对物品中的一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家买了两只书。", "corrected_sentence": "他家买了两本书。", "error_description": "量词用错。书用量词“本”，“只”不能用于书。错误形式为“他家买了两只书”，正确形式为“他家买了两本书。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖边停着两只的白鹅。", "corrected_sentence": "湖边停着两只白鹅。", "error_description": "量词后多加了“的”。“两只白鹅”中“白”直接修饰“鹅”，“两只”后不能加“的”，写成“两只的白鹅”不成词组。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
