INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85774, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于某些动物、成对物品中的一个等。", "primary_collocate": null, "pronunciation": "zhī", "ipa": "ʈʂɨ˥", "syllable_count": 1, "sentences": [{"text": "他一只手拿着书包。", "target_word": "只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到另一只鞋。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她丢了一只耳环。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只袜子有一个洞。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的一只眼睛看不清。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里有一只大老虎。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农场里有十只羊。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我戴了一只手套。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的两只耳朵都很红。", "target_word": "只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上飞着一只老鹰。", "target_word": "只", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "量词，用于某些动物或成对物品中的一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fb035c5-9777-447c-8d06-6c17b4aedd72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id