INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85774, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "只", "is_correct": true, "explanation": "只（zhī，第一声）：量词，用于成对物品中的一个，是正确答案。"}, {"text": "志", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是志向。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是笔直。"}, {"text": "吃", "is_correct": false, "explanation": "chī 与 zhī 声母不同（ch 与 zh），声调相同，意思是吃。"}, {"text": "资", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是资源。"}, {"text": "诗", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是诗歌。"}, {"text": "纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸张。"}], "explanations": {"只": "只（zhī，第一声）：量词，用于成对物品中的一个，是正确答案。", "志": "zhì（第四声）与 zhī（第一声）声调不同，意思是志向。", "直": "zhí（第二声）与 zhī（第一声）声调不同，意思是笔直。", "吃": "chī 与 zhī 声母不同（ch 与 zh），声调相同，意思是吃。", "资": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是资源。", "诗": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是诗歌。", "纸": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸张。"}, "sentence_index": null, "correct_answer": "只"}, "level_3": {"options": [{"text": "只", "is_correct": true, "explanation": "只：量词，表示成对器官或物品中的一个，与“一只手”搭配，是正确答案。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，不能用来数手。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，手不是平面物，不能这样数。"}, {"text": "位", "is_correct": false, "explanation": "语义：“位”表示对人的敬称，手不是人，此处意思不合。"}], "explanations": {"只": "只：量词，表示成对器官或物品中的一个，与“一只手”搭配，是正确答案。", "条": "搭配：“条”用于细长的东西，不能用来数手。", "张": "搭配：“张”用于平面的东西，手不是平面物，不能这样数。", "位": "语义：“位”表示对人的敬称，手不是人，此处意思不合。"}, "sentence_index": 0, "correct_answer": "只"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只房子。", "explanation": "这里应该用〈栋〉。房子用量词“栋”或“座”，“只”用于小动物或成对物品中的一个。"}, {"text": "他搬来一只桌子。", "explanation": "这里应该用〈张〉。桌子用量词“张”，“只”不能用于桌子。"}, {"text": "他买了一只电视。", "explanation": "这里应该用〈台〉。电视用量词“台”，“只”不能用于电视。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85774, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "只", "is_correct": true, "explanation": "只（zhī，第一声）：量词，用于成对物品中的一个，是正确答案。"}, {"text": "指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是手指。"}, {"text": "至", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是到达。"}, {"text": "职", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是职业。"}, {"text": "师", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是老师。"}, {"text": "失", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是丢失。"}, {"text": "滋", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是滋润。"}], "explanations": {"只": "只（zhī，第一声）：量词，用于成对物品中的一个，是正确答案。", "指": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是手指。", "至": "zhì（第四声）与 zhī（第一声）声调不同，意思是到达。", "职": "zhí（第二声）与 zhī（第一声）声调不同，意思是职业。", "师": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是老师。", "失": "shī 与 zhī 声母不同（sh 与 zh），声调相同，意思是丢失。", "滋": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是滋润。"}, "sentence_index": null, "correct_answer": "只"}, "level_3": {"options": [{"text": "只", "is_correct": true, "explanation": "只：量词，用于羊等小动物，与“十只羊”搭配，是正确答案。"}, {"text": "棵", "is_correct": false, "explanation": "搭配：“棵”用于树木、植物，不能用来数羊。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”用于书籍，羊不是书，此处意思不合。"}, {"text": "座", "is_correct": false, "explanation": "体貌：“座”指大型、固定不动的东西，与会走动的羊不合。"}], "explanations": {"只": "只：量词，用于羊等小动物，与“十只羊”搭配，是正确答案。", "棵": "搭配：“棵”用于树木、植物，不能用来数羊。", "本": "语义：“本”用于书籍，羊不是书，此处意思不合。", "座": "体貌：“座”指大型、固定不动的东西，与会走动的羊不合。"}, "sentence_index": 6, "correct_answer": "只"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是一只很认真的医生。", "explanation": "这里应该用〈个〉。指人要用量词“个”，“只”只用于小动物或成对物品中的一个。"}, {"text": "院子里种着一只树。", "explanation": "这里应该用〈棵〉。树用量词“棵”，“只”不能用于树。"}, {"text": "前面有一只路。", "explanation": "这里应该用〈条〉。路用量词“条”，“只”不能用于路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她落下了一个只袜子。", "corrected_sentence": "她落下了一只袜子。", "error_description": "量词多加了一个。“一只袜子”中只用“只”，前面不能再加“个”，写成“一个只袜子”属于量词重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的右手戴着一只的手套。", "corrected_sentence": "他的右手戴着一只手套。", "error_description": "“只”后多加了“的”。“一只手套”中数量短语直接修饰名词，中间不能加“的”，写成“一只的手套”不成词组。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
