INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85787, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“第”放在数字前面，用来说排在哪一个。", "primary_collocate": null, "pronunciation": "dì", "ipa": "ti˥˩", "syllable_count": 1, "sentences": [{"text": "他在比赛中得了第一名。", "target_word": "第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请打开书的第十页。", "target_word": "第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家住在第五层。", "target_word": "第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我第一次来北京。", "target_word": "第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第二天早上，我们去爬山。", "target_word": "第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的第三节课是语文课。", "target_word": "第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们班第一个到的人。", "target_word": "第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你坐在第二排的座位上。", "target_word": "第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是他第四次迟到了。", "target_word": "第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在第三个路口往右走。", "target_word": "第", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "第一", "label": "复合"}], "register": "中性", "sense_fingerprint": "序数前缀：放在数字前表示次序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f52a792-026e-4f8e-a395-edf1e5ec92ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85787, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "第", "is_correct": true, "explanation": "第（dì）表示次序，如“第一名”，正是听到的读音。"}, {"text": "低", "is_correct": false, "explanation": "低（dī）与第（dì）声调不同（一声与四声），意思是高低的“低”。"}, {"text": "底", "is_correct": false, "explanation": "底（dǐ）与第（dì）声调不同（三声与四声），意思是底部。"}, {"text": "替", "is_correct": false, "explanation": "替（tì）与第（dì）声母不同（t 与 d），声调相同，意思是替代。"}, {"text": "立", "is_correct": false, "explanation": "立（lì）与第（dì）声母不同（l 与 d），声调相同，意思是站立。"}], "explanations": {"第": "第（dì）表示次序，如“第一名”，正是听到的读音。", "低": "低（dī）与第（dì）声调不同（一声与四声），意思是高低的“低”。", "底": "底（dǐ）与第（dì）声调不同（三声与四声），意思是底部。", "替": "替（tì）与第（dì）声母不同（t 与 d），声调相同，意思是替代。", "立": "立（lì）与第（dì）声母不同（l 与 d），声调相同，意思是站立。"}, "sentence_index": null, "correct_answer": "第"}, "level_3": {"options": [{"text": "第", "is_correct": true, "explanation": "第用在数字前表示次序，“第一名”即名次第一，与“得了”搭配，符合句意。"}, {"text": "末", "is_correct": false, "explanation": "语义：“末”指最后，“得了末一名”的意思与比赛获胜的语境相反。"}, {"text": "次", "is_correct": false, "explanation": "搭配：“次”不作次序前缀，表示名次要说“第”，不能说“次一名”。"}, {"text": "老", "is_correct": false, "explanation": "搭配：“老”只接“老三”“老大”等排行，不能说“老一名”。"}], "explanations": {"第": "第用在数字前表示次序，“第一名”即名次第一，与“得了”搭配，符合句意。", "末": "语义：“末”指最后，“得了末一名”的意思与比赛获胜的语境相反。", "次": "搭配：“次”不作次序前缀，表示名次要说“第”，不能说“次一名”。", "老": "搭配：“老”只接“老三”“老大”等排行，不能说“老一名”。"}, "sentence_index": 0, "correct_answer": "第"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了第三斤苹果。", "explanation": "“第”只表示次序，这里却用来修饰计量单位，把次序义和数量义混用了；表示数量时不能加“第”。"}, {"text": "第四分之一的同学没来。", "explanation": "“第”只表示次序，分数表示部分，属于数量义，前面不能加“第”。"}, {"text": "他今年第五岁了。", "explanation": "“第”只表示次序，年龄属于数量义，不能用次序义的“第”来修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85787, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "第", "is_correct": true, "explanation": "第（dì）表示次序，如“第一个”，正是听到的读音。"}, {"text": "敌", "is_correct": false, "explanation": "敌（dí）与第（dì）声调不同（二声与四声），意思是敌人。"}, {"text": "抵", "is_correct": false, "explanation": "抵（dǐ）与第（dì）声调不同（三声与四声），意思是抵挡。"}, {"text": "逆", "is_correct": false, "explanation": "逆（nì）与第（dì）声母不同（n 与 d），声调相同，意思是相反、逆向。"}, {"text": "利", "is_correct": false, "explanation": "利（lì）与第（dì）声母不同（l 与 d），声调相同，意思是锋利、利益。"}], "explanations": {"第": "第（dì）表示次序，如“第一个”，正是听到的读音。", "敌": "敌（dí）与第（dì）声调不同（二声与四声），意思是敌人。", "抵": "抵（dǐ）与第（dì）声调不同（三声与四声），意思是抵挡。", "逆": "逆（nì）与第（dì）声母不同（n 与 d），声调相同，意思是相反、逆向。", "利": "利（lì）与第（dì）声母不同（l 与 d），声调相同，意思是锋利、利益。"}, "sentence_index": null, "correct_answer": "第"}, "level_3": {"options": [{"text": "第", "is_correct": true, "explanation": "第表示次序，“第一个到”即最先到达的人，符合句意。"}, {"text": "每", "is_correct": false, "explanation": "语义：“每”指全部，“每一个到的人”与“最先到”的句意矛盾。"}, {"text": "末", "is_correct": false, "explanation": "语义：“末”指最后，“末一个到的人”与“最先到”的句意矛盾。"}, {"text": "初", "is_correct": false, "explanation": "搭配：“初”只用于“初一、初二”等日期，不能说“初一个到的人”。"}], "explanations": {"第": "第表示次序，“第一个到”即最先到达的人，符合句意。", "每": "语义：“每”指全部，“每一个到的人”与“最先到”的句意矛盾。", "末": "语义：“末”指最后，“末一个到的人”与“最先到”的句意矛盾。", "初": "搭配：“初”只用于“初一、初二”等日期，不能说“初一个到的人”。"}, "sentence_index": 6, "correct_answer": "第"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我早上第六点起床。", "explanation": "时刻要说“六点”，“第”只表示次序，不能放在时刻前。"}, {"text": "他花了第三十块钱。", "explanation": "“第”只表示次序，“三十块钱”是数量，不能加“第”。"}, {"text": "他家有第三口人。", "explanation": "“三口人”是人口数量，“第”不能加在数量词前表示次序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是他第两次迟到了。", "corrected_sentence": "这是他第二次迟到了。", "error_description": "“第”后面要接序数“二”，不用“两”。“第两次”是错的，应为“第二次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我们班一第名。", "corrected_sentence": "他是我们班第一名。", "error_description": "“第”要放在数词前面，“一第名”语序颠倒，应为“第一名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceef970f-af3b-467f-952b-04ff70b5cb30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
