INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85801, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“号”是排定的序数，用于房间、楼、窗口、车辆等的编号，也用于表示每月的第几天。", "primary_collocate": null, "pronunciation": "hào", "ipa": "xɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "今天是五号。", "target_word": "号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我住在三号楼。", "target_word": "号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的房间是八号。", "target_word": "号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的生日是十月九号。", "target_word": "号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下个月十号我们去北京。", "target_word": "号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请到二号窗口交钱。", "target_word": "号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家在中山路十二号。", "target_word": "号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿着七号球衣上场。", "target_word": "号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道今天是几号吗？", "target_word": "号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我坐三号车去学校。", "target_word": "号", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表示房间、楼、日期的序号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fb035c5-9777-447c-8d06-6c17b4aedd72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85801, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "号", "is_correct": true, "explanation": "号（hào，第四声）：表示房间、楼、日期等次序的数字，是正确答案。"}, {"text": "好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是好。"}, {"text": "毫", "is_correct": false, "explanation": "háo（第二声）与 hào（第四声）声调不同，意思是毫米。"}, {"text": "厚", "is_correct": false, "explanation": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是厚。"}, {"text": "豪", "is_correct": false, "explanation": "háo（第二声）与 hào（第四声）声调不同，意思是豪迈。"}], "explanations": {"号": "号（hào，第四声）：表示房间、楼、日期等次序的数字，是正确答案。", "好": "hǎo（第三声）与 hào（第四声）声调不同，意思是好。", "毫": "háo（第二声）与 hào（第四声）声调不同，意思是毫米。", "厚": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是厚。", "豪": "háo（第二声）与 hào（第四声）声调不同，意思是豪迈。"}, "sentence_index": null, "correct_answer": "号"}, "level_3": {"options": [{"text": "号", "is_correct": true, "explanation": "号：表示日期的序数，“今天是五号”中用它，是正确答案。"}, {"text": "楼", "is_correct": false, "explanation": "语义：“楼”指建筑或楼层，不能用来表示日期，“今天是五楼”不通。"}, {"text": "班", "is_correct": false, "explanation": "搭配：“今天是”后接日期序数，不接“班”这类班级名称。"}, {"text": "车", "is_correct": false, "explanation": "语义：“车”指交通工具，与表示日期的“今天是”不合。"}], "explanations": {"号": "号：表示日期的序数，“今天是五号”中用它，是正确答案。", "楼": "语义：“楼”指建筑或楼层，不能用来表示日期，“今天是五楼”不通。", "班": "搭配：“今天是”后接日期序数，不接“班”这类班级名称。", "车": "语义：“车”指交通工具，与表示日期的“今天是”不合。"}, "sentence_index": 0, "correct_answer": "号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今年三号岁了。", "explanation": "这里应该用〈岁〉。表示年龄要说“岁”，“号”表示编号或次序，不能表示年龄。"}, {"text": "他号了我的电话。", "explanation": "这里应该用〈记〉。表示记下号码要说“记”，“号”作动词只用于号脉、号令、号召等，不能表示记下号码。"}, {"text": "这次考试我考了三号。", "explanation": "这里应该用〈分〉。考试成绩用“分”，“号”表示编号或次序，不能表示分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85801, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "号", "is_correct": true, "explanation": "号（hào，第四声）：表示房间、楼、日期等次序的数字，是正确答案。"}, {"text": "后", "is_correct": false, "explanation": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是后面。"}, {"text": "候", "is_correct": false, "explanation": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是等候。"}, {"text": "害", "is_correct": false, "explanation": "hài 与 hào 只有韵母不同（ai 与 ao），声调相同，意思是伤害。"}, {"text": "嚎", "is_correct": false, "explanation": "háo（第二声）与 hào（第四声）声调不同，意思是大声哭叫。"}], "explanations": {"号": "号（hào，第四声）：表示房间、楼、日期等次序的数字，是正确答案。", "后": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是后面。", "候": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是等候。", "害": "hài 与 hào 只有韵母不同（ai 与 ao），声调相同，意思是伤害。", "嚎": "háo（第二声）与 hào（第四声）声调不同，意思是大声哭叫。"}, "sentence_index": null, "correct_answer": "号"}, "level_3": {"options": [{"text": "号", "is_correct": true, "explanation": "号：门牌或地址中的序数，“中山路十二号”中用它，是正确答案。"}, {"text": "年", "is_correct": false, "explanation": "语义：“年”表示时间段，不能用作门牌号，“中山路十二年”不通。"}, {"text": "课", "is_correct": false, "explanation": "搭配：地址中接在路名后的是门牌序号，不说“课”。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：“瓶”是容器，不能用作门牌号，此处意思不合。"}], "explanations": {"号": "号：门牌或地址中的序数，“中山路十二号”中用它，是正确答案。", "年": "语义：“年”表示时间段，不能用作门牌号，“中山路十二年”不通。", "课": "搭配：地址中接在路名后的是门牌序号，不说“课”。", "瓶": "语义：“瓶”是容器，不能用作门牌号，此处意思不合。"}, "sentence_index": 6, "correct_answer": "号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请输入你的密号。", "explanation": "这里应该用〈码〉。“密码”是固定说法，“号”表示次序或编号，不能说“密号”。"}, {"text": "我去过三号北京。", "explanation": "这里应该用〈次〉。表示动作的次数要用“次”，“号”不能用来计数动作。"}, {"text": "她的头发有三号长。", "explanation": "这里应该用〈厘米〉。长度要用“厘米”等单位，“号”表示编号，不能表示长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我住在八个号楼。", "corrected_sentence": "我住在八号楼。", "error_description": "序号前多加了量词。“八号楼”是固定说法，“号”前不能加“个”，应说“八号楼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请问，这是号几房间？", "corrected_sentence": "请问，这是几号房间？", "error_description": "“号”与“几”位置颠倒。应说“几号房间”，疑问词“几”要在“号”前面，不能说“号几房间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
