INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85803, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“这种”是指这一类的人或东西。", "primary_collocate": null, "pronunciation": "zhè zhǒng", "ipa": "ʈʂɤ˥˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种动物住在很冷的地方。", "target_word": "这种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种笔写字很快。", "target_word": "这种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种衣服夏天穿最好。", "target_word": "这种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近有很多这种小店。", "target_word": "这种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种茶对身体好。", "target_word": "这种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们都爱听这种音乐。", "target_word": "这种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种车比那种车便宜。", "target_word": "这种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种小事不用告诉妈妈。", "target_word": "这种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种面包是我自己做的。", "target_word": "这种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鱼只在海里生活。", "target_word": "这种", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "這種", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指这一类的人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f540895-15ac-4157-a79d-ae398b16a32b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85803, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪种", "is_correct": false, "explanation": "语义：“哪种”是疑问词，陈述句中不能用来指“这一类”。"}, {"text": "这种", "is_correct": true, "explanation": "正确：指“这一类”动物，符合语境。"}, {"text": "这块", "is_correct": false, "explanation": "量词：“块”不能用于动物，不说“这块动物”。"}, {"text": "每种", "is_correct": false, "explanation": "语义：“每种”指所有种类，说每种动物都住在寒冷地方与常识不符。"}], "explanations": {"哪种": "语义：“哪种”是疑问词，陈述句中不能用来指“这一类”。", "这种": "正确：指“这一类”动物，符合语境。", "这块": "量词：“块”不能用于动物，不说“这块动物”。", "每种": "语义：“每种”指所有种类，说每种动物都住在寒冷地方与常识不符。"}, "sentence_index": 0, "correct_answer": "这种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种太阳今天很热。", "explanation": "这里应该用〈这个〉。太阳只有一个，指它不能用“这种”，“这种”只指一类事物。"}, {"text": "这种月亮今天很圆。", "explanation": "这里应该用〈这轮〉。月亮只有一轮，指特定的月亮要用“这轮”，不能用“这种”。"}, {"text": "这种长江很长。", "explanation": "这里应该用〈这条〉。长江只有一条，指特定的河不能用“这种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27554354-df62-4d0b-802c-500ae638645d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪些", "is_correct": false, "explanation": "语义：“哪些”是疑问词，不能用来陈述“车比那种车便宜”。"}, {"text": "这种", "is_correct": true, "explanation": "正确：指“这一类”车，符合语境。"}, {"text": "这块", "is_correct": false, "explanation": "量词：车用“辆”，不说“这块车”。"}, {"text": "各种", "is_correct": false, "explanation": "语义：各种车都比那种车便宜，与语境不符。"}], "explanations": {"哪些": "语义：“哪些”是疑问词，不能用来陈述“车比那种车便宜”。", "这种": "正确：指“这一类”车，符合语境。", "这块": "量词：车用“辆”，不说“这块车”。", "各种": "语义：各种车都比那种车便宜，与语境不符。"}, "sentence_index": 6, "correct_answer": "这种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种地球我们一起去看吧。", "explanation": "这里应该用〈这个〉。地球只有一个，指它不能用“这种”。"}, {"text": "这种泰山我们明天去爬。", "explanation": "这里应该用〈这座〉。泰山是特定的山，指它要用“这座”，不能用“这种”。"}, {"text": "这种中国我很喜欢。", "explanation": "这里应该用〈这个国家〉。中国是特定的国家，不能用“这种”指它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27554354-df62-4d0b-802c-500ae638645d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种的笔我用了很久。", "corrected_sentence": "这种笔我用了很久。", "error_description": "助词错误：“这种”后面不加“的”，应说“这种笔”；“的”只用于“这样的”这类结构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27554354-df62-4d0b-802c-500ae638645d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鱼们我吃过两次。", "corrected_sentence": "这种鱼我吃过两次。", "error_description": "名词错误：“们”只用于指人的名词，不能加在“鱼”后面，应说“这种鱼”，不能说“这种鱼们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27554354-df62-4d0b-802c-500ae638645d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
