INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85805, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“你们”是对面前两个或更多人说话时的叫法。", "primary_collocate": null, "pronunciation": "nǐ men", "ipa": "ni˨˩˦ mən", "syllable_count": 2, "sentences": [{"text": "你们今天想吃什么？", "target_word": "你们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们都是我的好朋友。", "target_word": "你们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对你们说了什么？", "target_word": "你们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们先走，我随后就到。", "target_word": "你们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是给你们的礼物。", "target_word": "你们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们昨天去哪儿了？", "target_word": "你们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们俩是同学吗？", "target_word": "你们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请你们帮个忙。", "target_word": "你们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们学校离这儿远不远？", "target_word": "你们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们别担心，我没事。", "target_word": "你们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "你們", "label": "繁体"}], "register": "口语", "sense_fingerprint": "代词：当面称呼两人或多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d3283c2-c3c9-456b-a54d-b3cbf61747b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85805, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "你们", "is_correct": true, "explanation": "正确。“你们”是对多位听话人的称呼，可以作“想吃什么”的主语。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指事物，事物不会“想吃什么”。"}, {"text": "这些", "is_correct": false, "explanation": "语义：“这些”指事物，不指能想吃东西的人。"}, {"text": "那些", "is_correct": false, "explanation": "搭配：“那些”指物，不与指人的“想吃什么”搭配作主语。"}], "explanations": {"你们": "正确。“你们”是对多位听话人的称呼，可以作“想吃什么”的主语。", "它们": "语义：“它们”指事物，事物不会“想吃什么”。", "这些": "语义：“这些”指事物，不指能想吃东西的人。", "那些": "搭配：“那些”指物，不与指人的“想吃什么”搭配作主语。"}, "sentence_index": 0, "correct_answer": "你们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你们一个人住在这儿吗？", "explanation": "这里应该用〈你〉。“一个人”只有一位听话人，“你们”指两人或以上。"}, {"text": "小明和小红昨天去了公园，你们玩得很开心。", "explanation": "这里应该用〈他们〉。小明和小红不是听话人、也不在场，说到不在场的人应用“他们”，“你们”只指当面的听话人。"}, {"text": "我昨天和妈妈去了超市，你们买了很多东西。", "explanation": "这里应该用〈我们〉。说话人也参加了这件事，“你们”不包括说话人，应用“我们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "你们", "is_correct": true, "explanation": "正确。“你们俩”是对两位听话人的称呼，符合“是同学吗”的提问对象。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指全体，不能与数量词“俩”组合，“大家俩”不成立。"}, {"text": "同学们", "is_correct": false, "explanation": "搭配：“同学们”已表复数，不能再接“俩”，“同学们俩”不成立。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”是反身代词，指主语本人，不能指对面的两位听话人，“自己俩”不成立。"}], "explanations": {"你们": "正确。“你们俩”是对两位听话人的称呼，符合“是同学吗”的提问对象。", "大家": "搭配：“大家”指全体，不能与数量词“俩”组合，“大家俩”不成立。", "同学们": "搭配：“同学们”已表复数，不能再接“俩”，“同学们俩”不成立。", "自己": "语义：“自己”是反身代词，指主语本人，不能指对面的两位听话人，“自己俩”不成立。"}, "sentence_index": 6, "correct_answer": "你们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子是你们的，你们很结实。", "explanation": "这里应该用〈它〉。“你们”只指人，不能指桌子。"}, {"text": "我昨天买了一台电脑，你们的内存很大。", "explanation": "这里应该用〈它的〉。“你们的”只指听话人，不能指电脑。"}, {"text": "桌子上有三本书，你们都是我的。", "explanation": "这里应该用〈它们〉。“你们”只指人，不能指书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你们一个人去超市吗？", "corrected_sentence": "你一个人去超市吗？", "error_description": "错误形式：“你们一个人”；正确形式：“你一个人”。“你们”指两人或以上，与“一个人”矛盾，应用单数“你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你们一个是同学吗？", "corrected_sentence": "你们俩是同学吗？", "error_description": "错误形式：“你们一个”；正确形式：“你们俩”。“你们”指两人或以上，不能与“一个”搭配，应用数量词“俩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
