INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85820, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85820, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示因果关系中的结果，常与“因为”配合使用。", "primary_collocate": null, "pronunciation": "suǒ yǐ", "ipa": "suɔ˨˩ i˨˩", "syllable_count": 2, "sentences": [{"text": "因为下雨，所以我没出门。", "target_word": "所以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很累，所以早早睡了。", "target_word": "所以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为路上堵车，所以我迟到了。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很冷，所以我穿了大衣。", "target_word": "所以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为我喜欢吃面，所以常去那家店。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她感冒了，所以今天没来上课。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为明天考试，所以我今晚复习。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太忙，所以没有时间看电影。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为房子很大，所以租金很高。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没带钱，所以什么也没买。", "target_word": "所以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词，与“因为”配合，引出结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fb035c5-9777-447c-8d06-6c17b4aedd72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所以", "is_correct": true, "explanation": "正确：“因为下雨”引出原因，“所以”接结果“我没出门”，是固定的因果搭配。"}, {"text": "但是", "is_correct": false, "explanation": "搭配：“因为”表原因，与表转折的“但是”不能配对，此处应用“所以”。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，不能引出因果结果。"}, {"text": "如果", "is_correct": false, "explanation": "搭配：“因为”引出已发生的事实，不能与表假设的“如果”配合。"}], "explanations": {"所以": "正确：“因为下雨”引出原因，“所以”接结果“我没出门”，是固定的因果搭配。", "但是": "搭配：“因为”表原因，与表转折的“但是”不能配对，此处应用“所以”。", "然后": "语义：“然后”表示先后顺序，不能引出因果结果。", "如果": "搭配：“因为”引出已发生的事实，不能与表假设的“如果”配合。"}, "sentence_index": 0, "correct_answer": "所以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很努力，所以没考好。", "explanation": "这里应该用〈但是〉。“努力”与“没考好”是转折关系，“所以”只表示因果结果，用在这里说法错误。"}, {"text": "他吃完饭，所以去了图书馆。", "explanation": "这里应该用〈然后〉。前后是先后顺序，不是因果，“所以”把两个动作硬说成了因果。"}, {"text": "他会说英语，所以也会说法语。", "explanation": "这里应该用〈而且〉。这是递进补充，不是因果，“所以”在这里用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所以", "is_correct": true, "explanation": "正确：“因为明天考试”是原因，“所以”引出“我今晚复习”这一结果。"}, {"text": "不过", "is_correct": false, "explanation": "搭配：“不过”表转折，与“因为”引出的原因不配合。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”表让步，要与“但是”或“却”配合，不能接在“因为”之后。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”表示补充理由，不表示由原因得出的结果。"}], "explanations": {"所以": "正确：“因为明天考试”是原因，“所以”引出“我今晚复习”这一结果。", "不过": "搭配：“不过”表转折，与“因为”引出的原因不配合。", "虽然": "搭配：“虽然”表让步，要与“但是”或“却”配合，不能接在“因为”之后。", "况且": "语义：“况且”表示补充理由，不表示由原因得出的结果。"}, "sentence_index": 6, "correct_answer": "所以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们等了很久，所以他没来。", "explanation": "这里应该用〈却〉。“却”引出出乎意料的结局，不表示因果；“所以”把“没来”说成“等了很久”的原因，两者没有因果，用在这里说法不通。"}, {"text": "他不是老师，所以是医生。", "explanation": "这里应该用〈而是〉。前半句否定，后半句是更正，不是因果，“所以”不能这样用。"}, {"text": "他一边跑步，所以听音乐。", "explanation": "这里应该用〈同时〉。两个动作是同时进行的并列关系，“所以”表示因果，用在这里说法错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "因为天气不好，所以因为我没去公园。", "corrected_sentence": "因为天气不好，所以我没去公园。", "error_description": "错误：“所以”已引出结果，结果分句前又多加了“因为”。“因为”只引出原因，“所以”与“因为”配对使用，结果分句只用“所以”。错误形式为“所以因为我没去公园”，正确形式为“因为天气不好，所以我没去公园。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "因为他没带伞，他所以淋湿了。", "corrected_sentence": "因为他没带伞，所以淋湿了。", "error_description": "错误：“所以”位置不对。“所以”是连接结果分句的连词，应放在结果分句最前面，写作“所以淋湿了”，不能放在主语“他”之后。正确形式为“因为他没带伞，所以淋湿了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
