INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85827, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "批准是大人说可以，让你去做。", "primary_collocate": null, "pronunciation": "pī zhǔn", "ipa": "pʰi˥ ʈ͡ʂu̯n˨˩", "syllable_count": 2, "sentences": [{"text": "妈妈批准我周末去朋友家玩。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批准了我的请假。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不批准我晚上出去玩。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸终于批准我养小狗了。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈没有批准我看电视。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批准我们提前回家。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶批准孩子们玩一个小时游戏。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问了爸爸，他批准我骑车上学。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸批准我周末跟同学去爬山。", "target_word": "批准", "complexity_tier": "T3", "furigana": "bà ba pī zhǔn wǒ zhōu mò gēn tóng xué qù pá shān.", "sentence_source": "generated"}, {"text": "校长批准同学们明天不用穿校服。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批准了", "label": "体标"}, {"form": "批准过", "label": "体标"}, {"form": "批準", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大人或老师同意孩子做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5b1d1f-0031-45d5-a89b-428c11dec8c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批准", "is_correct": true, "explanation": "“批准”表示有权的家长同意孩子去做某事，与“妈妈……我周末去朋友家玩”相合。"}, {"text": "祝贺", "is_correct": false, "explanation": "配价：“祝贺”的宾语是人或事件，不能接“去朋友家玩”这样的小句。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指把一种语言转成另一种，不能表示允许。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理，与“去朋友家玩”的允许义无关。"}], "explanations": {"批准": "“批准”表示有权的家长同意孩子去做某事，与“妈妈……我周末去朋友家玩”相合。", "祝贺": "配价：“祝贺”的宾语是人或事件，不能接“去朋友家玩”这样的小句。", "翻译": "语义：“翻译”指把一种语言转成另一种，不能表示允许。", "打扫": "语义：“打扫”指清理，与“去朋友家玩”的允许义无关。"}, "sentence_index": 0, "correct_answer": "批准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我批准了同学的建议。", "explanation": "这里应该用〈同意〉。同意可用于平等的人之间表示赞成，批准指有权决定的人许可，学生不能批准同学的建议。"}, {"text": "妈妈批准了我的作业。", "explanation": "这里应该用〈检查〉。批准的对象是请求、计划或要做的事，作业应说检查或批改，不说批准。"}, {"text": "这台电视批准我看一个小时。", "explanation": "这里应该用〈允许〉，并改用人作主语。批准的施事须是有权的家长或老师，电视不能作施事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批准", "is_correct": true, "explanation": "“批准”表示奶奶同意孩子玩游戏，与“奶奶……孩子们玩一个小时游戏”的许可关系相合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热食物，不能表示同意。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，与玩游戏无关。"}, {"text": "拍", "is_correct": false, "explanation": "配价：“拍”带的宾语是具体的人或物，不能接“玩一个小时游戏”这样的小句。"}], "explanations": {"批准": "“批准”表示奶奶同意孩子玩游戏，与“奶奶……孩子们玩一个小时游戏”的许可关系相合。", "煮": "语义：“煮”指用水加热食物，不能表示同意。", "洗": "语义：“洗”指清洁，与玩游戏无关。", "拍": "配价：“拍”带的宾语是具体的人或物，不能接“玩一个小时游戏”这样的小句。"}, "sentence_index": 6, "correct_answer": "批准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸批准了那张旅游照片。", "explanation": "这里应该用〈认可〉。认可指肯定、承认某物的好坏；批准指有权的人对请求、计划表示同意，照片不是请求或计划，不能被批准。"}, {"text": "我批准我自己周末去爬山。", "explanation": "这里应该用〈决定〉。决定指自己拿主意；批准指有权的长辈或老师对别人的请求表示同意，不能自己批准自己。"}, {"text": "老师批准了同学们的笑容。", "explanation": "这里应该用〈欣赏〉。欣赏可用于笑容、表情等；批准的对象是请求、计划或要做的事，笑容不能被批准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈批准我了周末去看电影。", "corrected_sentence": "妈妈批准了我周末去看电影。", "error_description": "动态助词“了”位置错误：“了”应紧接动词“批准”，说“批准了我”，不能放在“我”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校长不批准了同学们明天穿便服。", "corrected_sentence": "校长不批准同学们明天穿便服。", "error_description": "体标错误：否定句中“不批准”后不能加动态助词“了”，应说“不批准同学们明天穿便服”，不能说“不批准了同学们……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
