INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85829, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“有的”是说在很多人或东西里，有一些是这样的。", "primary_collocate": null, "pronunciation": "yǒu de", "ipa": "jou̯˨˩˦ tɤ", "syllable_count": 2, "sentences": [{"text": "教室里的学生有的在看书，有的在写字。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的人有的在跑步，有的在聊天。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的苹果有的大，有的小。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友有的住在北京，有的住在上海。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花有的是红色的，有的是黄色的。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的衣服有的贵，有的便宜。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们有的喜欢唱歌，有的喜欢跳舞。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的孩子有的在玩水，有的在钓鱼。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书有的我看了，有的还没看。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，有的人去爬山，有的人在家休息。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "代词，指整体中的一部分人或事物，常成对出现：有的……有的……", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fb035c5-9777-447c-8d06-6c17b4aedd72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85829, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有的", "is_correct": true, "explanation": "正确：“有的”第二字为轻声，指一部分人或事物。"}, {"text": "有底", "is_correct": false, "explanation": "声调不同：“底”为第三声，“的”为轻声，意思是心里有把握，与“有的”不同。"}, {"text": "有德", "is_correct": false, "explanation": "声调不同：“德”为第二声，“的”为轻声，意思是有道德。"}, {"text": "油的", "is_correct": false, "explanation": "声调不同：“油”为第二声，“有”为第三声，意思是油腻的。"}, {"text": "有敌", "is_correct": false, "explanation": "声调不同：“敌”为第二声，“的”为轻声，意思是有敌人。"}], "explanations": {"有的": "正确：“有的”第二字为轻声，指一部分人或事物。", "有底": "声调不同：“底”为第三声，“的”为轻声，意思是心里有把握，与“有的”不同。", "有德": "声调不同：“德”为第二声，“的”为轻声，意思是有道德。", "油的": "声调不同：“油”为第二声，“有”为第三声，意思是油腻的。", "有敌": "声调不同：“敌”为第二声，“的”为轻声，意思是有敌人。"}, "sentence_index": null, "correct_answer": "有的"}, "level_3": {"options": [{"text": "有的", "is_correct": true, "explanation": "正确：“有的”指一部分学生，与后句“有的在写字”配对。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指全体，与后句“有的在写字”只指一部分相矛盾。"}, {"text": "每个", "is_correct": false, "explanation": "语义：“每个”指逐一的全部，与“有的……有的……”的部分之意冲突。"}, {"text": "那些", "is_correct": false, "explanation": "搭配：“那些”是指示代词，需有明确所指，“学生那些”不成话。"}], "explanations": {"有的": "正确：“有的”指一部分学生，与后句“有的在写字”配对。", "大家": "语义：“大家”指全体，与后句“有的在写字”只指一部分相矛盾。", "每个": "语义：“每个”指逐一的全部，与“有的……有的……”的部分之意冲突。", "那些": "搭配：“那些”是指示代词，需有明确所指，“学生那些”不成话。"}, "sentence_index": 0, "correct_answer": "有的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有的同学都来了。", "explanation": "这里应该用〈所有〉。“所有”指全部，与“都”搭配；“有的”指一部分，与“都”矛盾。"}, {"text": "我的叔叔有的很爱喝茶。", "explanation": "这里应该用〈他〉。“有的”指一部分，需要多个对象；“我的叔叔”只有一个人，应用代词“他”。"}, {"text": "我妈妈有的很喜欢做饭。", "explanation": "这里应该用〈她〉。“有的”指一部分，需要多个人或物才能分出部分；“我妈妈”只有一个人，应用代词“她”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85829, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有的", "is_correct": true, "explanation": "正确：“有的”第二字为轻声，指一部分人或事物。"}, {"text": "有地", "is_correct": false, "explanation": "声调不同：“地”为第四声，“的”为轻声，意思是拥有土地。"}, {"text": "有弟", "is_correct": false, "explanation": "声调不同：“弟”为第四声，“的”为轻声，意思是有弟弟。"}, {"text": "有得", "is_correct": false, "explanation": "声调不同：“得”为第二声，“的”为轻声，意思是有所得。"}], "explanations": {"有的": "正确：“有的”第二字为轻声，指一部分人或事物。", "有地": "声调不同：“地”为第四声，“的”为轻声，意思是拥有土地。", "有弟": "声调不同：“弟”为第四声，“的”为轻声，意思是有弟弟。", "有得": "声调不同：“得”为第二声，“的”为轻声，意思是有所得。"}, "sentence_index": null, "correct_answer": "有的"}, "level_3": {"options": [{"text": "有的", "is_correct": true, "explanation": "正确：“有的”指一部分同学，与后句“有的喜欢跳舞”配对。"}, {"text": "个个", "is_correct": false, "explanation": "语义：“个个”指每一个人，与“有的喜欢跳舞”的部分之意矛盾。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，句子变成疑问，不能陈述一部分同学的爱好。"}, {"text": "其余", "is_correct": false, "explanation": "搭配：“其余”作代词需带“的”，“同学们其余喜欢唱歌”不成句。"}], "explanations": {"有的": "正确：“有的”指一部分同学，与后句“有的喜欢跳舞”配对。", "个个": "语义：“个个”指每一个人，与“有的喜欢跳舞”的部分之意矛盾。", "谁": "语义：“谁”是疑问代词，句子变成疑问，不能陈述一部分同学的爱好。", "其余": "搭配：“其余”作代词需带“的”，“同学们其余喜欢唱歌”不成句。"}, "sentence_index": 6, "correct_answer": "有的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我奶奶有的很喜欢喝茶。", "explanation": "这里应该用〈她〉。“有的”指一部分，需要多个对象；“我奶奶”只有一个人，不能说“有的”，应用“她”。"}, {"text": "我买了一支笔，有的很贵。", "explanation": "这里应该用〈它〉。“有的”指一部分，需要多个东西；“一支笔”只有一件，应用“它”指代。"}, {"text": "这些作业我有的都做完了。", "explanation": "这里应该用〈全部〉。“全部”指作业整体，与“都”搭配；“有的”指一部分，与“都”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班上的同学有的喜欢数学，有了喜欢历史。", "corrected_sentence": "班上的同学有的喜欢数学，有的喜欢历史。", "error_description": "错误：第二个“有的”误写成了“有了”。“有了”是动词加助词，不能作主语；指一部分人时应用代词“有的”。正确形式为“班上的同学有的喜欢数学，有的喜欢历史。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末，所有的同学去爬山，有的同学在家休息。", "corrected_sentence": "周末，有的同学去爬山，有的同学在家休息。", "error_description": "错误：前半句误用了“所有的”。“所有的”指全部，与后半句“有的同学在家休息”的部分之意冲突，应用“有的”。正确形式为“周末，有的同学去爬山，有的同学在家休息。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
