INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，邀请或聘请别人来。", "primary_collocate": null, "pronunciation": "qǐng", "ipa": "tɕʰiŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我想请你来我家吃饭。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请了十个朋友参加生日会。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈请医生来看奶奶。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请王老师给大家讲课。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我请你看电影，好吗？", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她请我去她家玩。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈请邻居来家里吃饭。", "target_word": "请", "complexity_tier": "T3", "furigana": "mā ma qǐng lín jū lái jiā lǐ chī fàn", "sentence_source": "generated"}, {"text": "明天我请大家喝咖啡。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请朋友来帮忙搬家。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请她唱了一首歌。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "請", "label": "繁体"}, {"form": "请了", "label": "完成体"}, {"form": "请过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动词：邀请或聘请别人来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d3283c2-c3c9-456b-a54d-b3cbf61747b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85836, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "请", "is_correct": true, "explanation": "正确。“请”（qǐng）意思是邀请或聘请别人来。"}, {"text": "轻", "is_correct": false, "explanation": "qīng（第一声）与 qǐng（第三声）声调不同，“轻”意思是重量小。"}, {"text": "情", "is_correct": false, "explanation": "qíng（第二声）与 qǐng（第三声）声调不同，“情”意思是感情。"}, {"text": "清", "is_correct": false, "explanation": "qīng（第一声）与 qǐng（第三声）声调不同，“清”意思是干净。"}], "explanations": {"请": "正确。“请”（qǐng）意思是邀请或聘请别人来。", "轻": "qīng（第一声）与 qǐng（第三声）声调不同，“轻”意思是重量小。", "情": "qíng（第二声）与 qǐng（第三声）声调不同，“情”意思是感情。", "清": "qīng（第一声）与 qǐng（第三声）声调不同，“清”意思是干净。"}, "sentence_index": null, "correct_answer": "请"}, "level_3": {"options": [{"text": "请", "is_correct": true, "explanation": "正确。“请你来我家吃饭”是邀请对方来做客。"}, {"text": "陪", "is_correct": false, "explanation": "语义：“陪”表示陪同，“我想陪你来我家吃饭”表达的不是邀请对方来做客。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替，“替你来我家吃饭”意思不通，不是邀请。"}, {"text": "逼", "is_correct": false, "explanation": "语义：“逼”表示强迫，与客气地邀请对方来做客相反。"}], "explanations": {"请": "正确。“请你来我家吃饭”是邀请对方来做客。", "陪": "语义：“陪”表示陪同，“我想陪你来我家吃饭”表达的不是邀请对方来做客。", "替": "语义：“替”表示代替，“替你来我家吃饭”意思不通，不是邀请。", "逼": "语义：“逼”表示强迫，与客气地邀请对方来做客相反。"}, "sentence_index": 0, "correct_answer": "请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们请书包里的铅笔给大家讲课。", "explanation": "这里应该用〈让〉。“请”的对象应是能受邀的人，不能是物。"}, {"text": "我请他的生日，他很高兴。", "explanation": "这里应该用〈庆祝〉。“请”表示邀请人来，不能说“请生日”。"}, {"text": "我请一个苹果去他家玩。", "explanation": "这里应该用〈拿〉。“请”的对象必须是能受邀的人，苹果不能被邀请；带东西去别人家应用“拿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85836, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "请", "is_correct": true, "explanation": "正确。“请”（qǐng）意思是邀请或聘请别人来。"}, {"text": "庆", "is_correct": false, "explanation": "qìng（第四声）与 qǐng（第三声）声调不同，“庆”意思是庆祝。"}, {"text": "青", "is_correct": false, "explanation": "qīng（第一声）与 qǐng（第三声）声调不同，“青”意思是绿色。"}, {"text": "晴", "is_correct": false, "explanation": "qíng（第二声）与 qǐng（第三声）声调不同，“晴”意思是天气晴朗。"}], "explanations": {"请": "正确。“请”（qǐng）意思是邀请或聘请别人来。", "庆": "qìng（第四声）与 qǐng（第三声）声调不同，“庆”意思是庆祝。", "青": "qīng（第一声）与 qǐng（第三声）声调不同，“青”意思是绿色。", "晴": "qíng（第二声）与 qǐng（第三声）声调不同，“晴”意思是天气晴朗。"}, "sentence_index": null, "correct_answer": "请"}, "level_3": {"options": [{"text": "请", "is_correct": true, "explanation": "正确。“妈妈请邻居来家里吃饭”是邀请邻居来做客。"}, {"text": "派", "is_correct": false, "explanation": "语义：“派”表示指派人去做任务，不表示客气地邀请对方来做客。"}, {"text": "雇", "is_correct": false, "explanation": "搭配：“雇”的对象是受雇用的人，不能与“来家里吃饭”的邀请搭配。"}, {"text": "逼", "is_correct": false, "explanation": "语义：“逼”表示强迫，与“妈妈……吃饭”的客气邀请相反。"}], "explanations": {"请": "正确。“妈妈请邻居来家里吃饭”是邀请邻居来做客。", "派": "语义：“派”表示指派人去做任务，不表示客气地邀请对方来做客。", "雇": "搭配：“雇”的对象是受雇用的人，不能与“来家里吃饭”的邀请搭配。", "逼": "语义：“逼”表示强迫，与“妈妈……吃饭”的客气邀请相反。"}, "sentence_index": 6, "correct_answer": "请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我请这本书来我们班讲课。", "explanation": "这里应该用〈让〉。“请”的对象应是能受邀的人，不能是书。"}, {"text": "我请天气下雨，因为我很喜欢雨。", "explanation": "这里应该用〈希望〉。“请”表示邀请人来，不能用于天气。"}, {"text": "他请门口的花来帮忙搬家。", "explanation": "这里应该用〈让〉。“请”的对象应是人，不能是花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天请朋友了来家里吃饭。", "corrected_sentence": "我明天请朋友来家里吃饭。", "error_description": "错误形式：“请朋友了”；正确形式：“请朋友”。“明天”表示将来，动作还没有发生，“请”带宾语时不能在宾语后加“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们她请来唱一首歌。", "corrected_sentence": "我们请她来唱一首歌。", "error_description": "错误形式：“她请来”；正确形式：“请她来”。“请”是兼语动词，“她”既是“请”的宾语又是“来”的主语，应放在“请”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
