INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85837, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "枪是一种会射出子弹的东西，很危险，小朋友不能玩。", "primary_collocate": null, "pronunciation": "qiāng", "ipa": "tɕʰiɑŋ˥", "syllable_count": 1, "sentences": [{"text": "他手里有一把枪。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "枪很危险，小孩不能玩。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察的枪放在桌子上。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个人拿着一把枪。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在电影里看过枪。", "target_word": "枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把枪放进了箱子里。", "target_word": "枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到枪响，大家都很害怕。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把枪是警察的，别碰它。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，枪不是玩具。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不敢看那把枪。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把枪", "label": "量词"}, {"form": "一支枪", "label": "量词"}, {"form": "手枪", "label": "复合"}, {"form": "槍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会射出子弹、危险的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8be57f03-7fb2-4413-ac65-d96db36736d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85837, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "枪", "is_correct": true, "explanation": "枪：会射出子弹的东西。"}, {"text": "强", "is_correct": false, "explanation": "qiáng（第二声）与 qiāng（第一声）声调不同，意思是强大。"}, {"text": "抢", "is_correct": false, "explanation": "qiǎng（第三声）与 qiāng（第一声）声调不同，意思是抢夺。"}, {"text": "千", "is_correct": false, "explanation": "qiān 与 qiāng 韵母不同（an 与 ang），意思是一千。"}, {"text": "江", "is_correct": false, "explanation": "jiāng 与 qiāng 声母不同（j 与 q），意思是江河。"}, {"text": "香", "is_correct": false, "explanation": "xiāng 与 qiāng 声母不同（x 与 q），意思是香气。"}], "explanations": {"枪": "枪：会射出子弹的东西。", "强": "qiáng（第二声）与 qiāng（第一声）声调不同，意思是强大。", "抢": "qiǎng（第三声）与 qiāng（第一声）声调不同，意思是抢夺。", "千": "qiān 与 qiāng 韵母不同（an 与 ang），意思是一千。", "江": "jiāng 与 qiāng 声母不同（j 与 q），意思是江河。", "香": "xiāng 与 qiāng 声母不同（x 与 q），意思是香气。"}, "sentence_index": null, "correct_answer": "枪"}, "level_3": {"options": [{"text": "枪", "is_correct": true, "explanation": "枪：可以握在手里的武器，量词用“把”，符合“手里有一把”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能握在手里，与“手里有”冲突。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“把”不用于房子，房子用“座”或“栋”。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能拿在手里，与“手里有”冲突。"}], "explanations": {"枪": "枪：可以握在手里的武器，量词用“把”，符合“手里有一把”。", "天空": "语义：天空不能握在手里，与“手里有”冲突。", "房子": "搭配：量词“把”不用于房子，房子用“座”或“栋”。", "大海": "语义：大海不能拿在手里，与“手里有”冲突。"}, "sentence_index": 0, "correct_answer": "枪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察从包里拿出一块枪。", "explanation": "这里应该用〈把〉或〈支〉。“块”用于块状或扁平的东西，不用来计量枪。"}, {"text": "他用枪切开了西瓜。", "explanation": "这里应该用〈刀〉。枪是射击用的武器，不能用来切东西。"}, {"text": "他买了一把枪，用来晾衣服。", "explanation": "这里应该用〈晾衣架〉。枪是射击用的武器，不能当晾衣架使用，晾衣服要用晾衣架。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85837, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "枪", "is_correct": true, "explanation": "枪：会射出子弹的东西。"}, {"text": "墙", "is_correct": false, "explanation": "qiáng（第二声）与 qiāng（第一声）声调不同，意思是墙。"}, {"text": "将", "is_correct": false, "explanation": "jiāng 与 qiāng 声母不同（j 与 q），意思是将要。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng 与 qiāng 声母不同（x 与 q），意思是乡村。"}, {"text": "牵", "is_correct": false, "explanation": "qiān 与 qiāng 韵母不同（an 与 ang），意思是牵引。"}], "explanations": {"枪": "枪：会射出子弹的东西。", "墙": "qiáng（第二声）与 qiāng（第一声）声调不同，意思是墙。", "将": "jiāng 与 qiāng 声母不同（j 与 q），意思是将要。", "乡": "xiāng 与 qiāng 声母不同（x 与 q），意思是乡村。", "牵": "qiān 与 qiāng 韵母不同（an 与 ang），意思是牵引。"}, "sentence_index": null, "correct_answer": "枪"}, "level_3": {"options": [{"text": "枪", "is_correct": true, "explanation": "枪：会发出响声的武器，“枪响”是常见搭配。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不会发出响声，与“响”冲突。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会发出响声，与“响”冲突。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不会发出响声，与“响”冲突。"}], "explanations": {"枪": "枪：会发出响声的武器，“枪响”是常见搭配。", "花": "语义：花不会发出响声，与“响”冲突。", "太阳": "语义：太阳不会发出响声，与“响”冲突。", "眼睛": "语义：眼睛不会发出响声，与“响”冲突。"}, "sentence_index": 6, "correct_answer": "枪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一头枪送给儿子。", "explanation": "这里应该用〈把〉或〈支〉。“头”用于牛、猪等大型牲畜，不用来计量枪。"}, {"text": "他在街上看见一张枪。", "explanation": "这里应该用〈把〉或〈支〉。“张”用于纸、桌子等平面的东西，不用来计量枪。"}, {"text": "他在柜子里找到一颗枪。", "explanation": "这里应该用〈把〉或〈支〉。“颗”用于颗粒状或小而圆的东西，不用来计量枪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他收起了一只枪。", "corrected_sentence": "他收起了一支枪。", "error_description": "量词错误：枪应用“支”或“把”计量，“只”用于动物或成对物件中的一个，这里应改为“支”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候玩枪过。", "corrected_sentence": "他小时候玩过枪。", "error_description": "“过”的位置错误：经历标记“过”应紧跟动词，应为“玩过枪”，不能放在宾语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
