INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用火药或压缩空气发射子弹的武器。", "primary_collocate": null, "pronunciation": "qiāng", "ipa": "tɕʰiɑŋ˥", "syllable_count": 1, "sentences": [{"text": "这支枪用火药发射子弹。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "士兵背着一支枪站在门口。", "target_word": "枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起枪，对准了前面。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察拿出枪，让他别动。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "打猎的人需要有枪。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "枪里没有子弹了。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个士兵每天都要擦枪。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这把枪很重，孩子拿不动。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把枪交给了警察。", "target_word": "枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多国家不让人买枪。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把枪", "label": "量词"}, {"form": "一支枪", "label": "量词"}, {"form": "手枪", "label": "复合"}, {"form": "槍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "发射子弹的武器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8be57f03-7fb2-4413-ac65-d96db36736d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
