INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一只枪锁进了柜子。", "corrected_sentence": "他把枪锁进了柜子。", "error_description": "量词错误：“枪”前不能用量词“只”（“只”多用于动物或成对物件中的一个），应改用“把”或“支”，如“一把枪”“一支枪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察以前过用这种枪。", "corrected_sentence": "警察以前用过这种枪。", "error_description": "“过”的位置错误：经历标记“过”应紧跟动词，应为“用过这种枪”，不能放在动词“用”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
