INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "整个国家的范围。", "primary_collocate": null, "pronunciation": "quán guó", "ipa": "tɕʰyɛn˧˥ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "全国的天气今天都很好。", "target_word": "全国", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个节目全国的人都看过。", "target_word": "全国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国有很多大城市。", "target_word": "全国", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春节的时候，全国各地都很热闹。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司在全国有一百家商店。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是全国有名的医生。", "target_word": "全国", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "全国的学校今天都放假了。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条新闻让全国的人都知道了。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐火车可以去全国很多城市。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天全国大部分地方会下雨。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "全國", "label": "繁体"}, {"form": "全国性", "label": "复合"}], "register": "中性", "sense_fingerprint": "整个国家的范围，指国家的全部领土范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d8e7589-5b4b-4fd1-9e86-38e415da95b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全国", "is_correct": true, "explanation": "正确：“全国”指整个国家的范围，与“天气今天都很好”相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”与句中的“今天”冲突，不能说“明天的天气今天都很好”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“汽车”没有天气，不能说“汽车的天气”。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“身体”不能和“天气”搭配，不能说“身体的天气”。"}], "explanations": {"全国": "正确：“全国”指整个国家的范围，与“天气今天都很好”相符。", "明天": "语义：“明天”与句中的“今天”冲突，不能说“明天的天气今天都很好”。", "汽车": "搭配：“汽车”没有天气，不能说“汽车的天气”。", "身体": "搭配：“身体”不能和“天气”搭配，不能说“身体的天气”。"}, "sentence_index": 0, "correct_answer": "全国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的公司在全国十个国家都设有分部。", "explanation": "这里应该用〈全世界〉。全国只指一个国家的范围，不能用于十个国家；分布在多个国家要用全世界。"}, {"text": "我们学校全国的同学都参加了这次比赛。", "explanation": "这里应该用〈全校〉。全国指整个国家，不能用来指一所学校的范围；学校内所有同学要用全校。"}, {"text": "这所幼儿园全国的小朋友都参加了表演。", "explanation": "这里应该用〈全园〉。全国指整个国家，不能用于一所幼儿园的范围；园里的小朋友要用全园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全国", "is_correct": true, "explanation": "正确：“全国”指整个国家，与“学校今天都放假了”相符。"}, {"text": "后天", "is_correct": false, "explanation": "语义：“后天”与句中的“今天”冲突，不能说“后天的学校今天都放假了”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不是学校，不能说“冰箱的学校”。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“书包”不能作学校的修饰语，不能说“书包的学校”。"}], "explanations": {"全国": "正确：“全国”指整个国家，与“学校今天都放假了”相符。", "后天": "语义：“后天”与句中的“今天”冲突，不能说“后天的学校今天都放假了”。", "冰箱": "搭配：“冰箱”不是学校，不能说“冰箱的学校”。", "书包": "搭配：“书包”不能作学校的修饰语，不能说“书包的学校”。"}, "sentence_index": 6, "correct_answer": "全国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛，我们班全国同学都参加了。", "explanation": "这里应该用〈全班〉。全国指国家范围，不能用来指一个班；班里所有人要用全班。"}, {"text": "这座城市全国的人口超过一千万。", "explanation": "这里应该用〈全市〉。全国的范围远大于一座城市；一座城市的人口要用全市。"}, {"text": "这个小镇全国的居民都搬走了。", "explanation": "这里应该用〈全镇〉。全国的范围与一个小镇不符；小镇内的居民要用全镇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个全国城市都有图书馆。", "corrected_sentence": "全国城市都有图书馆。", "error_description": "“全国”是范围词，不能用数量词“一个”修饰，应删去“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个全国农民都在忙着收割。", "corrected_sentence": "全国农民都在忙着收割。", "error_description": "“全国”是范围词，不能用数量词“一个”修饰，应删去“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
