INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85845, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“呢”放在句子后面，用来问“在哪里”或“怎么样”。", "primary_collocate": null, "pronunciation": "ne", "ipa": "nɤ", "syllable_count": 1, "sentences": [{"text": "我的手机呢？", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你喜欢咖啡，他呢？", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我很好，你呢？", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈呢？我没看见她。", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸去上班了，妈妈呢？", "target_word": "呢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菜很好吃，那个呢？", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的笔呢？刚才还在这儿。", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们都到了，小明呢？", "target_word": "呢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我吃面条，你呢？", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天很冷，明天呢？", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "用在名词或代词后的省略问句，问在哪里或怎么样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d8e7589-5b4b-4fd1-9e86-38e415da95b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85845, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呢", "is_correct": true, "explanation": "正确：“呢”用于省略问，“我的手机呢？”问手机在哪里。"}, {"text": "吗", "is_correct": false, "explanation": "配价：“吗”要接完整陈述句，不能直接接名词“我的手机”。"}, {"text": "吧", "is_correct": false, "explanation": "语义：“吧”表示推测或商量，不是追问东西在哪里。"}, {"text": "啊", "is_correct": false, "explanation": "语义：“啊”表示感叹或语气，不用来追问位置。"}], "explanations": {"呢": "正确：“呢”用于省略问，“我的手机呢？”问手机在哪里。", "吗": "配价：“吗”要接完整陈述句，不能直接接名词“我的手机”。", "吧": "语义：“吧”表示推测或商量，不是追问东西在哪里。", "啊": "语义：“啊”表示感叹或语气，不用来追问位置。"}, "sentence_index": 0, "correct_answer": "呢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天真冷呢！", "explanation": "此处“呢”表示感叹语气，不是省略问，不属于本义项。"}, {"text": "快点吃饭呢！", "explanation": "此处“呢”表示催促语气，不是省略问，不属于本义项。"}, {"text": "你别这样呢。", "explanation": "此处“呢”表示劝说语气，不是省略问，不属于本义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85845, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呢", "is_correct": true, "explanation": "正确：“呢”用于省略问，“我的笔呢？刚才还在这儿”问笔在哪里。"}, {"text": "嘛", "is_correct": false, "explanation": "语义：“嘛”表示理所当然，不用于追问东西在哪里。"}, {"text": "呀", "is_correct": false, "explanation": "语义：“呀”用于感叹或招呼，不用来追问位置。"}, {"text": "啦", "is_correct": false, "explanation": "语义：“啦”表示语气变化，不能用来追问东西在哪里。"}], "explanations": {"呢": "正确：“呢”用于省略问，“我的笔呢？刚才还在这儿”问笔在哪里。", "嘛": "语义：“嘛”表示理所当然，不用于追问东西在哪里。", "呀": "语义：“呀”用于感叹或招呼，不用来追问位置。", "啦": "语义：“啦”表示语气变化，不能用来追问东西在哪里。"}, "sentence_index": 6, "correct_answer": "呢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "快点呢，车要开了！", "explanation": "此处“呢”表示催促语气，不是省略问，不属于本义项。"}, {"text": "我已经做完作业呢。", "explanation": "此处“呢”表示陈述完成的语气，不是省略问，不属于本义项。"}, {"text": "他已经走呢。", "explanation": "此处“呢”表示陈述语气，不是省略问，不属于本义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王的伞呢吗？", "corrected_sentence": "小王的伞呢？", "error_description": "问“伞在哪里”只用“呢”，句末不能再加“吗”，应说“小王的伞呢？”；“呢”与“吗”两个疑问语气词不能叠用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你看见我的笔了呢？", "corrected_sentence": "你看见我的笔了吗？", "error_description": "“呢”不用于是非问，是非问应用“吗”，故“你看见我的笔了呢？”应改为“……了吗？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
