INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85846, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "语气助词，用在句末，表示疑问、持续或提醒等语气。", "primary_collocate": null, "pronunciation": "ne", "ipa": "nɤ", "syllable_count": 1, "sentences": [{"text": "他在看书呢。", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外面下着雨呢。", "target_word": "呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别急，时间还早呢。", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你去不去呢？", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子在睡觉呢，小声点。", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我还没吃饭呢。", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事该怎么办呢？", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们还在路上呢。", "target_word": "呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别忘了，明天还有考试呢。", "target_word": "呢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门开着呢，你进来吧。", "target_word": "呢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句末语气助词，表示疑问、动作持续或提醒对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d8e7589-5b4b-4fd1-9e86-38e415da95b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呢", "is_correct": true, "explanation": "正确：“呢”表示动作正在进行，“他在看书呢”描述正在看书的状态。"}, {"text": "吗", "is_correct": false, "explanation": "配价：“吗”用于疑问句末，不能接陈述句“他在看书”。"}, {"text": "啊", "is_correct": false, "explanation": "语义：“啊”表示感叹，不表示动作正在进行。"}, {"text": "过", "is_correct": false, "explanation": "语法：“过”表示经历，不能表示“在看书”的持续，也不能作句末语气词。"}], "explanations": {"呢": "正确：“呢”表示动作正在进行，“他在看书呢”描述正在看书的状态。", "吗": "配价：“吗”用于疑问句末，不能接陈述句“他在看书”。", "啊": "语义：“啊”表示感叹，不表示动作正在进行。", "过": "语法：“过”表示经历，不能表示“在看书”的持续，也不能作句末语气词。"}, "sentence_index": 0, "correct_answer": "呢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喜欢呢这本书。", "explanation": "“呢”是句末语气词，不能插在动词和宾语之间，此处应删去。"}, {"text": "他昨天呢来了。", "explanation": "“呢”不能插在主语与动词之间，此处应删去。"}, {"text": "我今天呢去公园。", "explanation": "“呢”不能放在状语与动词之间，此处应删去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呢", "is_correct": true, "explanation": "正确：“呢”用于疑问句，“这件事该怎么办呢？”追问解决办法。"}, {"text": "过", "is_correct": false, "explanation": "语法：“过”表示经历，不能作句末语气词，与疑问句不合。"}, {"text": "嘛", "is_correct": false, "explanation": "语义：“嘛”表示理所当然或劝说，不用于追问办法。"}, {"text": "哟", "is_correct": false, "explanation": "语域：“哟”口语色彩过强，与这种书面追问的语气不符。"}], "explanations": {"呢": "正确：“呢”用于疑问句，“这件事该怎么办呢？”追问解决办法。", "过": "语法：“过”表示经历，不能作句末语气词，与疑问句不合。", "嘛": "语义：“嘛”表示理所当然或劝说，不用于追问办法。", "哟": "语域：“哟”口语色彩过强，与这种书面追问的语气不符。"}, "sentence_index": 6, "correct_answer": "呢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你别这么呢着急。", "explanation": "“呢”不能插在状语与中心语之间，此处应删去。"}, {"text": "他跑得呢很快。", "explanation": "“呢”不能放在补语标记“得”之后，此处应删去。"}, {"text": "请你呢稍等。", "explanation": "“呢”不能放在动词前，此处应删去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他还在睡觉呢吗。", "corrected_sentence": "他还在睡觉呢。", "error_description": "表示动作正在进行，句末只用“呢”，应说“还在睡觉呢。”；“呢”与“吗”不能叠用，多加的“吗”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们还在操场上呢玩。", "corrected_sentence": "孩子们还在操场上玩呢。", "error_description": "“呢”是句末语气词，要放在句尾，应说“还在操场上玩呢”，不能放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85847, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合法", "is_correct": true, "explanation": "合法与“非法”构成反义，指符合法律规定。"}, {"text": "公正", "is_correct": false, "explanation": "公正指公平、不偏袒，与“非法”没有反义关系。"}, {"text": "严格", "is_correct": false, "explanation": "严格指要求高、执行紧，与“非法”没有反义关系。"}, {"text": "必要", "is_correct": false, "explanation": "必要指不可缺少，与“非法”没有反义关系。"}], "correct_answer": "合法", "explanations": {"合法": "合法与“非法”构成反义，指符合法律规定。", "公正": "公正指公平、不偏袒，与“非法”没有反义关系。", "严格": "严格指要求高、执行紧，与“非法”没有反义关系。", "必要": "必要指不可缺少，与“非法”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85847, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合法", "is_correct": true, "explanation": "合法与“非法”构成反义，指符合法律规定。"}, {"text": "诚实", "is_correct": false, "explanation": "诚实指说话做事真实，与“非法”没有反义关系。"}, {"text": "明显", "is_correct": false, "explanation": "明显指容易看出，与“非法”没有反义关系。"}, {"text": "正常", "is_correct": false, "explanation": "正常指符合常规，与“非法”没有反义关系。"}], "correct_answer": "合法", "explanations": {"合法": "合法与“非法”构成反义，指符合法律规定。", "诚实": "诚实指说话做事真实，与“非法”没有反义关系。", "明显": "明显指容易看出，与“非法”没有反义关系。", "正常": "正常指符合常规，与“非法”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85847, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非法就是做了法律不让做的事。", "primary_collocate": null, "pronunciation": "fēi fǎ", "ipa": "fei˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察抓住了几个非法捕鱼的人。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这里卖枪是非法的。", "target_word": "非法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "没有证件就进入这个国家是非法的。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠非法赚来的钱买了房子。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院说这家公司的做法是非法的。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有执照开出租车是非法的。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "非法停车要交罚款。", "target_word": "非法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察说他非法入境，要送他回国。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在网上非法卖药，警察发现了。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师告诉我们，偷别人的东西是非法的。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "非法入境", "label": "复合"}, {"form": "非法所得", "label": "复合"}], "register": "书面语", "sense_fingerprint": "做了法律禁止的事，违法的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53fc934-9efd-4505-9f2d-9389e6da67ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非法", "is_correct": true, "explanation": "非法：做了法律禁止的事，修饰“捕鱼的人”，指违法捕鱼。"}, {"text": "合法", "is_correct": false, "explanation": "语义：合法捕鱼的人没有违法，与“警察抓住”的情境矛盾。"}, {"text": "守法", "is_correct": false, "explanation": "语义：守法的人遵守法律，不会被警察抓住，与语境冲突。"}, {"text": "友善", "is_correct": false, "explanation": "搭配：“友善”形容人的态度，不能用来描述“捕鱼的人”这类行为主体。"}], "explanations": {"非法": "非法：做了法律禁止的事，修饰“捕鱼的人”，指违法捕鱼。", "合法": "语义：合法捕鱼的人没有违法，与“警察抓住”的情境矛盾。", "守法": "语义：守法的人遵守法律，不会被警察抓住，与语境冲突。", "友善": "搭配：“友善”形容人的态度，不能用来描述“捕鱼的人”这类行为主体。"}, "sentence_index": 0, "correct_answer": "非法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这名球员在比赛中非法犯规，裁判给了他黄牌。", "explanation": "这里应该用〈违规〉。非法指违反法律，比赛中的犯规违反的是比赛规则，要说违规。"}, {"text": "他的汉语说得很非法，大家都听不懂。", "explanation": "这里应该用〈不流利〉。非法只形容违反法律的行为，不能形容说话的流利程度。"}, {"text": "他对老人说话很非法。", "explanation": "这里应该用〈不礼貌〉。非法不能形容说话的态度，对老人态度不好应说不礼貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非法", "is_correct": true, "explanation": "非法：违反法律，修饰“停车”，指违规停车。"}, {"text": "免费", "is_correct": false, "explanation": "语义：免费停车不收费，不应因此被罚款，与“要交罚款”矛盾。"}, {"text": "安全", "is_correct": false, "explanation": "语义：安全停车不会违规，与“要交罚款”的语境矛盾。"}, {"text": "大型", "is_correct": false, "explanation": "搭配：“大型”修饰车场等事物的规模，不说“大型停车”。"}], "explanations": {"非法": "非法：违反法律，修饰“停车”，指违规停车。", "免费": "语义：免费停车不收费，不应因此被罚款，与“要交罚款”矛盾。", "安全": "语义：安全停车不会违规，与“要交罚款”的语境矛盾。", "大型": "搭配：“大型”修饰车场等事物的规模，不说“大型停车”。"}, "sentence_index": 6, "correct_answer": "非法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的答案很非法，老师说要重新算。", "explanation": "这里应该用〈错误〉。非法指违反法律，答案算错要说错误，不能说非法。"}, {"text": "他的穿着很非法，朋友们都觉得奇怪。", "explanation": "这里应该用〈不合适〉。非法指违反法律，衣着是否得体、合适不能说非法，要说不合适。"}, {"text": "今天的天气很非法，我们都没出门。", "explanation": "这里应该用〈恶劣〉。非法指违反法律，天气差要说恶劣，不能说非法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种做法是非法地。", "corrected_sentence": "这种做法是非法的。", "error_description": "“非法”作谓语时要用结构助词“的”，不能用“地”。“地”用于修饰动词，“是非法地”不通，应为“是非法的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他非法得捕鱼，被抓了。", "corrected_sentence": "他非法地捕鱼，被抓了。", "error_description": "“非法”修饰动词“捕鱼”作状语，要用“地”连接；“得”用于动词后引出补语，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85848, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合法", "is_correct": true, "explanation": "合法与“非法”构成反义，指符合法律规定。"}, {"text": "善良", "is_correct": false, "explanation": "善良指心地好，与“非法”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“非法”没有反义关系。"}, {"text": "普通", "is_correct": false, "explanation": "普通指一般、不特别，与“非法”没有反义关系。"}], "correct_answer": "合法", "explanations": {"合法": "合法与“非法”构成反义，指符合法律规定。", "善良": "善良指心地好，与“非法”没有反义关系。", "清楚": "清楚指明白、不模糊，与“非法”没有反义关系。", "普通": "普通指一般、不特别，与“非法”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85848, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合法", "is_correct": true, "explanation": "合法与“非法”构成反义，指符合法律规定。"}, {"text": "诚实", "is_correct": false, "explanation": "诚实指说话做事真实，与“非法”没有反义关系。"}, {"text": "明显", "is_correct": false, "explanation": "明显指容易看出，与“非法”没有反义关系。"}, {"text": "正常", "is_correct": false, "explanation": "正常指符合常规，与“非法”没有反义关系。"}], "correct_answer": "合法", "explanations": {"合法": "合法与“非法”构成反义，指符合法律规定。", "诚实": "诚实指说话做事真实，与“非法”没有反义关系。", "明显": "明显指容易看出，与“非法”没有反义关系。", "正常": "正常指符合常规，与“非法”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85848, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不合法律规定的；违反法律的。", "primary_collocate": null, "pronunciation": "fēi fǎ", "ipa": "fei˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察查到了他的非法收入。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一家非法工厂，没有人批准。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "非法的买卖应该马上停下来。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想用非法的办法拿到这笔钱。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律不允许非法砍树。", "target_word": "非法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个网站卖的东西都是非法的。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "非法行为会让人进监狱。", "target_word": "非法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他因为非法持枪，坐了三年牢。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海关发现他带着非法物品。", "target_word": "非法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人在街上非法换钱，这样很危险。", "target_word": "非法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "非法集资", "label": "复合"}, {"form": "非法入境", "label": "复合"}], "register": "书面语", "sense_fingerprint": "不合法律规定的，违反法律的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53fc934-9efd-4505-9f2d-9389e6da67ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非法", "is_correct": true, "explanation": "非法：不合法律规定，修饰“收入”，指违法所得。"}, {"text": "正当", "is_correct": false, "explanation": "语义：“正当”指合法正当，与“警察查到”的情境矛盾。"}, {"text": "正式", "is_correct": false, "explanation": "语义：“正式收入”指正规渠道的工资报酬，不是违法所得，与“查到”的违法调查语境矛盾。"}, {"text": "免费", "is_correct": false, "explanation": "搭配：“免费”修饰商品或服务，不修饰“收入”。"}], "explanations": {"非法": "非法：不合法律规定，修饰“收入”，指违法所得。", "正当": "语义：“正当”指合法正当，与“警察查到”的情境矛盾。", "正式": "语义：“正式收入”指正规渠道的工资报酬，不是违法所得，与“查到”的违法调查语境矛盾。", "免费": "搭配：“免费”修饰商品或服务，不修饰“收入”。"}, "sentence_index": 0, "correct_answer": "非法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中非法抢球，裁判吹了哨子。", "explanation": "这里应该用〈违规〉。非法指违反法律，抢球违反的是比赛规则，要说违规。"}, {"text": "他做作业很非法，常常出错。", "explanation": "这里应该用〈不认真〉。非法只说违反法律的行为，不能形容做作业的态度。"}, {"text": "他对孩子说话很非法，孩子都很怕他。", "explanation": "这里应该用〈不耐烦〉。非法不能形容说话时的语气和态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非法", "is_correct": true, "explanation": "非法：违反法律，修饰“行为”，指会受法律惩罚的行为。"}, {"text": "正常", "is_correct": false, "explanation": "语义：正常行为不违法，不会让人进监狱，与语境矛盾。"}, {"text": "高尚", "is_correct": false, "explanation": "语义：高尚行为受人敬重，与“进监狱”的结果相矛盾。"}, {"text": "高雅", "is_correct": false, "explanation": "语域：“高雅”偏书面、文艺，不用来描述会受处罚的一般行为。"}], "explanations": {"非法": "非法：违反法律，修饰“行为”，指会受法律惩罚的行为。", "正常": "语义：正常行为不违法，不会让人进监狱，与语境矛盾。", "高尚": "语义：高尚行为受人敬重，与“进监狱”的结果相矛盾。", "高雅": "语域：“高雅”偏书面、文艺，不用来描述会受处罚的一般行为。"}, "sentence_index": 6, "correct_answer": "非法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告很非法，大家都看不懂。", "explanation": "这里应该用〈不清楚〉。非法只形容违反法律的行为，不能形容报告的表达是否清楚。"}, {"text": "他的态度很非法，大家都不想理他。", "explanation": "这里应该用〈不友好〉。非法不能形容待人的态度。"}, {"text": "这块布很非法，一拉就破。", "explanation": "这里应该用〈不结实〉。非法指违反法律，布料牢固程度要说不结实，不能说非法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是非法地行为。", "corrected_sentence": "这是非法的行为。", "error_description": "“非法”修饰名词“行为”时要用“的”，不能用“地”；“地”用于修饰动词或形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在街上非法了卖烟，被警察抓走了。", "corrected_sentence": "他在街上非法卖烟，被警察抓走了。", "error_description": "“非法”后面不能直接加“了”，“了”表示动作完成，应说“非法卖烟”；“非法了卖烟”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
