INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85855, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“还是”是在两样东西里问你要哪一样。", "primary_collocate": null, "pronunciation": "hái shi", "ipa": "xaɪ̯˧˥ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "你喝茶还是喝咖啡？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐地铁还是坐公共汽车去？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是老师还是学生？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想吃米饭还是面条？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天去还是后天去，你决定吧。", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末你在家还是出去玩？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件是红的还是蓝的？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢猫还是喜欢狗？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天看电影还是去公园？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用手机付钱还是用现金？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "连词，用于选择疑问句，A还是B？让人二选一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fb035c5-9777-447c-8d06-6c17b4aedd72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85855, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "还是", "is_correct": true, "explanation": "正确答案。hái shi 是表示二选一的连词，意思是在两者之间选择。"}, {"text": "孩子", "is_correct": false, "explanation": "hái 相同，但 shi 与 zi 声母不同，意思是孩子。"}, {"text": "海事", "is_correct": false, "explanation": "hǎi（第三声）与 hái（第二声）声调不同，意思是海上事务。"}, {"text": "海狮", "is_correct": false, "explanation": "hǎi 与 hái 声调不同，shī 与 shi 声调也不同，意思是海狮。"}], "explanations": {"还是": "正确答案。hái shi 是表示二选一的连词，意思是在两者之间选择。", "孩子": "hái 相同，但 shi 与 zi 声母不同，意思是孩子。", "海事": "hǎi（第三声）与 hái（第二声）声调不同，意思是海上事务。", "海狮": "hǎi 与 hái 声调不同，shī 与 shi 声调也不同，意思是海狮。"}, "sentence_index": null, "correct_answer": "还是"}, "level_3": {"options": [{"text": "还是", "is_correct": true, "explanation": "连词“还是”表示二选一，符合选择问句的句意。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表原因，与二选一的问句不符。"}, {"text": "但是", "is_correct": false, "explanation": "搭配：“但是”要连接转折的分句，前面没有对立内容，不能用于选择问句。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表结果，与选择问句的句意不符。"}], "explanations": {"还是": "连词“还是”表示二选一，符合选择问句的句意。", "因为": "语义：“因为”表原因，与二选一的问句不符。", "但是": "搭配：“但是”要连接转折的分句，前面没有对立内容，不能用于选择问句。", "所以": "语义：“所以”表结果，与选择问句的句意不符。"}, "sentence_index": 0, "correct_answer": "还是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天你来还是我去。", "explanation": "这里应该用〈或者〉。“还是”在陈述句中一般只见于“X还是Y都行”之类固定格式，此句没有这类格式，列举可能时应用“或者”。"}, {"text": "这个苹果比那个还是甜。", "explanation": "这里应该用〈更〉。还是不表示程度的进一步加深；比较句中表示“更加”要用“更”。"}, {"text": "我们需要苹果、香蕉还是橘子。", "explanation": "这里应该用〈或者〉。还是用于问句请对方选择，陈述句列举可能时要用或者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还是", "is_correct": true, "explanation": "连词“还是”表示二选一，符合句意。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表让步，后面要接转折分句，句意不符。"}, {"text": "然而", "is_correct": false, "explanation": "语域：“然而”偏书面，口语选择问句不用。"}, {"text": "不然", "is_correct": false, "explanation": "语义：“不然”表示否则，此处没有假设条件。"}], "explanations": {"还是": "连词“还是”表示二选一，符合句意。", "虽然": "语义：“虽然”表让步，后面要接转折分句，句意不符。", "然而": "语域：“然而”偏书面，口语选择问句不用。", "不然": "语义：“不然”表示否则，此处没有假设条件。"}, "sentence_index": 6, "correct_answer": "还是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑比那台还是快。", "explanation": "这里应该用〈更〉。还是不表示程度的进一步加深；比较句中要用“更”。"}, {"text": "他喜欢红的、蓝的还是绿的。", "explanation": "这里应该用〈或者〉。还是用于问句请对方选择，陈述句列举喜好时要用或者。"}, {"text": "我用手机付钱还是用现金。", "explanation": "这里应该用〈或者〉。“还是”在陈述句中一般只见于“X还是Y都行”之类固定格式，此句没有这类格式，应改为“或者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下班以后你是回家或者还是去健身房？", "corrected_sentence": "下班以后你是回家还是去健身房？", "error_description": "多加了连词“或者”，与“还是”叠用。选择问句只用“还是”，应去掉“或者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次出差你还是坐飞机还是坐火车？", "corrected_sentence": "这次出差你坐飞机还是坐火车？", "error_description": "多加了副词“还是”（仍然），与选择连词“还是”重复。“你还是坐飞机”表示“仍然坐飞机”，与选择句意不符，应删去前面的“还是”，即“你坐飞机还是坐火车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec8827ef-905b-46dc-80de-aa40597b3712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
