INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85859, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示否定判断，意思是“并不是”，多用于纠正对方的误解。", "primary_collocate": null, "pronunciation": "bìng fēi", "ipa": "piŋ˥˩ fei˥", "syllable_count": 2, "sentences": [{"text": "这并非他一个人的错。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "成功并非靠运气。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "并非所有人都喜欢吃辣。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事并非你想的那样。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他并非不想去，只是没时间。", "target_word": "并非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贵的东西并非都是好东西。", "target_word": "并非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好中文并非很难。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他今天没来，并非因为生病。", "target_word": "并非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这并非我第一次来北京。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "并非每个孩子都爱看书。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "並非", "label": "繁体"}], "register": "书面", "sense_fingerprint": "并非：否定判断，纠正误会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8be57f03-7fb2-4413-ac65-d96db36736d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "并非", "is_correct": true, "explanation": "并非：表示否定判断，纠正误会，这里指“不是他一个人的错”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示得到愉快，与“错”不合。"}, {"text": "犯下", "is_correct": false, "explanation": "配价：“犯下”要求人作施事，“这”不能作主语去犯错。"}, {"text": "赢得", "is_correct": false, "explanation": "语义：“赢得”指取得胜利或好评，与“错”不合。"}], "explanations": {"并非": "并非：表示否定判断，纠正误会，这里指“不是他一个人的错”。", "享受": "语义：“享受”表示得到愉快，与“错”不合。", "犯下": "配价：“犯下”要求人作施事，“这”不能作主语去犯错。", "赢得": "语义：“赢得”指取得胜利或好评，与“错”不合。"}, "sentence_index": 0, "correct_answer": "并非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我并非去过北京，所以很熟悉那里。", "explanation": "这里应该用〈没〉。“并非”用于否定判断，不用于否定动作或经历。"}, {"text": "我并非会游泳，所以不去海边。", "explanation": "这里应该用〈不〉。“并非”不与“会”这类能愿动词连用。"}, {"text": "我并非吃饭，所以不饿。", "explanation": "这里应该用〈不〉。“并非”不能用来否定“吃饭”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "并非", "is_correct": true, "explanation": "并非：否定“学好中文很难”这一看法，表示并不是这样。"}, {"text": "认为", "is_correct": false, "explanation": "配价：“认为”需要人作主语并带小句，“学好中文认为很难”不通。"}, {"text": "嫌", "is_correct": false, "explanation": "语义：“嫌”表示厌恶，与句子所述的客观判断不合。"}, {"text": "获得", "is_correct": false, "explanation": "语义：“获得”指取得事物，不能用于“学好中文很难”这一判断。"}], "explanations": {"并非": "并非：否定“学好中文很难”这一看法，表示并不是这样。", "认为": "配价：“认为”需要人作主语并带小句，“学好中文认为很难”不通。", "嫌": "语义：“嫌”表示厌恶，与句子所述的客观判断不合。", "获得": "语义：“获得”指取得事物，不能用于“学好中文很难”这一判断。"}, "sentence_index": 6, "correct_answer": "并非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他并非喝酒，所以很清醒。", "explanation": "这里应该用〈不〉。“并非”不用于否定“喝酒”这类动作。"}, {"text": "她并非能唱歌，所以参加了合唱队。", "explanation": "这里应该用〈不〉。“并非”不与“能”这类能愿动词连用。"}, {"text": "这封信他并非读过。", "explanation": "这里应该用〈没〉。“并非”不用于否定“读过”这类经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试不并非很难。", "corrected_sentence": "这次考试并非很难。", "error_description": "重复否定：“并非”本身已表示否定，前面不能再加“不”，应为“并非很难”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
