INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85860, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "并不是；一点也不是（用于加强否定）。", "primary_collocate": null, "pronunciation": "bìng fēi", "ipa": "piŋ˥˩ fei˥", "syllable_count": 2, "sentences": [{"text": "我并非故意迟到，请您原谅。", "target_word": "并非", "complexity_tier": "T3", "furigana": "wǒ bìngfēi gùyì chídào, qǐng nín yuánliàng。", "sentence_source": "generated"}, {"text": "他并非老师，而是医生。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这并非小事，请认真对待。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "事情并非如此简单。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我并非不相信你。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她并非坏人，你别误会。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这并非钱的问题。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他并非不努力，只是方法不对。", "target_word": "并非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说话并非越多越好。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里的冬天并非很冷。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "並非", "label": "繁体"}], "register": "书面", "sense_fingerprint": "并非：加强否定，一点也不是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8be57f03-7fb2-4413-ac65-d96db36736d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "并非", "is_correct": true, "explanation": "并非：并不是故意，表示否定，符合道歉的语境。"}, {"text": "希望", "is_correct": false, "explanation": "语义：“希望”表示愿望，与“故意迟到”的道歉语境不合。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”需要带言语内容，“我说故意迟到”不通。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示愉快，与“迟到”和道歉不合。"}], "explanations": {"并非": "并非：并不是故意，表示否定，符合道歉的语境。", "希望": "语义：“希望”表示愿望，与“故意迟到”的道歉语境不合。", "说": "配价：“说”需要带言语内容，“我说故意迟到”不通。", "享受": "语义：“享受”表示愉快，与“迟到”和道歉不合。"}, "sentence_index": 0, "correct_answer": "并非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我并非见过他，所以很陌生。", "explanation": "这里应该用〈没〉。“并非”用于否定判断，不用于否定“见过”这类经历。"}, {"text": "她并非能开车，所以坐公交。", "explanation": "这里应该用〈不〉。“并非”不与“能”这类能愿动词连用。"}, {"text": "我并非睡觉，所以没有休息。", "explanation": "这里应该用〈不〉。“并非”不能用来否定“睡觉”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "并非", "is_correct": true, "explanation": "并非：表示“不是这样”，否定“这是钱的问题”这一判断。"}, {"text": "缺乏", "is_correct": false, "explanation": "语义：“缺乏”表示不足，不能说“缺乏钱的问题”。"}, {"text": "认为", "is_correct": false, "explanation": "配价：“认为”需要人作主语，“这认为钱的问题”不通。"}, {"text": "记录", "is_correct": false, "explanation": "语义：“记录”指把信息写下，不能与“钱的问题”搭配。"}], "explanations": {"并非": "并非：表示“不是这样”，否定“这是钱的问题”这一判断。", "缺乏": "语义：“缺乏”表示不足，不能说“缺乏钱的问题”。", "认为": "配价：“认为”需要人作主语，“这认为钱的问题”不通。", "记录": "语义：“记录”指把信息写下，不能与“钱的问题”搭配。"}, "sentence_index": 6, "correct_answer": "并非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他并非写作业，所以在玩游戏。", "explanation": "这里应该用〈不〉。“并非”不用于否定“写作业”这类动作。"}, {"text": "我们并非会说法语，所以请翻译。", "explanation": "这里应该用〈不〉。“并非”不与“会”这类能愿动词连用。"}, {"text": "这条路并非走过。", "explanation": "这里应该用〈没〉。“并非”不用于否定“走过”这类经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的话不并非玩笑。", "corrected_sentence": "他的话并非玩笑。", "error_description": "重复否定：“并非”本身已表示否定，前面不能再加“不”，应为“并非玩笑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份礼物很并非很贵重。", "corrected_sentence": "这份礼物并非很贵重。", "error_description": "位置错误：程度副词“很”不能放在“并非”之前，应为“这份礼物并非很贵重”，“很并非”语序不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
