INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "名词，指在所说的范围、事物之中。", "primary_collocate": null, "pronunciation": "qí zhōng", "ipa": "tɕʰi˧˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这次来了三十个客人，其中五个是外国人。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有很多爱好，其中游泳最受欢迎。", "target_word": "其中", "complexity_tier": "T3", "furigana": "qízhōng", "sentence_source": "generated"}, {"text": "书店里的书很多，其中很多是新书。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听了十首歌，其中两首很好听。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题很难，其中一个我还没想好。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了一百张照片，其中几张很漂亮。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的东西不贵，其中水果最便宜。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试有四个人没过，其中一个是我朋友。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司有八个人，其中三个是女的。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国有很多节日，其中春节最热闹。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指所说的范围或事物之中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '978170ba-3e1a-45cc-a780-edc5c61ec137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
