INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85864, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "到达", "is_correct": true, "explanation": "到达与“出发”构成反义，指抵达目的地。"}, {"text": "挖掘", "is_correct": false, "explanation": "挖掘指向下挖土或深入发掘，与“出发”没有反义关系。"}, {"text": "欢迎", "is_correct": false, "explanation": "欢迎指热情接待，与“出发”没有反义关系。"}, {"text": "检查", "is_correct": false, "explanation": "检查指仔细查看，与“出发”没有反义关系。"}], "correct_answer": "到达", "explanations": {"到达": "到达与“出发”构成反义，指抵达目的地。", "挖掘": "挖掘指向下挖土或深入发掘，与“出发”没有反义关系。", "欢迎": "欢迎指热情接待，与“出发”没有反义关系。", "检查": "检查指仔细查看，与“出发”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85864, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开原地到别处去；开始行程。", "primary_collocate": null, "pronunciation": "chū fā", "ipa": "ʈʂʰu˥ fa˥", "syllable_count": 2, "sentences": [{"text": "我们明天早上七点出发。", "target_word": "出发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车几点出发？", "target_word": "出发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你们准备好了就出发吧。", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们已经从北京出发了。", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天还没亮，爸爸就出发去机场了。", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出发前，请检查一下行李。", "target_word": "出发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家带着地图出发了。", "target_word": "出发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行我们从上海出发，坐船去海南。", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我出发的时候，天正在下雨。", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队员们到齐了，马上就要出发。", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "出发了", "label": "体标"}, {"form": "出发过", "label": "体标"}, {"form": "出发点", "label": "复合"}, {"form": "出發", "label": "繁体"}], "register": "通用", "sense_fingerprint": "离开原地，开始行程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53fc934-9efd-4505-9f2d-9389e6da67ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85864, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出发", "is_correct": true, "explanation": "出发 chū fā：离开原地，开始行程。"}, {"text": "除法", "is_correct": false, "explanation": "声调不同：chú（第二声）fǎ（第三声）与 chū fā（第一声）不同，意思是数学中的除法。"}, {"text": "处罚", "is_correct": false, "explanation": "声调不同：chǔ（第三声）fá（第二声）与 chū fā（第一声）不同，意思是处罚。"}, {"text": "出访", "is_correct": false, "explanation": "fǎng 与 fā 韵母不同（-ang 与 -a），意思是出国访问。"}], "explanations": {"出发": "出发 chū fā：离开原地，开始行程。", "除法": "声调不同：chú（第二声）fǎ（第三声）与 chū fā（第一声）不同，意思是数学中的除法。", "处罚": "声调不同：chǔ（第三声）fá（第二声）与 chū fā（第一声）不同，意思是处罚。", "出访": "fǎng 与 fā 韵母不同（-ang 与 -a），意思是出国访问。"}, "sentence_index": null, "correct_answer": "出发"}, "level_3": {"options": [{"text": "出发", "is_correct": true, "explanation": "出发：离开原地开始行程，与“早上七点”搭配，指动身的时间。"}, {"text": "离婚", "is_correct": false, "explanation": "语义：“离婚”与行程无关，放在“早上七点”后语义不通。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体状况，与“明天早上七点”的出行安排无关。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体症状，与出行安排无关，放在此处语义不通。"}], "explanations": {"出发": "出发：离开原地开始行程，与“早上七点”搭配，指动身的时间。", "离婚": "语义：“离婚”与行程无关，放在“早上七点”后语义不通。", "发烧": "语义：“发烧”是身体状况，与“明天早上七点”的出行安排无关。", "咳嗽": "语义：“咳嗽”是身体症状，与出行安排无关，放在此处语义不通。"}, "sentence_index": 0, "correct_answer": "出发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影八点出发了。", "explanation": "这里应该用〈开演〉。出发只指人或交通工具动身去别处，电影开始放映要说开演，不能说出发。"}, {"text": "这首歌慢慢出发了。", "explanation": "这里应该用〈响起〉。出发只指人或交通工具动身，歌曲响起不能说出发。"}, {"text": "这场比赛刚刚出发。", "explanation": "这里应该用〈开始〉。出发指人或车辆动身，比赛开始不说出发，要说开始。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出发", "is_correct": true, "explanation": "出发：离开原地开始行程，与“带着地图”的旅行语境相符。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆是停留原地不动，与“带着地图”的行程语境矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是停止活动，与“带着地图”表示的行进不符。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”不能与“带着地图”构成行进的语义关系，语境不符。"}], "explanations": {"出发": "出发：离开原地开始行程，与“带着地图”的旅行语境相符。", "发呆": "语义：发呆是停留原地不动，与“带着地图”的行程语境矛盾。", "睡觉": "语义：睡觉是停止活动，与“带着地图”表示的行进不符。", "游泳": "搭配：“游泳”不能与“带着地图”构成行进的语义关系，语境不符。"}, "sentence_index": 6, "correct_answer": "出发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨终于出发了，天空很晴朗。", "explanation": "这里应该用〈停〉。出发指人或车辆开始行程，雨停不能说出发。"}, {"text": "这本书下个月就要出发了。", "explanation": "这里应该用〈出版〉。出发指动身前往，书籍发行要说出版。"}, {"text": "灯突然出发了，屋里一片黑暗。", "explanation": "这里应该用〈熄灭〉。出发只用于人或交通工具动身，灯火不能说出发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们下午两点出发着去上海。", "corrected_sentence": "他们下午两点出发去上海。", "error_description": "“出发”后不能加“着”表示持续，这里说的是动身这一动作，应说“出发去上海”，“出发着去上海”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们明天早上上海出发去北京。", "corrected_sentence": "他们明天早上从上海出发去北京。", "error_description": "表示出发地点的介词“从”不能省略，应说“从上海出发”；省去“从”后，“上海出发”不成词组，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
