INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85866, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示转折，语气比“但是”轻。", "primary_collocate": null, "pronunciation": "bú guò", "ipa": "pu˧˥ kuo˥˩", "syllable_count": 2, "sentences": [{"text": "房子不大，不过很干净。", "target_word": "不过", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我同意你，不过我有一个问题。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他来过北京，不过只住了两天。", "target_word": "不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋很舒服，不过颜色我不喜欢。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买车，不过现在钱不够。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唱得不错，不过声音有点小。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路不远，不过走着去要半小时。", "target_word": "不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题很难，不过我做对了。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我也喜欢旅行，不过更喜欢在家。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说他会来，不过我觉得他很忙。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示转折的连词，语气比但是轻，常补充保留意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d8e7589-5b4b-4fd1-9e86-38e415da95b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85866, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不过", "is_correct": true, "explanation": "正确答案。“不过”读 bú guò，表示转折，语气比“但是”轻。"}, {"text": "不够", "is_correct": false, "explanation": "gòu（第四声）与 guò 的韵母不同（ou 与 uo），意思是“不足、不够”。"}, {"text": "不错", "is_correct": false, "explanation": "cuò 与 guò 的声母不同（c 与 g），意思是“还可以”。"}, {"text": "不顾", "is_correct": false, "explanation": "gù 与 guò 的韵母不同（少一个 o），意思是“不管”。"}, {"text": "不怪", "is_correct": false, "explanation": "guài 与 guò 的韵母不同（uai 与 uo），意思是“不责怪”。"}], "explanations": {"不过": "正确答案。“不过”读 bú guò，表示转折，语气比“但是”轻。", "不够": "gòu（第四声）与 guò 的韵母不同（ou 与 uo），意思是“不足、不够”。", "不错": "cuò 与 guò 的声母不同（c 与 g），意思是“还可以”。", "不顾": "gù 与 guò 的韵母不同（少一个 o），意思是“不管”。", "不怪": "guài 与 guò 的韵母不同（uai 与 uo），意思是“不责怪”。"}, "sentence_index": null, "correct_answer": "不过"}, "level_3": {"options": [{"text": "不过", "is_correct": true, "explanation": "正确。“不过”表示转折：前句说房子不大，后句“很干净”形成转折，语气较轻。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，而“很干净”不是“房子不大”的原因，前后关系颠倒。"}, {"text": "如果", "is_correct": false, "explanation": "搭配：“如果”要与“就”呼应，且后句应是假设条件，不能接在“房子不大，”之后。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，“房子不大”与“很干净”之间没有先后关系。"}], "explanations": {"不过": "正确。“不过”表示转折：前句说房子不大，后句“很干净”形成转折，语气较轻。", "因为": "语义：“因为”引出原因，而“很干净”不是“房子不大”的原因，前后关系颠倒。", "如果": "搭配：“如果”要与“就”呼应，且后句应是假设条件，不能接在“房子不大，”之后。", "然后": "语义：“然后”表示先后顺序，“房子不大”与“很干净”之间没有先后关系。"}, "sentence_index": 0, "correct_answer": "不过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "因为天气很热，不过我们去了公园。", "explanation": "这里应该用〈所以〉。“因为……”引出原因，后面要接结果；“不过”表示转折，不能与因果搭配。"}, {"text": "只要努力，不过一定会成功。", "explanation": "这里应该用〈就〉。“只要……就……”表示条件，“不过”表示转折，不能放在条件与结果之间。"}, {"text": "他一边工作，不过在学习英语。", "explanation": "这里应该用〈同时〉。两件事同时进行，不是转折，“不过”不能连接并列的同时动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不过", "is_correct": true, "explanation": "正确。“不过”表示转折：路不远，但走着去要半小时，前后形成对比。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，“路不远”和“走着去要半小时”之间没有先后关系。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示由前面引出的动作，“要半小时”不是“路不远”带来的结果。"}, {"text": "况且", "is_correct": false, "explanation": "语域：“况且”偏书面，且表示递进补充，与“路不远”的前后关系不符。"}], "explanations": {"不过": "正确。“不过”表示转折：路不远，但走着去要半小时，前后形成对比。", "然后": "语义：“然后”表示先后顺序，“路不远”和“走着去要半小时”之间没有先后关系。", "于是": "语义：“于是”表示由前面引出的动作，“要半小时”不是“路不远”带来的结果。", "况且": "语域：“况且”偏书面，且表示递进补充，与“路不远”的前后关系不符。"}, "sentence_index": 6, "correct_answer": "不过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我先吃饭，不过去散步。", "explanation": "这里应该用〈然后〉。前后是先后顺序，不是转折，“不过”会让人以为吃饭与散步之间有对立。"}, {"text": "他会游泳，不过会打篮球。", "explanation": "这里应该用〈而且〉。前后是并列补充，“不过”表示转折，与原意不符。"}, {"text": "即使下雨，不过我们去。", "explanation": "这里应该用〈也〉。“即使”要与“也”搭配，“不过”不能放在让步分句之后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区很安静，但是不过房租有点高。", "corrected_sentence": "这个小区很安静，不过房租有点高。", "error_description": "“但是”与“不过”重复使用，表示转折的连词只用一个。错误：“但是不过”；正确：“不过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个饭馆很远，不过了菜很好吃。", "corrected_sentence": "这个饭馆很远，不过菜很好吃。", "error_description": "“不过”是连词，后面不能加“了”。错误：“不过了菜很好吃”；正确：“不过菜很好吃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
