INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85867, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取是把东西拿到手里。", "primary_collocate": null, "pronunciation": "qǔ", "ipa": "tɕʰy˨˩˦", "syllable_count": 1, "sentences": [{"text": "我去楼上取我的书包。", "target_word": "取", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他走到柜子前，取了一件衣服。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请到前台取你的钥匙。", "target_word": "取", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈从冰箱里取了一瓶牛奶。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了带伞，回家去取。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他伸手去取架子上的帽子。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先在这儿等，我去车上取包。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打开箱子，取了一双鞋。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去干洗店取衣服的时候，别忘了带票。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我去办公室取作业本。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "取了", "label": "体标"}, {"form": "取过", "label": "体标"}], "register": "通用", "sense_fingerprint": "把东西从某处拿到手里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53fc934-9efd-4505-9f2d-9389e6da67ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85867, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "取", "is_correct": true, "explanation": "正确：取（qǔ）是把东西拿到手里。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，意思是去。"}, {"text": "曲", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是弯曲或曲子。"}, {"text": "举", "is_correct": false, "explanation": "j 与 q 声母不同，声调相同，意思是举起。"}, {"text": "许", "is_correct": false, "explanation": "x 与 q 声母不同，声调相同，意思是也许或允许。"}, {"text": "区", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是区域。"}], "explanations": {"取": "正确：取（qǔ）是把东西拿到手里。", "去": "qù（第四声）与 qǔ（第三声）声调不同，意思是去。", "曲": "qū（第一声）与 qǔ（第三声）声调不同，意思是弯曲或曲子。", "举": "j 与 q 声母不同，声调相同，意思是举起。", "许": "x 与 q 声母不同，声调相同，意思是也许或允许。", "区": "qū（第一声）与 qǔ（第三声）声调不同，意思是区域。"}, "sentence_index": null, "correct_answer": "取"}, "level_3": {"options": [{"text": "取", "is_correct": true, "explanation": "正确：取表示把东西从某处拿到手里，与“去楼上”和“书包”相合。"}, {"text": "寄", "is_correct": false, "explanation": "语义：“寄”指通过邮递把东西送出去，与“去楼上”以及拿自己的书包不合。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”要从商家得到商品，而“我的书包”已经属于我，不能去买。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指把东西交给别人，句中是自己去楼上拿书包，与“取”的动作方向相反。"}], "explanations": {"取": "正确：取表示把东西从某处拿到手里，与“去楼上”和“书包”相合。", "寄": "语义：“寄”指通过邮递把东西送出去，与“去楼上”以及拿自己的书包不合。", "买": "语义：“买”要从商家得到商品，而“我的书包”已经属于我，不能去买。", "送": "语义：“送”指把东西交给别人，句中是自己去楼上拿书包，与“取”的动作方向相反。"}, "sentence_index": 0, "correct_answer": "取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去机场取朋友。", "explanation": "这里应该用〈接〉。取是把东西拿到手里，用于物品；接人要用“接”，应说“接朋友”，不能说“取朋友”。"}, {"text": "他在树上取了一个苹果。", "explanation": "这里应该用〈摘〉。摘指从植物上采下果实，取不用于从树上采果子，应说“摘了一个苹果”。"}, {"text": "他向我取了五百块钱。", "explanation": "这里应该用〈收〉。收指向别人收费、收钱，取只表示拿到手里，不能用于向人收钱，应说“收了五百块钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85867, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "取", "is_correct": true, "explanation": "正确：取（qǔ）是把东西拿到手里。"}, {"text": "趣", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，意思是趣味。"}, {"text": "屈", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是弯曲或受委屈。"}, {"text": "驱", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是驱赶。"}, {"text": "其", "is_correct": false, "explanation": "qí（第二声）与 qǔ（第三声）声调不同，意思是其他或他的。"}, {"text": "起", "is_correct": false, "explanation": "qǐ 与 qǔ 只有元音不同（i 与 u），声调相同，意思是起来。"}], "explanations": {"取": "正确：取（qǔ）是把东西拿到手里。", "趣": "qù（第四声）与 qǔ（第三声）声调不同，意思是趣味。", "屈": "qū（第一声）与 qǔ（第三声）声调不同，意思是弯曲或受委屈。", "驱": "qū（第一声）与 qǔ（第三声）声调不同，意思是驱赶。", "其": "qí（第二声）与 qǔ（第三声）声调不同，意思是其他或他的。", "起": "qǐ 与 qǔ 只有元音不同（i 与 u），声调相同，意思是起来。"}, "sentence_index": null, "correct_answer": "取"}, "level_3": {"options": [{"text": "取", "is_correct": true, "explanation": "正确：取表示把包从车上拿下来，与“在这儿等”的语境相合。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”多用于果实、眼镜、帽子等，不说“摘包”。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是用力打击使东西破碎，与“先在这儿等”的平静语境不合。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者，“我去车上给包”缺少受者，句子不完整。"}], "explanations": {"取": "正确：取表示把包从车上拿下来，与“在这儿等”的语境相合。", "摘": "搭配：“摘”多用于果实、眼镜、帽子等，不说“摘包”。", "砸": "语义：“砸”是用力打击使东西破碎，与“先在这儿等”的平静语境不合。", "给": "配价：“给”需要接受者，“我去车上给包”缺少受者，句子不完整。"}, "sentence_index": 6, "correct_answer": "取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他取上了一顶帽子。", "explanation": "这里应该用〈戴〉。戴指把帽子、眼镜等穿戴在身上，取不能表示“戴上”，应说“戴上了一顶帽子”。"}, {"text": "他在路边取了一分钱。", "explanation": "这里应该用〈捡〉。捡指拾起地上掉落的东西，取不用于从地上拾物，应说“捡了一分钱”。"}, {"text": "他把作业取上去了。", "explanation": "这里应该用〈交〉。交指把东西递给或上缴给别人，取不能表示交作业，应说“把作业交上去了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从书包里出取了一本书。", "corrected_sentence": "他从书包里取出了一本书。", "error_description": "语序错误：“取出”中“出”是补语，应紧跟在“取”之后，应为“取出了一本书”，不能把“出”放到“取”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去门口了取一把伞。", "corrected_sentence": "他去门口取了一把伞。", "error_description": "语序错误：“了”应紧跟动词之后，表示动作完成，应为“取了一把伞”，不能放在“取”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85868, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "予", "is_correct": true, "explanation": "正确：“予”是给出的意思，与“取”（获得）构成反义，二者合称“取予”。"}, {"text": "买", "is_correct": false, "explanation": "“买”是用钱换得商品，与“取”的领取义不构成对立，不是反义词。"}, {"text": "卖", "is_correct": false, "explanation": "“卖”与“买”互为反义，但与“取”的领取义没有对立关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”是书写的意思，与“取”没有对立关系，不是反义词。"}], "correct_answer": "予", "explanations": {"予": "正确：“予”是给出的意思，与“取”（获得）构成反义，二者合称“取予”。", "买": "“买”是用钱换得商品，与“取”的领取义不构成对立，不是反义词。", "卖": "“卖”与“买”互为反义，但与“取”的领取义没有对立关系。", "写": "“写”是书写的意思，与“取”没有对立关系，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85868, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舍", "is_correct": true, "explanation": "正确：“舍”是放弃、不要的意思，与“取”构成反义，如“取舍”一词中的对立关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”是书写的意思，与“取”没有对立关系，不是反义词。"}, {"text": "借", "is_correct": false, "explanation": "“借”是暂时拿别人的东西来用，与“还”互为反义，但与“取”不构成反义。"}, {"text": "洗", "is_correct": false, "explanation": "“洗”是清洁的意思，与“取”没有对立关系，不是反义词。"}], "correct_answer": "舍", "explanations": {"舍": "正确：“舍”是放弃、不要的意思，与“取”构成反义，如“取舍”一词中的对立关系。", "写": "“写”是书写的意思，与“取”没有对立关系，不是反义词。", "借": "“借”是暂时拿别人的东西来用，与“还”互为反义，但与“取”不构成反义。", "洗": "“洗”是清洁的意思，与“取”没有对立关系，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿；拿到；获得。", "primary_collocate": null, "pronunciation": "qǔ", "ipa": "tɕʰy˨˩˦", "syllable_count": 1, "sentences": [{"text": "我要去银行取钱。", "target_word": "取", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "快递到了，我下楼去取。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在机器上取了五百块钱。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你取到去上海的火车票了吗？", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去医院取药，一会儿就回来。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去窗口取号，然后坐着等。", "target_word": "取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在自助机上取了一张票。", "target_word": "取", "complexity_tier": "T3", "furigana": "wǒ zài zì zhù jī shàng qǔ le yì zhāng piào。", "sentence_source": "generated"}, {"text": "凭这个号码，你可以去前台取包裹。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把存了很久的钱都取了。", "target_word": "取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下班前，我得去邮局取信。", "target_word": "取", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "取了", "label": "体标"}, {"form": "取过", "label": "体标"}, {"form": "取款", "label": "复合"}, {"form": "取钱", "label": "复合"}], "register": "通用", "sense_fingerprint": "去某处拿到或领到属于自己的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53fc934-9efd-4505-9f2d-9389e6da67ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85868, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "取", "is_correct": true, "explanation": "正确：取（qǔ）在此表示领取属于自己的东西。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，意思是去。"}, {"text": "区", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是区域。"}, {"text": "举", "is_correct": false, "explanation": "j 与 q 声母不同，声调相同，意思是举起。"}, {"text": "许", "is_correct": false, "explanation": "x 与 q 声母不同，声调相同，意思是也许或允许。"}, {"text": "起", "is_correct": false, "explanation": "qǐ 与 qǔ 只有元音不同（i 与 u），声调相同，意思是起来。"}], "explanations": {"取": "正确：取（qǔ）在此表示领取属于自己的东西。", "去": "qù（第四声）与 qǔ（第三声）声调不同，意思是去。", "区": "qū（第一声）与 qǔ（第三声）声调不同，意思是区域。", "举": "j 与 q 声母不同，声调相同，意思是举起。", "许": "x 与 q 声母不同，声调相同，意思是也许或允许。", "起": "qǐ 与 qǔ 只有元音不同（i 与 u），声调相同，意思是起来。"}, "sentence_index": null, "correct_answer": "取"}, "level_3": {"options": [{"text": "取", "is_correct": true, "explanation": "正确：取钱是从银行拿出属于自己的钱，与“去银行”相合。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”指暗中拿走别人的东西，与去银行办正常业务的目的不合。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的对象是商品，不能说“买钱”。"}, {"text": "赢", "is_correct": false, "explanation": "语义：“赢”指在比赛或赌博中获胜，与“去银行”的语境不合。"}], "explanations": {"取": "正确：取钱是从银行拿出属于自己的钱，与“去银行”相合。", "偷": "语义：“偷”指暗中拿走别人的东西，与去银行办正常业务的目的不合。", "买": "搭配：“买”的对象是商品，不能说“买钱”。", "赢": "语义：“赢”指在比赛或赌博中获胜，与“去银行”的语境不合。"}, "sentence_index": 0, "correct_answer": "取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去车站取朋友。", "explanation": "这里应该用〈接〉。接人要用“接”，取是拿取物品的动作，不能用于人，应说“接朋友”。"}, {"text": "他向顾客取了二十块钱。", "explanation": "这里应该用〈收〉。收指向别人收钱，取只表示拿到手里，不能表示向人收钱，应说“收了二十块钱”。"}, {"text": "他取上了一件外套。", "explanation": "这里应该用〈穿〉。穿指把衣服穿在身上，取不能表示穿衣，应说“穿上了一件外套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85868, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "取", "is_correct": true, "explanation": "正确：取（qǔ）在此表示领取属于自己的东西。"}, {"text": "趣", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，意思是趣味。"}, {"text": "屈", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是弯曲或受委屈。"}, {"text": "驱", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是驱赶。"}, {"text": "其", "is_correct": false, "explanation": "qí（第二声）与 qǔ（第三声）声调不同，意思是其他或他的。"}, {"text": "曲", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是弯曲或曲子。"}], "explanations": {"取": "正确：取（qǔ）在此表示领取属于自己的东西。", "趣": "qù（第四声）与 qǔ（第三声）声调不同，意思是趣味。", "屈": "qū（第一声）与 qǔ（第三声）声调不同，意思是弯曲或受委屈。", "驱": "qū（第一声）与 qǔ（第三声）声调不同，意思是驱赶。", "其": "qí（第二声）与 qǔ（第三声）声调不同，意思是其他或他的。", "曲": "qū（第一声）与 qǔ（第三声）声调不同，意思是弯曲或曲子。"}, "sentence_index": null, "correct_answer": "取"}, "level_3": {"options": [{"text": "取", "is_correct": true, "explanation": "正确：取了一张票，表示从机器上拿到属于自己的票，与语境相合。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是重重扔下，与在自助机上领票的动作不合。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是点火燃烧，自助机出票不会是烧票，与语境不合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”多用于照片、衣物等，不能说“洗票”。"}], "explanations": {"取": "正确：取了一张票，表示从机器上拿到属于自己的票，与语境相合。", "摔": "语义：“摔”是重重扔下，与在自助机上领票的动作不合。", "烧": "语义：“烧”是点火燃烧，自助机出票不会是烧票，与语境不合。", "洗": "搭配：“洗”多用于照片、衣物等，不能说“洗票”。"}, "sentence_index": 6, "correct_answer": "取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把试卷取给老师了。", "explanation": "这里应该用〈交〉。交指把东西递交给别人，取不能表示交给老师，应说“把试卷交给老师了”。"}, {"text": "她取上了一副耳环。", "explanation": "这里应该用〈戴〉。戴指把耳环等戴在身上，取不能表示戴耳环，应说“戴上了一副耳环”。"}, {"text": "她在花园里取了几朵花。", "explanation": "这里应该用〈摘〉。摘指从植物上采下花朵，取不用于采花，应说“摘了几朵花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去邮局出取了包裹。", "corrected_sentence": "我去邮局取出了包裹。", "error_description": "语序错误：“取出”中“出”是补语，应紧跟在“取”之后，应为“取出了包裹”，不能把“出”放到“取”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下楼去了取一个包裹。", "corrected_sentence": "他下楼去取了一个包裹。", "error_description": "语序错误：“了”应放在动词“取”之后，表示动作完成，不能放在动词之前。正确应为：取了一个包裹。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
