INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85873, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“那么”是说像那样，用来说样子或者多少。", "primary_collocate": null, "pronunciation": "nà me", "ipa": "na˥˩ mə", "syllable_count": 2, "sentences": [{"text": "这个房间没有那个那么大。", "target_word": "那么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上有那么多菜，我们吃不完。", "target_word": "那么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么那么难过？", "target_word": "那么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唱歌那么好听，大家都喜欢听。", "target_word": "那么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要那么大声说话，宝宝在睡觉。", "target_word": "那么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没想到路上有那么多人。", "target_word": "那么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长得那么高，像个大人了。", "target_word": "那么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别那么做，会伤到朋友的心。", "target_word": "那么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥那么爱看书，每天都去图书馆。", "target_word": "那么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天没有那么冷，今天冷多了。", "target_word": "那么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "像那样，指示样子或数量多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487a10cd-ac34-420d-b7b4-50a652b0befc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85873, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那么", "is_correct": true, "explanation": "正确：“那么”指示程度，与“那个”比较，构成“没有那个那么大”。"}, {"text": "多少", "is_correct": false, "explanation": "搭配：“多少”用于询问或不定的数量，不能用在“没有那个……大”这样的比较结构中。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样”用于询问方式或样子，与“没有那个……大”表示的程度比较不符。"}, {"text": "何等", "is_correct": false, "explanation": "语域：“何等”文言色彩浓，口语比较句中不用。"}], "explanations": {"那么": "正确：“那么”指示程度，与“那个”比较，构成“没有那个那么大”。", "多少": "搭配：“多少”用于询问或不定的数量，不能用在“没有那个……大”这样的比较结构中。", "怎样": "语义：“怎样”用于询问方式或样子，与“没有那个……大”表示的程度比较不符。", "何等": "语域：“何等”文言色彩浓，口语比较句中不用。"}, "sentence_index": 0, "correct_answer": "那么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她唱歌那么，大家都喜欢听。", "explanation": "这里不通。“那么”不能单独作谓语，后面要接形容词，应说“唱歌那么好听”。"}, {"text": "她唱歌比妈妈那么好听。", "explanation": "这里应该用〈更〉。比较句要用“更”，“那么”不能直接放在“比”字后。"}, {"text": "她唱歌那么的好听。", "explanation": "这里应该去掉〈的〉。“那么”后面不能直接加“的”修饰形容词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那么", "is_correct": true, "explanation": "正确：“那么”表示程度，修饰“高”，构成“长得那么高”。"}, {"text": "哪样", "is_correct": false, "explanation": "语义：“哪样”用于询问样子，与“长得……高”表示的程度不符。"}, {"text": "如何", "is_correct": false, "explanation": "语义：“如何”用于询问方式或情况，不能表示“高”的程度。"}, {"text": "都", "is_correct": false, "explanation": "语义：“都”表示全部或连同，不能直接修饰“高”来表示程度。"}], "explanations": {"那么": "正确：“那么”表示程度，修饰“高”，构成“长得那么高”。", "哪样": "语义：“哪样”用于询问样子，与“长得……高”表示的程度不符。", "如何": "语义：“如何”用于询问方式或情况，不能表示“高”的程度。", "都": "语义：“都”表示全部或连同，不能直接修饰“高”来表示程度。"}, "sentence_index": 6, "correct_answer": "那么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那么的书是我的。", "explanation": "这里不通。“那么”不能加“的”作定语，指代物品要说“那”。"}, {"text": "昨天那么的冷，今天冷多了。", "explanation": "这里应该去掉〈的〉。“那么”后面的形容词前不能加“的”，直接说“那么冷”。"}, {"text": "昨天没有冷那么，今天冷多了。", "explanation": "这里语序错误。“那么”要放在形容词前，应说〈没有那么冷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路很那么长，我们走了一下午。", "corrected_sentence": "这条路那么长，我们走了一下午。", "error_description": "“很”与“那么”都是程度修饰语，不能同时修饰“长”。应删去“很”，说“那么长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家院子里有那么花，很漂亮。", "corrected_sentence": "我家院子里有那么多花，很漂亮。", "error_description": "“那么”后面接名词时要带数量词“多”，应说“那么多花”，缺少“多”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50952014-d3cb-4f4e-9fae-e80435cce8b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
