INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85875, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电影是在大屏幕上看的会动的故事，有人物，也有声音。", "primary_collocate": null, "pronunciation": "diàn yǐng", "ipa": "tjɛn˥˩ iŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "昨天晚上我和朋友去看了一部电影。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的票多少钱一张？", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影八点开始，我们七点半在门口见面。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱在周末一个人在家看电影。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影很长，我看了三个小时。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的小狗特别可爱，孩子们都喜欢。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先吃饭，然后去看电影。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影结束后，大家慢慢走出来了。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天看的电影叫什么名字？", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，我不能在车上看电影。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "电影院", "label": "复合"}, {"form": "电影票", "label": "复合"}, {"form": "電影", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电影：在银幕上放映、供人观看的一部故事片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d8e7589-5b4b-4fd1-9e86-38e415da95b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电影", "is_correct": true, "explanation": "正确。“一部电影”指一部影片，与“去看”搭配，符合句意。"}, {"text": "饭", "is_correct": false, "explanation": "量词与语义：“部”不用于饭，“看”也不接“饭”，“看了一部饭”说不通。"}, {"text": "水", "is_correct": false, "explanation": "量词与语义：“部”不用于水，“看”的对象也不是水，“看了一部水”说不通。"}, {"text": "椅子", "is_correct": false, "explanation": "量词：“椅子”用“把”计量，不用“部”；语义：“看”的对象应是影视作品。"}], "explanations": {"电影": "正确。“一部电影”指一部影片，与“去看”搭配，符合句意。", "饭": "量词与语义：“部”不用于饭，“看”也不接“饭”，“看了一部饭”说不通。", "水": "量词与语义：“部”不用于水，“看”的对象也不是水，“看了一部水”说不通。", "椅子": "量词：“椅子”用“把”计量，不用“部”；语义：“看”的对象应是影视作品。"}, "sentence_index": 0, "correct_answer": "电影"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天吃了一顿电影。", "explanation": "这里应该用〈饭〉。“电影”是作品，不能被吃，“吃”的对象是食物。"}, {"text": "我的朋友是一部电影。", "explanation": "这里应该用〈医生〉。“电影”指作品，不能用来指人，不能把人说成电影。"}, {"text": "妈妈给我倒了一杯电影。", "explanation": "这里应该用〈水〉。“电影”不能倒进杯子里，“倒”的对象是液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电影", "is_correct": true, "explanation": "正确。“去看电影”是常见的搭配，符合“我们先吃饭，然后去看”的语境。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“看”的对象应是可以看到的事物，“去看声音”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道要靠品尝或闻，不能用“看”，“去看味道”不符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“看”不与“心情”搭配，表达心情通常用“感受”之类的词。"}], "explanations": {"电影": "正确。“去看电影”是常见的搭配，符合“我们先吃饭，然后去看”的语境。", "声音": "语义：“看”的对象应是可以看到的事物，“去看声音”说不通。", "味道": "语义：味道要靠品尝或闻，不能用“看”，“去看味道”不符合句意。", "心情": "搭配：“看”不与“心情”搭配，表达心情通常用“感受”之类的词。"}, "sentence_index": 6, "correct_answer": "电影"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙放在电影里。", "explanation": "这里应该用〈口袋〉。“电影”不是可以装东西的地方，不能把钥匙放进去。"}, {"text": "孩子们在公园里踢电影。", "explanation": "这里应该用〈足球〉。“踢”的对象是球，电影不能被踢。"}, {"text": "妈妈在厨房里炒电影。", "explanation": "这里应该用〈菜〉。“炒”的对象是食材，电影不能炒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天看了三张电影。", "corrected_sentence": "我们昨天看了三部电影。", "error_description": "“电影”的量词应为“部”，“张”用于纸张等扁平的东西，不能用于电影。错误：“三张电影”；正确：“三部电影”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天去看一张电影吧。", "corrected_sentence": "我们明天去看一部电影吧。", "error_description": "“电影”的量词应为“部”，“张”用于纸张等扁平的东西，不能用于电影。错误：“一张电影”；正确：“一部电影”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '104fa865-3ed1-4819-b0a5-f288bdbdd6e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
