INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85887, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“这么”是说像这样，用来说样子有多大、多高。", "primary_collocate": null, "pronunciation": "zhè me", "ipa": "ʈʂɤ˥˩ mɤ", "syllable_count": 2, "sentences": [{"text": "这棵树这么高，我爬不上去。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个西瓜这么大，我拿不动。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么这么高了？", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的雪这么大，别出门了。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河这么宽，我不敢游。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手这么小，只能拿一个。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间这么大，住五个人没问题。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山这么高，我们走了三个小时。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子才五岁，就这么高了。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路这么远，你开车去吧。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "这么些", "label": "复合"}, {"form": "这么点儿", "label": "复合"}, {"form": "這麼", "label": "繁体"}], "register": "口语", "sense_fingerprint": "这么：指示程度，如这么大、这么高、这么远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '217b17f7-3652-4b45-872e-2d935d63277c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85887, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这个", "is_correct": false, "explanation": "语法：“这个”后需接名词，“这棵树这个高”不成句。"}, {"text": "这么", "is_correct": true, "explanation": "正确：“这么高”表示程度，与“我爬不上去”相合。"}, {"text": "怎么", "is_correct": false, "explanation": "语义：“怎么高”是疑问，不能用于“这棵树……，我爬不上去”的陈述。"}, {"text": "这种", "is_correct": false, "explanation": "语法：“这种”后需接名词，“这棵树这种高”不成句。"}], "explanations": {"这个": "语法：“这个”后需接名词，“这棵树这个高”不成句。", "这么": "正确：“这么高”表示程度，与“我爬不上去”相合。", "怎么": "语义：“怎么高”是疑问，不能用于“这棵树……，我爬不上去”的陈述。", "这种": "语法：“这种”后需接名词，“这棵树这种高”不成句。"}, "sentence_index": 0, "correct_answer": "这么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这么天很冷，别出门了。", "explanation": "用法错误：“这么”不能直接修饰名词“天”，这里应说“这么冷的天”。"}, {"text": "这么雪很大，别出门了。", "explanation": "这里应该用“这场”。“这么”是指示性质、程度的代词，不能直接修饰名词“雪”。"}, {"text": "这么办法很好，我们用它吧。", "explanation": "用法错误：“这么”不能直接修饰名词“办法”，这里应说“这个办法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85887, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这一", "is_correct": false, "explanation": "语法：“这一”后需接量词和名词，“这个房间这一大”不成句。"}, {"text": "这么", "is_correct": true, "explanation": "正确：“这么大”表示程度，与“住五个人没问题”相合。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样大”是疑问，不能用于“这个房间……，住五个人没问题”的陈述。"}, {"text": "这份", "is_correct": false, "explanation": "语法：“这份”后需接名词，“这个房间这份大”不成句。"}], "explanations": {"这一": "语法：“这一”后需接量词和名词，“这个房间这一大”不成句。", "这么": "正确：“这么大”表示程度，与“住五个人没问题”相合。", "怎样": "语义：“怎样大”是疑问，不能用于“这个房间……，住五个人没问题”的陈述。", "这份": "语法：“这份”后需接名词，“这个房间这份大”不成句。"}, "sentence_index": 6, "correct_answer": "这么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么山很高，我们爬不上去。", "explanation": "用法错误：“这么”不能直接修饰名词“山”，这里应说“这座山”。"}, {"text": "这么河很宽，我不敢游。", "explanation": "用法错误：“这么”不能直接修饰名词“河”，这里应说“这条河”。"}, {"text": "这么房间很大，住五个人没问题。", "explanation": "用法错误：“这么”不能直接修饰名词“房间”，这里应说“这个房间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子这么很重，我搬不动。", "corrected_sentence": "这个箱子这么重，我搬不动。", "error_description": "重复程度：“这么”和“很”都表示程度，不能同时用；应删去“很”，说“这么重”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么远路，我们坐车去吧。", "corrected_sentence": "这么远的路，我们坐车去吧。", "error_description": "结构错误：“这么远”修饰名词“路”时要加“的”，应说“这么远的路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
