INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85888, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，指示方式、做法，如“这么说”“这么做”。", "primary_collocate": null, "pronunciation": "zhè me", "ipa": "ʈʂɤ˥˩ mɤ", "syllable_count": 2, "sentences": [{"text": "你为什么这么说？", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情就这么定了。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜要这么做才好吃。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别这么看着我。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不应该这么对朋友。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这么一说，我就明白了。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就这么办吧，我同意。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字不是这么写的。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这么跑，会很累的。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她这么想也有道理。", "target_word": "这么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "这么样", "label": "复合"}, {"form": "这么些", "label": "复合"}, {"form": "這麼", "label": "繁体"}], "register": "口语", "sense_fingerprint": "这么：指示方式、做法，如这么说、这么做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '217b17f7-3652-4b45-872e-2d935d63277c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怎样", "is_correct": false, "explanation": "搭配：“为什么”与“怎样”都是疑问词，同用时句子不通顺。"}, {"text": "这么", "is_correct": true, "explanation": "正确：“这么说”指像这样地说，与“为什么”相合。"}, {"text": "如何", "is_correct": false, "explanation": "搭配：“为什么”与“如何”重叠，“你为什么如何说”不成句。"}, {"text": "这一", "is_correct": false, "explanation": "语法：“这一”后需接量词和名词，“你为什么这一说”不成句。"}], "explanations": {"怎样": "搭配：“为什么”与“怎样”都是疑问词，同用时句子不通顺。", "这么": "正确：“这么说”指像这样地说，与“为什么”相合。", "如何": "搭配：“为什么”与“如何”重叠，“你为什么如何说”不成句。", "这一": "语法：“这一”后需接量词和名词，“你为什么这一说”不成句。"}, "sentence_index": 0, "correct_answer": "这么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了这么书。", "explanation": "用法错误：“这么”不能直接修饰名词，这里应说“这本书”。"}, {"text": "这么书包很重，别背了。", "explanation": "用法错误：“这么”不能直接修饰名词“书包”，这里应说“这个书包”。"}, {"text": "这么地方很好，我们常来。", "explanation": "用法错误：“这么”不能直接修饰名词“地方”，这里应说“这个地方”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这一", "is_correct": false, "explanation": "语法：“这一”后需接量词和名词，“就这一办吧”不成句。"}, {"text": "这么", "is_correct": true, "explanation": "正确：“就这么办”指照这个样子办，与“我同意”相合。"}, {"text": "哪样", "is_correct": false, "explanation": "搭配：“哪样”带有询问的意味，“就哪样办吧”与“我同意”不协调。"}, {"text": "这份", "is_correct": false, "explanation": "语法：“这份”后需接名词，“就这份办吧”不成句。"}], "explanations": {"这一": "语法：“这一”后需接量词和名词，“就这一办吧”不成句。", "这么": "正确：“就这么办”指照这个样子办，与“我同意”相合。", "哪样": "搭配：“哪样”带有询问的意味，“就哪样办吧”与“我同意”不协调。", "这份": "语法：“这份”后需接名词，“就这份办吧”不成句。"}, "sentence_index": 6, "correct_answer": "这么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么电影很好看，我们去看吧。", "explanation": "用法错误：“这么”不能直接修饰名词“电影”，这里应说“这部电影”。"}, {"text": "这么老师很好，我们都喜欢他。", "explanation": "用法错误：“这么”不能直接修饰名词“老师”，这里应说“这位老师”。"}, {"text": "这么办法很好，我们就用它吧。", "explanation": "用法错误：“这么”不能直接修饰名词“办法”，这里应说“这个办法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你这么了说话，大家都不喜欢。", "corrected_sentence": "你这么说话，大家都不喜欢。", "error_description": "多余成分：“了”不能紧跟在“这么”后面，应删去“了”，说“你这么说话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你就走这么吧。", "corrected_sentence": "你就这么走吧。", "error_description": "语序错误：“这么”是指示方式的状语，要放在动词前，不能放在动词后；应说“你就这么走吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
