INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85889, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天下是天空下面所有的地方，指全世界。", "primary_collocate": null, "pronunciation": "tiān xià", "ipa": "tʰjɛn˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "天下没有不散的宴席。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天下的人都知道他。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样的好人天下少有。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷说，天下的父母都爱孩子。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走遍天下，看过很多地方。", "target_word": "天下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天下这么大，我想去看看。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的画传遍天下，大家都知道。", "target_word": "天下", "complexity_tier": "T3", "furigana": "tā de huà chuán biàn tiān xià, dà jiā dōu zhī dào", "sentence_source": "generated"}, {"text": "他的朋友遍布天下。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天下的河最后都流向大海。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天下的孩子都爱玩。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "天空下面所有的地方，全世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8be57f03-7fb2-4413-ac65-d96db36736d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85889, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确答案。天下 tiān xià 指天空下面所有的地方，即全世界。"}, {"text": "天线", "is_correct": false, "explanation": "xiàn（第四声）与 xià（第四声）声调相同，但韵尾不同（多一个 n），意思是天线，不是天下。"}, {"text": "甜虾", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）、xiā（第一声）与 xià（第四声）声调不同，意思是甜虾，不是天下。"}, {"text": "添加", "is_correct": false, "explanation": "jiā（第一声）与 xià（第四声）声母不同（j 与 x），声调也不同，意思是添加，不是天下。"}, {"text": "天象", "is_correct": false, "explanation": "xiàng（第四声）与 xià（第四声）韵尾不同（多一个 ng），意思是天体现象，不是天下。"}], "explanations": {"天下": "正确答案。天下 tiān xià 指天空下面所有的地方，即全世界。", "天线": "xiàn（第四声）与 xià（第四声）声调相同，但韵尾不同（多一个 n），意思是天线，不是天下。", "甜虾": "tián（第二声）与 tiān（第一声）、xiā（第一声）与 xià（第四声）声调不同，意思是甜虾，不是天下。", "添加": "jiā（第一声）与 xià（第四声）声母不同（j 与 x），声调也不同，意思是添加，不是天下。", "天象": "xiàng（第四声）与 xià（第四声）韵尾不同（多一个 ng），意思是天体现象，不是天下。"}, "sentence_index": null, "correct_answer": "天下"}, "level_3": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确：天下指全世界，作主语，句意是“全世界都没有不散的宴席”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指冷热阴晴，不指所有地方，句子说的范围对不上。"}, {"text": "老天爷", "is_correct": false, "explanation": "语域：老天爷是口语化的神的称呼，与“天下”的中性说法不符，句子也说不通。"}, {"text": "酒桌", "is_correct": false, "explanation": "搭配：酒桌是放桌子的地方，不能作“宴席散不散”的范围主语，“酒桌没有宴席”说不通。"}], "explanations": {"天下": "正确：天下指全世界，作主语，句意是“全世界都没有不散的宴席”。", "天气": "语义：天气指冷热阴晴，不指所有地方，句子说的范围对不上。", "老天爷": "语域：老天爷是口语化的神的称呼，与“天下”的中性说法不符，句子也说不通。", "酒桌": "搭配：酒桌是放桌子的地方，不能作“宴席散不散”的范围主语，“酒桌没有宴席”说不通。"}, "sentence_index": 0, "correct_answer": "天下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窗外的天下很蓝，我们去散步吧。", "explanation": "这里应该用〈天空〉。天下指全世界，不指天空；说天空的颜色要用“天空”。"}, {"text": "今天的天下很好，我们出去玩吧。", "explanation": "这里应该用〈天气〉。天下指全世界，不指天气；说天气好要用“天气”。"}, {"text": "这个天下很甜。", "explanation": "这里应该用〈西瓜〉。“天下”指全世界，不指水果；“甜”的主语应是“西瓜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85889, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确答案。天下 tiān xià 指天空下面所有的地方，即全世界。"}, {"text": "天价", "is_correct": false, "explanation": "jià（第四声）与 xià（第四声）韵母相同，只是声母不同（j 与 x），意思是极高的价格，不是天下。"}, {"text": "天蝎", "is_correct": false, "explanation": "xiē（第一声）与 xià（第四声）声母相同，但韵母不同（e 与 a），声调也不同，意思是蝎子座，不是天下。"}, {"text": "天涯", "is_correct": false, "explanation": "yá（第二声）与 xià（第四声）韵母相同，声母不同（零声母与 x），声调也不同，意思是天边、远方，不是天下。"}], "explanations": {"天下": "正确答案。天下 tiān xià 指天空下面所有的地方，即全世界。", "天价": "jià（第四声）与 xià（第四声）韵母相同，只是声母不同（j 与 x），意思是极高的价格，不是天下。", "天蝎": "xiē（第一声）与 xià（第四声）声母相同，但韵母不同（e 与 a），声调也不同，意思是蝎子座，不是天下。", "天涯": "yá（第二声）与 xià（第四声）韵母相同，声母不同（零声母与 x），声调也不同，意思是天边、远方，不是天下。"}, "sentence_index": null, "correct_answer": "天下"}, "level_3": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确：天下指全世界，作“传遍”的宾语，句意是“画的名声传遍全世界”。"}, {"text": "画家", "is_correct": false, "explanation": "配价：“传遍”要求一个处所作宾语，“画家”是人，不能作“传遍”的范围。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是一件物品，不是可以让画作传遍的范围，句意说不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是一门学科，不是地点或范围，“传遍数学”没有意义。"}], "explanations": {"天下": "正确：天下指全世界，作“传遍”的宾语，句意是“画的名声传遍全世界”。", "画家": "配价：“传遍”要求一个处所作宾语，“画家”是人，不能作“传遍”的范围。", "手机": "语义：手机是一件物品，不是可以让画作传遍的范围，句意说不通。", "数学": "语义：数学是一门学科，不是地点或范围，“传遍数学”没有意义。"}, "sentence_index": 6, "correct_answer": "天下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些天下，他一直很忙。", "explanation": "这里应该用〈天〉。“天”可以表示一段时间，如“这些天”；“天下”指全世界，不能用来计算时间。"}, {"text": "他的天下受伤了，不能写字。", "explanation": "这里应该用〈手〉。“天下”指全世界，不指身体部位；受伤的应是“手”。"}, {"text": "天下在院子里跑来跑去。", "explanation": "这里应该用〈小狗〉。“天下”指全世界，不指动物；在院子里跑的应是“小狗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的歌传遍天下们，大家都会唱。", "corrected_sentence": "他的歌传遍天下，大家都会唱。", "error_description": "词缀错误：“天下”后不能加复数词尾“们”，应为“传遍天下”，“天下们”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天下得老师都很辛苦。", "corrected_sentence": "天下的老师都很辛苦。", "error_description": "结构助词错误：修饰名词要用“的”，“得”用于动词后作补语。这里应为“天下的老师”，写成“天下得老师”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家的政权，即统治国家的权力。", "primary_collocate": null, "pronunciation": "tiān xià", "ipa": "tʰjɛn˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "他们一起打天下，吃了很多苦。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个皇帝用十年得了天下。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天下是打出来的，不是等来的。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，人们都想得到天下。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想夺天下，可是没成功。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "秦始皇统一了天下。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天下大乱，百姓过不上好日子。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个时候的天下很不太平。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐了二十年天下，最后老了。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位将军帮皇帝守住了天下。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "国家的政权，统治的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8be57f03-7fb2-4413-ac65-d96db36736d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确答案。天下 tiān xià 指国家的政权，也指全世界。"}, {"text": "天线", "is_correct": false, "explanation": "xiàn（第四声）与 xià（第四声）声调相同，但韵尾不同（多一个 n），意思是天线，不是天下。"}, {"text": "甜虾", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）、xiā（第一声）与 xià（第四声）声调不同，意思是甜虾，不是天下。"}, {"text": "添加", "is_correct": false, "explanation": "jiā（第一声）与 xià（第四声）声母不同（j 与 x），声调也不同，意思是添加，不是天下。"}, {"text": "天象", "is_correct": false, "explanation": "xiàng（第四声）与 xià（第四声）韵尾不同（多一个 ng），意思是天体现象，不是天下。"}], "explanations": {"天下": "正确答案。天下 tiān xià 指国家的政权，也指全世界。", "天线": "xiàn（第四声）与 xià（第四声）声调相同，但韵尾不同（多一个 n），意思是天线，不是天下。", "甜虾": "tián（第二声）与 tiān（第一声）、xiā（第一声）与 xià（第四声）声调不同，意思是甜虾，不是天下。", "添加": "jiā（第一声）与 xià（第四声）声母不同（j 与 x），声调也不同，意思是添加，不是天下。", "天象": "xiàng（第四声）与 xià（第四声）韵尾不同（多一个 ng），意思是天体现象，不是天下。"}, "sentence_index": null, "correct_answer": "天下"}, "level_3": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确：天下指国家政权，“打天下”即争夺政权，与句意“一起奋斗吃苦”相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“打”不能与“天气”搭配，不说“打天气”。"}, {"text": "杂志", "is_correct": false, "explanation": "搭配：“打杂志”不成立，“打”后不接印刷品。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“打电话”是通话，与“吃了很多苦”的语境不合，句意说不通。"}], "explanations": {"天下": "正确：天下指国家政权，“打天下”即争夺政权，与句意“一起奋斗吃苦”相符。", "天气": "搭配：“打”不能与“天气”搭配，不说“打天气”。", "杂志": "搭配：“打杂志”不成立，“打”后不接印刷品。", "电话": "语义：“打电话”是通话，与“吃了很多苦”的语境不合，句意说不通。"}, "sentence_index": 0, "correct_answer": "天下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个天下很香。", "explanation": "这里应该用〈面包〉。“天下”指全世界或国家政权，不指食物；说香的应是“面包”。"}, {"text": "我天下有空。", "explanation": "这里应该用〈下午〉。“天下”指全世界或国家政权，不指时间；说有空的时间要用“下午”。"}, {"text": "他想去天下留学，开阔眼界。", "explanation": "这里应该用〈国外〉。留学要去具体的国家或地方，“天下”不能作留学的去处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确答案。天下 tiān xià 指国家的政权，也指全世界。"}, {"text": "天价", "is_correct": false, "explanation": "jià（第四声）与 xià（第四声）韵母相同，只是声母不同（j 与 x），意思是极高的价格，不是天下。"}, {"text": "天蝎", "is_correct": false, "explanation": "xiē（第一声）与 xià（第四声）声母相同，但韵母不同（e 与 a），声调也不同，意思是蝎子座，不是天下。"}, {"text": "天涯", "is_correct": false, "explanation": "yá（第二声）与 xià（第四声）韵母相同，声母不同（零声母与 x），声调也不同，意思是天边、远方，不是天下。"}], "explanations": {"天下": "正确答案。天下 tiān xià 指国家的政权，也指全世界。", "天价": "jià（第四声）与 xià（第四声）韵母相同，只是声母不同（j 与 x），意思是极高的价格，不是天下。", "天蝎": "xiē（第一声）与 xià（第四声）声母相同，但韵母不同（e 与 a），声调也不同，意思是蝎子座，不是天下。", "天涯": "yá（第二声）与 xià（第四声）韵母相同，声母不同（零声母与 x），声调也不同，意思是天边、远方，不是天下。"}, "sentence_index": null, "correct_answer": "天下"}, "level_3": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确：天下作主语，指国家局势，“天下大乱”即国家动荡。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不会“大乱”，句子说的是国家的局势。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“大乱”用于局势、社会，不能用于课本。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是季节，不能“大乱”，与“百姓过不上好日子”的语境不合。"}], "explanations": {"天下": "正确：天下作主语，指国家局势，“天下大乱”即国家动荡。", "河流": "语义：河流不会“大乱”，句子说的是国家的局势。", "课本": "搭配：“大乱”用于局势、社会，不能用于课本。", "夏天": "语义：夏天是季节，不能“大乱”，与“百姓过不上好日子”的语境不合。"}, "sentence_index": 6, "correct_answer": "天下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天下在屋顶上睡觉。", "explanation": "这里应该用〈小猫〉。“天下”指全世界或国家政权，不指动物；在屋顶上睡觉的应是“小猫”。"}, {"text": "天下开得很快。", "explanation": "这里应该用〈汽车〉。“天下”指全世界或国家政权，不是交通工具；开得快的应是“汽车”。"}, {"text": "天下很厚，我读不完。", "explanation": "这里应该用〈书〉。“天下”指全世界或国家政权，不是书籍；说厚的应是“书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于守了住天下，大家都很佩服。", "corrected_sentence": "他终于守住了天下，大家都很佩服。", "error_description": "补语位置错误：“守住”中的“住”是结果补语，应紧跟动词，“了”放在“守住”之后；写成“守了住”是错的，应为“守住了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时打了过天下，很有经验。", "corrected_sentence": "他年轻时打过天下，很有经验。", "error_description": "体标错误：“过”表示经历，动词后不能再加“了”，两个体标叠用是错的；应为“打过天下”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“只有”是说一定要有这个，事情才能做成。", "primary_collocate": null, "pronunciation": "zhǐ yǒu", "ipa": "ʈʂɻ̩˨˩ joʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "只有找到钥匙，门才能打开。", "target_word": "只有", "complexity_tier": "T3", "furigana": "zhǐ yǒu zhǎo dào yào shi, mén cái néng dǎ kāi.", "sentence_source": "generated"}, {"text": "只有用热水，茶才会好喝。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有你在，这个会才能开。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有买了票，我们才能进去。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有带着地图，我们才不会迷路。", "target_word": "只有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有加盐，这道菜才好吃。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有通电，灯才会亮。", "target_word": "只有", "complexity_tier": "T3", "furigana": "zhǐ yǒu tōng diàn, dēng cái huì liàng.", "sentence_source": "generated"}, {"text": "只有连上网，手机才能用。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有医生同意，他才能出院。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有排队，我们才能买到票。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "必须具备某个事物或人，事情才能成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '217b17f7-3652-4b45-872e-2d935d63277c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "只有", "is_correct": true, "explanation": "只有 zhǐ yǒu：表示一定要有某个条件，事情才能成。"}, {"text": "挚友", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，“挚友”指亲密的朋友，与“只有”声音不同。"}, {"text": "质优", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，yōu（第一声）与 yǒu（第三声）声调也不同，“质优”指质量好。"}, {"text": "至友", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，yǒu 相同；“至友”指最好的朋友，与“只有”只差声调。"}, {"text": "知友", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，yǒu 相同；“知友”指知心朋友，与“只有”只差声调。"}], "explanations": {"只有": "只有 zhǐ yǒu：表示一定要有某个条件，事情才能成。", "挚友": "zhì（第四声）与 zhǐ（第三声）声调不同，“挚友”指亲密的朋友，与“只有”声音不同。", "质优": "zhì（第四声）与 zhǐ（第三声）声调不同，yōu（第一声）与 yǒu（第三声）声调也不同，“质优”指质量好。", "至友": "zhì（第四声）与 zhǐ（第三声）声调不同，yǒu 相同；“至友”指最好的朋友，与“只有”只差声调。", "知友": "zhī（第一声）与 zhǐ（第三声）声调不同，yǒu 相同；“知友”指知心朋友，与“只有”只差声调。"}, "sentence_index": null, "correct_answer": "只有"}, "level_3": {"options": [{"text": "只有", "is_correct": true, "explanation": "“只有”表示一定要有这个条件，与后面的“才能”配合，句子成立。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”要与“都”或“也”配合，不能与“才能”配合。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，前后是事实，不表示必须具备的条件。"}, {"text": "即使", "is_correct": false, "explanation": "语义：“即使”表示让步，与“门才能打开”所表达的必要条件矛盾。"}], "explanations": {"只有": "“只有”表示一定要有这个条件，与后面的“才能”配合，句子成立。", "无论": "搭配：“无论”要与“都”或“也”配合，不能与“才能”配合。", "虽然": "语义：“虽然”表示让步，前后是事实，不表示必须具备的条件。", "即使": "语义：“即使”表示让步，与“门才能打开”所表达的必要条件矛盾。"}, "sentence_index": 0, "correct_answer": "只有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "只有他一个人排队，我们也都排了队。", "explanation": "这里的“只有”强调唯一，与“我们也都排了队”矛盾。表示“不止一人”应该用〈除了…还〉。"}, {"text": "只有他一个人没买票，别人也都没买。", "explanation": "这里的“只有”强调唯一，与“别人也都没买”矛盾。表示“不止一人”应该用〈不只〉。"}, {"text": "只有他一个人有钥匙，大家也都有。", "explanation": "这里的“只有”强调唯一，与“大家也都有”矛盾。表示“不止一人”应该用〈除了…还〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "只有", "is_correct": true, "explanation": "只有 zhǐ yǒu：表示一定要有某个条件，事情才能成。"}, {"text": "执友", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，yǒu 相同；“执友”指志同道合的朋友。"}, {"text": "诸友", "is_correct": false, "explanation": "zhū（第一声）与 zhǐ 声调不同且韵母不同，yǒu 相同；“诸友”指各位朋友。"}, {"text": "自由", "is_correct": false, "explanation": "zì 与 zhǐ 声母不同，声调也不同，yóu 与 yǒu 只差声调；“自由”指不受约束。"}], "explanations": {"只有": "只有 zhǐ yǒu：表示一定要有某个条件，事情才能成。", "执友": "zhí（第二声）与 zhǐ（第三声）声调不同，yǒu 相同；“执友”指志同道合的朋友。", "诸友": "zhū（第一声）与 zhǐ 声调不同且韵母不同，yǒu 相同；“诸友”指各位朋友。", "自由": "zì 与 zhǐ 声母不同，声调也不同，yóu 与 yǒu 只差声调；“自由”指不受约束。"}, "sentence_index": null, "correct_answer": "只有"}, "level_3": {"options": [{"text": "只有", "is_correct": true, "explanation": "“只有”表示一定要有这个条件，与后面的“才会”配合，句子成立。"}, {"text": "不但", "is_correct": false, "explanation": "配价：“不但”需要后面的“而且”或“也”来配合，句中没有这种配合。"}, {"text": "纵使", "is_correct": false, "explanation": "语域：“纵使”是书面语，与这句口语化的表达不协调。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，与“灯才会亮”所表达的必要条件矛盾。"}], "explanations": {"只有": "“只有”表示一定要有这个条件，与后面的“才会”配合，句子成立。", "不但": "配价：“不但”需要后面的“而且”或“也”来配合，句中没有这种配合。", "纵使": "语域：“纵使”是书面语，与这句口语化的表达不协调。", "尽管": "语义：“尽管”表示让步，与“灯才会亮”所表达的必要条件矛盾。"}, "sentence_index": 6, "correct_answer": "只有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "只有他一个人会修车，我们班的人几乎都会。", "explanation": "这里的“只有”强调唯一，与“我们班的人几乎都会”矛盾。表示“不止一人”应该用〈不止〉。"}, {"text": "只有我一个人去过那里，朋友们也都去过。", "explanation": "这里的“只有”强调唯一，与“朋友们也都去过”矛盾。表示“不止一人”应该用〈除了…还〉。"}, {"text": "只有他一个人答对了，还有很多人也答对了。", "explanation": "这里的“只有”强调唯一，与“还有很多人也答对了”矛盾。表示“不止一人”应该用〈不只〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "只有通过考试，你能拿到证书。", "corrected_sentence": "只有通过考试，你才能拿到证书。", "error_description": "“只有”表示必须具备的条件，要与“才能”配合；这里漏掉了“才”。应改为“你才能拿到证书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只有带好钥匙，我们也能进屋。", "corrected_sentence": "只有带好钥匙，我们才能进屋。", "error_description": "“只有”要与“才”配合，表示必须具备的条件；这里把“才”错用成“也”。应改为“我们才能进屋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
