INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85919, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "网上是指在电脑和手机连着的网络里。", "primary_collocate": null, "pronunciation": "wǎng shàng", "ipa": "waŋ˨˩˦ ʂaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "网上有很多好看的视频。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的消息不一定都是真的。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的朋友我从来没见过面。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事现在网上很多人在谈。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的东西有时候比商店里便宜。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上看到一个有意思的故事。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上说明天会下大雨。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌在网上很受欢迎。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的天气预报很准。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别什么都相信网上的话。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "網上", "label": "繁体"}], "register": "口语", "sense_fingerprint": "电脑和手机连着的网络里（网上有、网上的内容）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e787e97-1e72-4215-97db-ad41e99b5a31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85919, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "网上", "is_correct": true, "explanation": "网上：指电脑和手机连着的网络里，与题目读音相符。"}, {"text": "上网", "is_correct": false, "explanation": "上网（shàng wǎng）与 wǎng shàng 的声调顺序不同，意思是连接互联网，不是本题的词。"}, {"text": "晚上", "is_correct": false, "explanation": "晚上（wǎnshang）与 wǎng shàng 的韵母不同，wǎn 是 -n，wǎng 是 -ng，意思是夜里。"}, {"text": "网商", "is_correct": false, "explanation": "网商（wǎng shāng）与 wǎng shàng 第二个音节的声调不同，意思是在网上做生意的人。"}], "explanations": {"网上": "网上：指电脑和手机连着的网络里，与题目读音相符。", "上网": "上网（shàng wǎng）与 wǎng shàng 的声调顺序不同，意思是连接互联网，不是本题的词。", "晚上": "晚上（wǎnshang）与 wǎng shàng 的韵母不同，wǎn 是 -n，wǎng 是 -ng，意思是夜里。", "网商": "网商（wǎng shāng）与 wǎng shàng 第二个音节的声调不同，意思是在网上做生意的人。"}, "sentence_index": null, "correct_answer": "网上"}, "level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是放食物的家电，视频不会存放在冰箱里，句子说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，与好看的视频没有关系，句子说不通。"}, {"text": "网上", "is_correct": true, "explanation": "网上：指互联网里，好看的视频大多在网上，与句意相符。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“有很多好看的视频”需要能存放视频的地方，花园与“视频”不搭配。"}], "explanations": {"冰箱": "语义：冰箱是放食物的家电，视频不会存放在冰箱里，句子说不通。", "厨房": "语义：厨房是做饭的地方，与好看的视频没有关系，句子说不通。", "网上": "网上：指互联网里，好看的视频大多在网上，与句意相符。", "花园": "搭配：“有很多好看的视频”需要能存放视频的地方，花园与“视频”不搭配。"}, "sentence_index": 0, "correct_answer": "网上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天去网上吃了一顿饭。", "explanation": "这里应该用〈饭馆〉。“网上”指在网络里，吃饭不能在网上进行，要去饭馆。"}, {"text": "周末我们去网上散步吧。", "explanation": "这里应该用〈公园〉。“网上”指在网络里，不能去散步；散步的地方要用“公园”。"}, {"text": "妈妈在网上做饭。", "explanation": "这里应该用〈厨房〉。“网上”指在网络里，做饭要在厨房进行，不能在网上做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85919, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭桌", "is_correct": false, "explanation": "语义：饭桌不会说话，不能发布“明天会下大雨”的消息，句子说不通。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：停车场是停车的地方，不会发布天气消息，句子说不通。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "配价：“说”要求有说话能力的主语，垃圾桶不能作“说”的主语，搭配不成立。"}, {"text": "网上", "is_correct": true, "explanation": "网上：指互联网里，天气消息可以在网上发布，与句意相符。"}], "explanations": {"饭桌": "语义：饭桌不会说话，不能发布“明天会下大雨”的消息，句子说不通。", "停车场": "语义：停车场是停车的地方，不会发布天气消息，句子说不通。", "垃圾桶": "配价：“说”要求有说话能力的主语，垃圾桶不能作“说”的主语，搭配不成立。", "网上": "网上：指互联网里，天气消息可以在网上发布，与句意相符。"}, "sentence_index": 6, "correct_answer": "网上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去网上取钱。", "explanation": "这里应该用〈银行〉。“网上”指在网络里，取钱要去银行，不能去网上取钱。"}, {"text": "我在网上睡觉。", "explanation": "这里应该用〈床上〉。“网上”指在网络里，人不能在网络里睡觉。"}, {"text": "他每天在网上洗澡。", "explanation": "这里应该用〈浴室〉。“网上”指在网络里，洗澡要在浴室进行，不能在网上洗澡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85919, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事在在网上传得很快。", "corrected_sentence": "这件事在网上传得很快。", "error_description": "错误：「在在网上」，介词「在」重复，多出一个「在」。正确：只保留一个「在」，即「在网上传得很快」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85919, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个视频到网上很火。", "corrected_sentence": "这个视频在网上很火。", "error_description": "介词误用：表示“在某个范围内”要用介词“在”，不用“到”。应说“在网上很火”，不说“到网上很火”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
