INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85928, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词，用于句末，表示仅此而已，有往小里说的语气。", "primary_collocate": null, "pronunciation": "ér yǐ", "ipa": "ɚ˧˥ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "你别当真，他只是说说而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不算什么，小事而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我就是想看看而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只是同事而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不过是个新手而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有恶意，只是想帮你而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服不贵，几十块钱而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我就喝了一小口而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不必道歉，只是迟到五分钟而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他什么也没说，只是笑了笑而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "而已：句末助词，把事情往小里说，语气轻描淡写", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53fc934-9efd-4505-9f2d-9389e6da67ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而已", "is_correct": true, "explanation": "“而已”表示“仅此而已”，与“别当真”的淡化语气相合。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问，前句是“你别当真”的劝告，改成疑问后语义不通。"}, {"text": "的", "is_correct": false, "explanation": "搭配：句末“的”需与“是”构成“是……的”格式，“只是说说的”单用不成句。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示感叹，与“别当真”的淡化语气不合。"}], "explanations": {"而已": "“而已”表示“仅此而已”，与“别当真”的淡化语气相合。", "吗": "语义：“吗”表示疑问，前句是“你别当真”的劝告，改成疑问后语义不通。", "的": "搭配：句末“的”需与“是”构成“是……的”格式，“只是说说的”单用不成句。", "哇": "语义：“哇”表示感叹，与“别当真”的淡化语气不合。"}, "sentence_index": 0, "correct_answer": "而已"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛对我来说是人生最大的挑战而已。", "explanation": "这里“而已”表示“仅此而已、往小里说”，与“人生最大的挑战”的强调语气相矛盾；表示强调应用〈非常〉之类的程度词。"}, {"text": "他为这个项目付出了三年心血，这只是一件小事而已。", "explanation": "“付出三年心血”说明投入很大，用“而已”往小里说，前后语气矛盾；这里应表示强调，不能用“而已”。"}, {"text": "我们成功拿下了这笔百亿订单，只是一桩普通生意而已。", "explanation": "“而已”表示轻描淡写，用来形容“百亿订单”的成功，语义矛盾；这里应表示强调，用〈非常〉之类的程度词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而已", "is_correct": true, "explanation": "“而已”表示“仅此而已”，与“不贵”呼应，说明价钱并不多。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问，把“几十块钱”这一陈述变成询问，与句意不合。"}, {"text": "哦", "is_correct": false, "explanation": "语义：“哦”表示醒悟或应答，不能表达“仅此而已”的轻描淡写。"}, {"text": "哪", "is_correct": false, "explanation": "语域：“哪”是口语或方言用法，书面语中不这样用，且此处语气不通。"}], "explanations": {"而已": "“而已”表示“仅此而已”，与“不贵”呼应，说明价钱并不多。", "吗": "语义：“吗”表示疑问，把“几十块钱”这一陈述变成询问，与句意不合。", "哦": "语义：“哦”表示醒悟或应答，不能表达“仅此而已”的轻描淡写。", "哪": "语域：“哪”是口语或方言用法，书面语中不这样用，且此处语气不通。"}, "sentence_index": 6, "correct_answer": "而已"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次的新产品改变了整个行业，只是一次小小的改进而已。", "explanation": "“改变整个行业”是很强的强调，“而已”却表示轻描淡写，语义矛盾；这里应用〈非常〉之类的程度词。"}, {"text": "这次地震造成了上万人伤亡，只是一次普通的自然灾害而已。", "explanation": "“而已”用于往小里说，与“造成上万人伤亡”的严重程度相矛盾；这里不能用“而已”。"}, {"text": "这位医生救活了无数病人，只是一份普通的工作而已。", "explanation": "“救活了无数病人”是很大的成绩，“而已”把它说成普通工作，语义矛盾；这里应表示强调，用〈非常〉之类的程度词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只是个小问题而已了。", "corrected_sentence": "这只是个小问题而已。", "error_description": "“而已”是句末助词，后面不能再加“了”。“这只是个小问题而已了”是错误的，应为“这只是个小问题而已”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只个小意思而已。", "corrected_sentence": "这只是个小意思而已。", "error_description": "“只是……而已”格式中漏掉了“是”。“这只个小意思”不成句，应为“这只是个小意思而已”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最前", "is_correct": true, "explanation": "正确：“最前”指排在最前面，与“最后”在位置上构成反义。"}, {"text": "中间", "is_correct": false, "explanation": "不是反义：“中间”指居中的位置，与“最后”没有对立关系。"}, {"text": "中央", "is_correct": false, "explanation": "不是反义：“中央”指正中的位置，不与“最后”对立。"}, {"text": "旁边", "is_correct": false, "explanation": "不是反义：“旁边”指靠近的一侧，与“最后”没有对立关系。"}], "correct_answer": "最前", "explanations": {"最前": "正确：“最前”指排在最前面，与“最后”在位置上构成反义。", "中间": "不是反义：“中间”指居中的位置，与“最后”没有对立关系。", "中央": "不是反义：“中央”指正中的位置，不与“最后”对立。", "旁边": "不是反义：“旁边”指靠近的一侧，与“最后”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最前", "is_correct": true, "explanation": "正确：“最前”指排在最前面，与“最后”在位置上构成反义。"}, {"text": "中部", "is_correct": false, "explanation": "不是反义：“中部”指中间的部分，与“最后”没有对立关系。"}, {"text": "当中", "is_correct": false, "explanation": "不是反义：“当中”指中间位置，与“最后”不构成对立。"}, {"text": "途中", "is_correct": false, "explanation": "不是反义：“途中”指行进的过程中，与“最后”没有对立关系。"}], "correct_answer": "最前", "explanations": {"最前": "正确：“最前”指排在最前面，与“最后”在位置上构成反义。", "中部": "不是反义：“中部”指中间的部分，与“最后”没有对立关系。", "当中": "不是反义：“当中”指中间位置，与“最后”不构成对立。", "途中": "不是反义：“途中”指行进的过程中，与“最后”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“最后”是排在所有的后面，那一个就是最后。", "primary_collocate": null, "pronunciation": "zuì hòu", "ipa": "tsweɪ˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他排在队伍的最后。", "target_word": "最后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我坐在教室的最后一排。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明跑在最后，一直很慢。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "名单的最后是我的名字。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题放在试卷最后。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走在大家的最后。", "target_word": "最后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你排到队伍最后去。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "最后一个人把门关上了。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "名单上，我的名字在最后。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他考试得了最后一名。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "排列顺序中位于所有之后的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '217b17f7-3652-4b45-872e-2d935d63277c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最后", "is_correct": true, "explanation": "正确：“排在队伍的最后”指排在队尾，“最后”表示位置在末尾。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以排队的位置，“排在队伍的冰箱”句子不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“窗户”不能与“排在队伍的”搭配来表示位置。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店是场所，不能指队伍中的位置，句子不通。"}], "explanations": {"最后": "正确：“排在队伍的最后”指排在队尾，“最后”表示位置在末尾。", "冰箱": "语义：冰箱不是可以排队的位置，“排在队伍的冰箱”句子不成立。", "窗户": "搭配：“窗户”不能与“排在队伍的”搭配来表示位置。", "饭店": "语义：饭店是场所，不能指队伍中的位置，句子不通。"}, "sentence_index": 0, "correct_answer": "最后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最后站在队伍里的人，是排在第一位的我。", "explanation": "这里应该用〈首位〉。“最后”指排在末尾，与“排在第一位”相矛盾；指排在最前的位置要用〈首位〉。"}, {"text": "我站在队伍的最后，前面没有人。", "explanation": "这里应该用〈最前〉。“最后”指排在末尾，与“前面没有人”相矛盾；排在队伍第一位要用“最前”。"}, {"text": "名单的最后是我的名字，名单的最后却是他的名字。", "explanation": "这里应该用〈开头〉。两个“最后”同时指名单末尾，自相矛盾；指名单开头的位置要用“开头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最后", "is_correct": true, "explanation": "正确：“排到队伍最后去”指排到队尾。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是可以排队的位置，句子无法表示队伍中的位置。"}, {"text": "讲台", "is_correct": false, "explanation": "搭配：“讲台”是固定的站立位置，“排到队伍讲台去”不搭配。"}, {"text": "饭桌", "is_correct": false, "explanation": "语义：饭桌是吃饭用的家具，不是排队的位置，句子不通。"}], "explanations": {"最后": "正确：“排到队伍最后去”指排到队尾。", "书包": "语义：书包不是可以排队的位置，句子无法表示队伍中的位置。", "讲台": "搭配：“讲台”是固定的站立位置，“排到队伍讲台去”不搭配。", "饭桌": "语义：饭桌是吃饭用的家具，不是排队的位置，句子不通。"}, "sentence_index": 6, "correct_answer": "最后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他考试得了最后一名，全班都羡慕他的好成绩。", "explanation": "这里应该用〈第一名〉。“最后一名”指排在末尾，与“羡慕好成绩”相矛盾；表示名次靠前要用“第一名”。"}, {"text": "他是队伍的最后，走在大家前面。", "explanation": "这里应该用〈领头〉。“最后”指排在末尾，与“走在大家前面”相矛盾；表示排在最前、带头的人要用“领头”。"}, {"text": "他站在名单的最后，却排在第一位。", "explanation": "这里应该用〈首位〉。“最后”指名单末尾，与“排在第一位”相矛盾；表示排在名单首位要用“首位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他住在楼的最后得一层。", "corrected_sentence": "他住在楼的最后一层。", "error_description": "错误形式：“最后得一层”；正确形式：“最后一层”。“得”是补语标记，不能插在定语“最后”和数量短语“一层”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跑在大家的了最后。", "corrected_sentence": "他跑在大家的最后。", "error_description": "错误形式：“的了最后”；正确形式：“的最后”。“了”不能插在定语“的”和“最后”之间，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最初", "is_correct": true, "explanation": "正确：“最初”指开始的时候，与“最后”在时间顺序上构成反义。"}, {"text": "中间", "is_correct": false, "explanation": "不是反义：“中间”指位置居中，与“最后”没有对立关系。"}, {"text": "过程", "is_correct": false, "explanation": "不是反义：“过程”指事情发展的经过，与“最后”不构成对立。"}, {"text": "中途", "is_correct": false, "explanation": "不是反义：“中途”指事情进行中的中间阶段，与“最后”没有对立关系。"}], "correct_answer": "最初", "explanations": {"最初": "正确：“最初”指开始的时候，与“最后”在时间顺序上构成反义。", "中间": "不是反义：“中间”指位置居中，与“最后”没有对立关系。", "过程": "不是反义：“过程”指事情发展的经过，与“最后”不构成对立。", "中途": "不是反义：“中途”指事情进行中的中间阶段，与“最后”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
