INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指次序或时间上在末尾的部分；也作形容词表示最末的。", "primary_collocate": null, "pronunciation": "zuì hòu", "ipa": "tsweɪ˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "音乐会的最后五分钟很精彩。", "target_word": "最后", "complexity_tier": "T3", "furigana": "yīn yuè huì de zuì hòu wǔ fēn zhōng hěn jīng cǎi", "sentence_source": "generated"}, {"text": "这本书的最后很感人。", "target_word": "最后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次考试我是班里的最后一名。", "target_word": "最后", "complexity_tier": "T3", "furigana": "zhè cì kǎo shì wǒ shì bān lǐ de zuì hòu yì míng", "sentence_source": "generated"}, {"text": "比赛最后，我们赢了。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的最后一天，我去看奶奶。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影的最后，他回家了。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的最后一句话是再见。", "target_word": "最后", "complexity_tier": "T3", "furigana": "tā de zuì hòu yí jù huà shì zài jiàn", "sentence_source": "generated"}, {"text": "一年的最后，大家都很忙。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我最后一次来这里。", "target_word": "最后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是最后一个问题。", "target_word": "最后", "complexity_tier": "T3", "furigana": "zhè shì zuì hòu yí ge wèn tí", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "次序或时间上的末尾部分；最末的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '217b17f7-3652-4b45-872e-2d935d63277c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最后", "is_correct": true, "explanation": "正确：“最后五分钟”指演出结束前的五分钟，“最后”修饰时段，表示末尾。"}, {"text": "最远", "is_correct": false, "explanation": "语义：“最远”说的是空间距离，不能修饰“五分钟”这样的时长。"}, {"text": "最贵", "is_correct": false, "explanation": "搭配：“最贵”说的是价格，不能用来修饰时间段。"}, {"text": "最高", "is_correct": false, "explanation": "语义：“最高”说的是高度或程度，不能修饰时长，句子不通。"}], "explanations": {"最后": "正确：“最后五分钟”指演出结束前的五分钟，“最后”修饰时段，表示末尾。", "最远": "语义：“最远”说的是空间距离，不能修饰“五分钟”这样的时长。", "最贵": "搭配：“最贵”说的是价格，不能用来修饰时间段。", "最高": "语义：“最高”说的是高度或程度，不能修饰时长，句子不通。"}, "sentence_index": 0, "correct_answer": "最后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最后才到了，比所有人都早。", "explanation": "这里应该用〈最早〉。“最后”指末尾，与“比所有人都早”相矛盾；先于所有人要用〈最早〉。"}, {"text": "这个计划最后很简单，后来很难做。", "explanation": "这里应该用〈起初〉。“最后”指末尾，与“后来”的先后顺序矛盾；说开始的时候要用“起初”。"}, {"text": "我们最后关灯，然后关门。", "explanation": "这里应该用〈首先〉。“最后”指末尾，与“然后”的顺序矛盾；表示第一步要用“首先”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最后", "is_correct": true, "explanation": "正确：“最后一句话”指末了的一句话，即“再见”那句。"}, {"text": "最热", "is_correct": false, "explanation": "搭配：“最热”说的是温度，不能修饰“一句话”。"}, {"text": "最凉", "is_correct": false, "explanation": "语义：“最凉”说的是温度，与“话”不相关，句子不成立。"}, {"text": "最低", "is_correct": false, "explanation": "语义：“最低”说的是高低程度，不能用来修饰一句话。"}], "explanations": {"最后": "正确：“最后一句话”指末了的一句话，即“再见”那句。", "最热": "搭配：“最热”说的是温度，不能修饰“一句话”。", "最凉": "语义：“最凉”说的是温度，与“话”不相关，句子不成立。", "最低": "语义：“最低”说的是高低程度，不能用来修饰一句话。"}, "sentence_index": 6, "correct_answer": "最后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最后很努力，后来放弃了。", "explanation": "这里应该用〈最初〉。“最后”指末尾，与“后来放弃了”的先后不符；表示开始时要用“最初”。"}, {"text": "我们最后的时候人很少，后来越来越多。", "explanation": "这里应该用〈开始〉。“最后”表示末尾，与“后来越来越多”的先后顺序矛盾；讲开始的情形要用“开始”。"}, {"text": "最后这里没有路，现在有了一条大路。", "explanation": "这里应该用〈先前〉。“最后”指末尾，与“现在”的时间先后矛盾；表示过去的情形要用“先前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛的最后得三分钟很激烈。", "corrected_sentence": "比赛的最后三分钟很激烈。", "error_description": "错误形式：“最后得三分钟”；正确形式：“最后三分钟”。“得”是补语标记，不能插在定语“最后”和数量词“三分钟”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说了最后了一句话。", "corrected_sentence": "他说了最后一句话。", "error_description": "错误形式：“他说了最后了一句话”；正确形式：“他说了最后一句话”。“最后”与数量短语“一句话”之间不能插入“了”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a615d745-f2e7-456d-81b2-42ff20c741dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注销", "is_correct": true, "explanation": "反义：注销指取消已经登记的信息或资格，与“注册”相反。"}, {"text": "购买", "is_correct": false, "explanation": "无反义关系：购买是付钱取得物品，与登记信息无关。"}, {"text": "跑步", "is_correct": false, "explanation": "无反义关系：跑步是一种运动，不涉及登记或取消登记。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：唱歌是表演，不是登记或取消登记。"}], "correct_answer": "注销", "explanations": {"注销": "反义：注销指取消已经登记的信息或资格，与“注册”相反。", "购买": "无反义关系：购买是付钱取得物品，与登记信息无关。", "跑步": "无反义关系：跑步是一种运动，不涉及登记或取消登记。", "唱歌": "无反义关系：唱歌是表演，不是登记或取消登记。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注销", "is_correct": true, "explanation": "反义：注销指取消已经登记的信息或资格，与“注册”相反。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：游泳是一种运动，与登记信息无关。"}, {"text": "吃饭", "is_correct": false, "explanation": "无反义关系：吃饭是进食，与登记或取消登记无关。"}, {"text": "画画", "is_correct": false, "explanation": "无反义关系：画画是创作活动，不涉及登记。"}], "correct_answer": "注销", "explanations": {"注销": "反义：注销指取消已经登记的信息或资格，与“注册”相反。", "游泳": "无反义关系：游泳是一种运动，与登记信息无关。", "吃饭": "无反义关系：吃饭是进食，与登记或取消登记无关。", "画画": "无反义关系：画画是创作活动，不涉及登记。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "注册是把你的名字写到一个本子或网站上，这样你就能用它。", "primary_collocate": null, "pronunciation": "zhù cè", "ipa": "tʂu˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "你先注册，然后就能玩游戏了。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想注册一个新的微信号。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在手机上注册了这个软件。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注册很快，只要一分钟。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站注册不用花钱。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经注册了吗？", "target_word": "注册", "complexity_tier": "T3", "furigana": "nǐ yǐ jīng zhù cè le ma", "sentence_source": "generated"}, {"text": "孩子们在网上注册了账号。", "target_word": "注册", "complexity_tier": "T3", "furigana": "hái zi men zài wǎng shàng zhù cè le zhàng hào", "sentence_source": "generated"}, {"text": "我忘了密码，只好重新注册。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注册以后，你可以每天看书。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮奶奶注册了一个账号。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注册了", "label": "体标"}, {"form": "注册过", "label": "体标"}, {"form": "重新注册", "label": "复合"}], "register": "中性", "sense_fingerprint": "把名字写到网站或本子上以便使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8be57f03-7fb2-4413-ac65-d96db36736d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注册", "is_correct": true, "explanation": "正确：注册指登记账号，完成后才能玩游戏，句意相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不能让人玩游戏，“先生病，然后就能玩游戏”说不通。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧与玩游戏没有先后关系，句子说不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译与玩游戏之间没有先后的前提关系，“先翻译，然后就能玩游戏”说不通。"}], "explanations": {"注册": "正确：注册指登记账号，完成后才能玩游戏，句意相符。", "生病": "语义：生病不能让人玩游戏，“先生病，然后就能玩游戏”说不通。", "发烧": "语义：发烧与玩游戏没有先后关系，句子说不通。", "翻译": "语义：翻译与玩游戏之间没有先后的前提关系，“先翻译，然后就能玩游戏”说不通。"}, "sentence_index": 0, "correct_answer": "注册"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们提前注册了餐厅。", "explanation": "这里应该用〈预约〉。预订餐厅要用“预约”；“注册”指登记姓名、信息等，不用于订位。"}, {"text": "他注册了一份工作。", "explanation": "这里应该用〈申请〉。应聘工作要用“申请”；“注册”不用于求职。"}, {"text": "他帮爷爷注册了一瓶酱油。", "explanation": "这里应该用〈买〉。买酱油要用“买”；“注册”指登记姓名、信息，不用于买东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注册", "is_correct": true, "explanation": "正确：注册指在网上登记账号，这里表示孩子们登记了账号。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于账号，“吃了账号”说不通。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”不能与“账号”搭配，句子说不通。"}, {"text": "撒", "is_correct": false, "explanation": "搭配：“撒”不能用于账号，“撒了账号”不成立。"}], "explanations": {"注册": "正确：注册指在网上登记账号，这里表示孩子们登记了账号。", "吃": "语义：“吃”不能用于账号，“吃了账号”说不通。", "跑": "语义：“跑”不能与“账号”搭配，句子说不通。", "撒": "搭配：“撒”不能用于账号，“撒了账号”不成立。"}, "sentence_index": 6, "correct_answer": "注册"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他帮奶奶注册了一场雨。", "explanation": "注册的对象是账号、公司、商标等，不能指雨。这里应该用〈下〉。"}, {"text": "我想注册一顿晚饭。", "explanation": "注册的对象是账号、公司、商标等，不能指饭食。这里应该用〈吃〉。"}, {"text": "她注册了一片蓝天。", "explanation": "注册的对象是账号、公司、商标等，不能指天空。这里应该用〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我换了手机，只好重新注册着。", "corrected_sentence": "我换了手机，只好重新注册。", "error_description": "体标错误：“注册”是一次完成的动作，不能加“着”表示状态持续；应为“只好重新注册”，去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在手机上注册得账号很安全。", "corrected_sentence": "他在手机上注册的账号很安全。", "error_description": "结构助词错误：修饰“账号”要用“的”，“得”用于动词后作补语。这里应为“注册的账号”，写成“注册得账号”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注销", "is_correct": true, "explanation": "反义：注销指取消已经登记的信息或资格，与“注册”相反。"}, {"text": "购买", "is_correct": false, "explanation": "无反义关系：购买是付钱取得物品，与登记信息无关。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：散步是一种活动，不涉及登记或取消登记。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：唱歌是表演，不是登记或取消登记。"}], "correct_answer": "注销", "explanations": {"注销": "反义：注销指取消已经登记的信息或资格，与“注册”相反。", "购买": "无反义关系：购买是付钱取得物品，与登记信息无关。", "散步": "无反义关系：散步是一种活动，不涉及登记或取消登记。", "唱歌": "无反义关系：唱歌是表演，不是登记或取消登记。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注销", "is_correct": true, "explanation": "反义：注销指取消已经登记的信息或资格，与“注册”相反。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：游泳是一种运动，与登记信息无关。"}, {"text": "吃饭", "is_correct": false, "explanation": "无反义关系：吃饭是进食，与登记或取消登记无关。"}, {"text": "画画", "is_correct": false, "explanation": "无反义关系：画画是创作活动，不涉及登记。"}], "correct_answer": "注销", "explanations": {"注销": "反义：注销指取消已经登记的信息或资格，与“注册”相反。", "游泳": "无反义关系：游泳是一种运动，与登记信息无关。", "吃饭": "无反义关系：吃饭是进食，与登记或取消登记无关。", "画画": "无反义关系：画画是创作活动，不涉及登记。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向有关机构或网站登记姓名等信息，以取得资格或使用权。", "primary_collocate": null, "pronunciation": "zhù cè", "ipa": "tʂu˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "你要先在网站上注册，才能买票。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天注册了一个新邮箱。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司去年在北京注册。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想注册一家小公司。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新生要在九月一号前注册。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用手机号注册账号。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你注册过这个网站吗？", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注册的时候，要写真实的姓名。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不注册，就不能看这个视频。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的网上注册今天开始了。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注册了", "label": "体标"}, {"form": "注册过", "label": "体标"}, {"form": "注册商标", "label": "复合"}, {"form": "注册会计师", "label": "复合"}], "register": "中性", "sense_fingerprint": "向机构或网站登记个人信息以取得资格或使用权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8be57f03-7fb2-4413-ac65-d96db36736d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注册", "is_correct": true, "explanation": "正确：注册指在网站上登记信息以取得资格，这里表示先完成登记才能买票。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”不能与“网站上”搭配，“在网站上散步”说不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”不能用于网站的操作，“在网站上唱歌”不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与买票的前提无关，“先睡觉才能买票”说不通。"}], "explanations": {"注册": "正确：注册指在网站上登记信息以取得资格，这里表示先完成登记才能买票。", "散步": "搭配：“散步”不能与“网站上”搭配，“在网站上散步”说不通。", "唱歌": "搭配：“唱歌”不能用于网站的操作，“在网站上唱歌”不成立。", "睡觉": "语义：睡觉与买票的前提无关，“先睡觉才能买票”说不通。"}, "sentence_index": 0, "correct_answer": "注册"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去银行注册了一笔贷款。", "explanation": "这里应该用〈申请〉。贷款要用“申请”；“注册”指登记信息以取得资格，不用于借钱。"}, {"text": "她注册了一张电影票。", "explanation": "这里应该用〈买〉。买电影票要用“买”；“注册”指登记姓名、信息，不用于买票。"}, {"text": "我们去超市注册了一些水果。", "explanation": "这里应该用〈挑选〉。挑水果要用“挑选”；“注册”指登记信息，不用于挑选商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注册", "is_correct": true, "explanation": "正确：“注册过”指曾在该网站登记过账号，句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与网站无关，“吃过这个网站”说不通。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”不能用于网站，“骑过这个网站”不成立。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指移动，与登记账号无关，句意不通。"}], "explanations": {"注册": "正确：“注册过”指曾在该网站登记过账号，句意相符。", "吃": "语义：“吃”与网站无关，“吃过这个网站”说不通。", "骑": "搭配：“骑”不能用于网站，“骑过这个网站”不成立。", "跑": "语义：“跑”指移动，与登记账号无关，句意不通。"}, "sentence_index": 6, "correct_answer": "注册"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天注册了一位新朋友。", "explanation": "注册的对象是账号、公司、商标等，不能指人。结识新朋友要用〈认识〉。"}, {"text": "她每天都注册一次早饭。", "explanation": "注册的对象是账号、公司、商标等，不能指饭食。吃早饭要用〈吃〉。"}, {"text": "我们注册了这座山的美景。", "explanation": "注册的对象是账号、公司、商标等，不能指风景。欣赏美景要用〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经注册了了这个软件。", "corrected_sentence": "我已经注册了这个软件。", "error_description": "体标重复：“注册了”之后不能再加“了”，同一个“了”只用一次；应为“我已经注册了这个软件”，去掉多余的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他注册了过这个网站，所以很熟悉。", "corrected_sentence": "他注册过这个网站，所以很熟悉。", "error_description": "体标叠用：“注册”后的“了”与“过”不能同时使用，只保留“过”，应为“他注册过这个网站”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
