INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85939, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "议员是大家选出来，在会议上替大家说话的人。", "primary_collocate": null, "pronunciation": "yì yuán", "ipa": "i˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "议员在会议上说出了大家的想法。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位议员常常去听市民的意见。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民选他当议员。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员们正在讨论新的法律。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们城市最年轻的议员。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员要替选民说话。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位议员昨天参加了会议。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有两百多名议员。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员听完市民的问题，马上回答了。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔做过十年议员。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "国会议员", "label": "复合词"}, {"form": "議員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由选举产生、在议会中代表民众发言的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e787e97-1e72-4215-97db-ad41e99b5a31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85939, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员（yì yuán）：经选举进入议会、替大家发言和议事的人。"}, {"text": "一元", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，“一元”是货币单位，意思不同。"}, {"text": "医院", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，yuàn（第四声）与 yuán（第二声）也不同，意思是医院。"}, {"text": "意愿", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，意思是愿望。"}, {"text": "议院", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，“议院”指议会机构，意思不同。"}], "explanations": {"议员": "议员（yì yuán）：经选举进入议会、替大家发言和议事的人。", "一元": "yī（第一声）与 yì（第四声）声调不同，“一元”是货币单位，意思不同。", "医院": "yī（第一声）与 yì（第四声）声调不同，yuàn（第四声）与 yuán（第二声）也不同，意思是医院。", "意愿": "yuàn（第四声）与 yuán（第二声）声调不同，意思是愿望。", "议院": "yuàn（第四声）与 yuán（第二声）声调不同，“议院”指议会机构，意思不同。"}, "sentence_index": null, "correct_answer": "议员"}, "level_3": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员：经选举产生、在会议上替大家说话的人，与句意相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不是代表大家在会议上发言的人，与“说出了大家的想法”不符。"}, {"text": "桌子", "is_correct": false, "explanation": "体貌：桌子是无生命的家具，不能在会议上说话。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不会说话，无法说出大家的想法。"}], "explanations": {"议员": "议员：经选举产生、在会议上替大家说话的人，与句意相符。", "厨师": "语义：厨师不是代表大家在会议上发言的人，与“说出了大家的想法”不符。", "桌子": "体貌：桌子是无生命的家具，不能在会议上说话。", "鱼": "语义：鱼不会说话，无法说出大家的想法。"}, "sentence_index": 0, "correct_answer": "议员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位议员每天在医院给病人做手术。", "explanation": "这里应该用〈医生〉。做手术是医生的工作，议员的职责是立法和议事。"}, {"text": "我认识一只议员，他经常在电视上讲话。", "explanation": "这里量词用错了。议员是人，应该用〈位〉或〈名〉，不能用〈只〉。"}, {"text": "这位议员每天骑车给大家送快递。", "explanation": "这里应该用〈快递员〉。送快递是快递员的工作，议员的职责是立法和议事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85939, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员（yì yuán）：经选举进入议会、参与议事的人。"}, {"text": "一员", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，“一员”指一个成员，意思不同。"}, {"text": "遗愿", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是临终前的愿望。"}, {"text": "医员", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，“医员”指医生，意思不同。"}], "explanations": {"议员": "议员（yì yuán）：经选举进入议会、参与议事的人。", "一员": "yī（第一声）与 yì（第四声）声调不同，“一员”指一个成员，意思不同。", "遗愿": "yí（第二声）与 yì（第四声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是临终前的愿望。", "医员": "yī（第一声）与 yì（第四声）声调不同，“医员”指医生，意思不同。"}, "sentence_index": null, "correct_answer": "议员"}, "level_3": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员：经选举产生的议会成员，与“参加了会议”相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿还不能参加会议，也不能替大家说话。"}, {"text": "鬼", "is_correct": false, "explanation": "搭配：“那位”后接的是能参加会议的人，“鬼”不能与“参加会议”搭配。"}, {"text": "神仙", "is_correct": false, "explanation": "语义：神仙属于神话人物，在现实的会议语境中不能参加会议。"}], "explanations": {"议员": "议员：经选举产生的议会成员，与“参加了会议”相符。", "婴儿": "语义：婴儿还不能参加会议，也不能替大家说话。", "鬼": "搭配：“那位”后接的是能参加会议的人，“鬼”不能与“参加会议”搭配。", "神仙": "语义：神仙属于神话人物，在现实的会议语境中不能参加会议。"}, "sentence_index": 6, "correct_answer": "议员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大会开始时，议员负责给大家检票。", "explanation": "这里应该用〈检票员〉。检票是检票员的工作，议员的职责是立法和议事。"}, {"text": "这位议员每天在饭店炒菜。", "explanation": "这里应该用〈厨师〉。在饭店炒菜是厨师的工作，议员的职责是立法和议事。"}, {"text": "这位议员每天带领球队训练。", "explanation": "这里应该用〈教练〉。带领球队训练是教练的工作，与议员的职责无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是市里的一只议员，经常参加会议。", "corrected_sentence": "他是市里的一位议员，经常参加会议。", "error_description": "错误：一只议员；正确：一位议员。议员指人，量词应用“位”或“名”，“只”多用于动物或某些物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他母亲做过三只议员，很有经验。", "corrected_sentence": "他母亲做过三届议员，很有经验。", "error_description": "错误：三只议员；正确：三届议员。“届”用于任期，“只”用于动物或某些物品，不能用于议员。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
