INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "议会的成员，由选举产生，参与议事和立法。", "primary_collocate": null, "pronunciation": "yì yuán", "ipa": "i˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这位议员明天要去市政厅开会。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员们正在讨论新的交通法。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了十年议员，很了解老百姓的生活。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民给议员写了一封信，希望多建公园。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员们投票决定了明年的预算。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位议员是去年选出来的。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问议员对新法律有什么看法。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想成为议员，为城市做更多事。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员应该多听听大家的意见。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天有三位议员来我们学校参观。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "国会议员", "label": "复合"}, {"form": "議員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "议会中由选举产生、参与议事和立法的成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e787e97-1e72-4215-97db-ad41e99b5a31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85940, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员（yì yuán）：议会的成员，由选举产生，参与议事和立法。"}, {"text": "一元", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，“一元”是货币单位，意思不同。"}, {"text": "医院", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，yuàn（第四声）与 yuán（第二声）也不同，意思是医院。"}, {"text": "意愿", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，意思是愿望。"}, {"text": "议院", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，“议院”指议会机构，意思不同。"}], "explanations": {"议员": "议员（yì yuán）：议会的成员，由选举产生，参与议事和立法。", "一元": "yī（第一声）与 yì（第四声）声调不同，“一元”是货币单位，意思不同。", "医院": "yī（第一声）与 yì（第四声）声调不同，yuàn（第四声）与 yuán（第二声）也不同，意思是医院。", "意愿": "yuàn（第四声）与 yuán（第二声）声调不同，意思是愿望。", "议院": "yuàn（第四声）与 yuán（第二声）声调不同，“议院”指议会机构，意思不同。"}, "sentence_index": null, "correct_answer": "议员"}, "level_3": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员：议会的成员，与“明天要去市政厅开会”相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不能去市政厅开会。"}, {"text": "鬼", "is_correct": false, "explanation": "搭配：“这位”指人，“鬼”不能与“去市政厅开会”搭配。"}, {"text": "神仙", "is_correct": false, "explanation": "语义：神仙不属于会议的参与者，不能去市政厅开会。"}], "explanations": {"议员": "议员：议会的成员，与“明天要去市政厅开会”相符。", "婴儿": "语义：婴儿不能去市政厅开会。", "鬼": "搭配：“这位”指人，“鬼”不能与“去市政厅开会”搭配。", "神仙": "语义：神仙不属于会议的参与者，不能去市政厅开会。"}, "sentence_index": 0, "correct_answer": "议员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位议员在比赛中吹哨判罚犯规。", "explanation": "这里应该用〈裁判〉。吹哨判罚犯规是裁判的工作，议员的职责是立法和议事。"}, {"text": "我昨天在会上见到了两只议员。", "explanation": "这里量词用错了。议员是人，应该用〈位〉或〈名〉，不能用〈只〉。"}, {"text": "这位议员负责管理学校的食堂。", "explanation": "这里应该用〈后勤主任〉。管理学校食堂属于后勤工作，议员负责立法和议事，不负责学校的具体事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85940, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员（yì yuán）：议会的成员，由选举产生，参与议事和立法。"}, {"text": "一员", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，“一员”指一个成员，意思不同。"}, {"text": "遗愿", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是临终前的愿望。"}, {"text": "医员", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，“医员”指医生，意思不同。"}], "explanations": {"议员": "议员（yì yuán）：议会的成员，由选举产生，参与议事和立法。", "一员": "yī（第一声）与 yì（第四声）声调不同，“一员”指一个成员，意思不同。", "遗愿": "yí（第二声）与 yì（第四声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是临终前的愿望。", "医员": "yī（第一声）与 yì（第四声）声调不同，“医员”指医生，意思不同。"}, "sentence_index": null, "correct_answer": "议员"}, "level_3": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员：议会的成员，与“记者问……对新法律有什么看法”相符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不能回答记者的问题，也没有对法律的看法。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有发言能力，形体上也不能回答问题。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子无法对新法律表示看法。"}], "explanations": {"议员": "议员：议会的成员，与“记者问……对新法律有什么看法”相符。", "植物": "语义：植物不能回答记者的问题，也没有对法律的看法。", "石头": "体貌：石头没有发言能力，形体上也不能回答问题。", "桌子": "语义：桌子无法对新法律表示看法。"}, "sentence_index": 6, "correct_answer": "议员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位议员每天给客人理发。", "explanation": "这里应该用〈理发师〉。给客人理发是理发师的工作，议员的职责是立法和议事。"}, {"text": "议员在法庭上宣读了判决。", "explanation": "这里应该用〈法官〉。宣读判决是法官的职责，议员不参与审判。"}, {"text": "这位议员每天在工地上砌墙。", "explanation": "这里应该用〈泥瓦匠〉。砌墙是泥瓦匠的工作，议员的职责是立法和议事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他父亲二十年前就当上了一只议员。", "corrected_sentence": "他父亲二十年前就当上了一位议员。", "error_description": "错误：一只议员；正确：一位议员。议员指人，量词应用“位”或“名”，“只”多用于动物或某些物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只议员在任期内提出了很多建议。", "corrected_sentence": "这位议员在任期内提出了很多建议。", "error_description": "错误：这只议员；正确：这位议员。议员指人，指示量词应用“位”，“只”多用于动物或某些物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一旦是说如果有一天忽然发生了。", "primary_collocate": null, "pronunciation": "yí dàn", "ipa": "i˧˥ tan˥˩", "syllable_count": 2, "sentences": [{"text": "一旦发生火灾，大家要马上离开。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一旦丢了，很多事情都会很麻烦。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦生病，工作就要停下来。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车一旦坏了，我们就走不了了。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦比赛开始，谁也不能进来。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦忘了密码，就打不开门了。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦出现危险，你就大声叫我。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水一旦流出来，地板就湿了。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一旦生气，谁的话也不听。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦错过这班车，我们就要等一个小时。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一旦：假设意外情况忽然发生，强调后果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53fc934-9efd-4505-9f2d-9389e6da67ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一旦", "is_correct": true, "explanation": "正确：一旦（yí dàn）表示假设意外情况忽然发生，强调后果。"}, {"text": "一带", "is_correct": false, "explanation": "dài 与 dàn 韵尾不同（-ai 与 -an），意思是这一带。"}, {"text": "一半", "is_correct": false, "explanation": "bàn 与 dàn 声母不同（b 与 d），意思是一半。"}, {"text": "一探", "is_correct": false, "explanation": "tàn 与 dàn 声母不同（t 与 d），意思是探一下。"}], "explanations": {"一旦": "正确：一旦（yí dàn）表示假设意外情况忽然发生，强调后果。", "一带": "dài 与 dàn 韵尾不同（-ai 与 -an），意思是这一带。", "一半": "bàn 与 dàn 声母不同（b 与 d），意思是一半。", "一探": "tàn 与 dàn 声母不同（t 与 d），意思是探一下。"}, "sentence_index": null, "correct_answer": "一旦"}, "level_3": {"options": [{"text": "一旦", "is_correct": true, "explanation": "正确：一旦发生火灾，就立即离开，表示假设意外忽然发生。"}, {"text": "务必", "is_correct": false, "explanation": "语域：“务必”是书面语，多用于叮嘱，不能修饰“发生火灾”这种意外。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示催促，不能修饰“发生火灾”这种不由人控制的事件。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与“大家要马上离开”的要求相矛盾。"}], "explanations": {"一旦": "正确：一旦发生火灾，就立即离开，表示假设意外忽然发生。", "务必": "语域：“务必”是书面语，多用于叮嘱，不能修饰“发生火灾”这种意外。", "赶紧": "语义：“赶紧”表示催促，不能修饰“发生火灾”这种不由人控制的事件。", "不必": "语义：“不必”表示没有必要，与“大家要马上离开”的要求相矛盾。"}, "sentence_index": 0, "correct_answer": "一旦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一旦慢慢好起来了。", "explanation": "这里应该用〈慢慢〉。一旦强调突然发生，不能与表示逐步变化的“慢慢”搭配，应说“慢慢好起来了”。"}, {"text": "他十点一旦起床。", "explanation": "这里应该用〈才〉。一旦表示意外情况突然发生，不能表示“十点才”这样的时间限定，应说“十点才起床”。"}, {"text": "我一旦就去。", "explanation": "这里应该用〈马上〉。一旦需要带出条件和结果，不能单独与“就”搭配表示立即，应说“我马上就去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一旦", "is_correct": true, "explanation": "正确：一旦（yí dàn）表示假设意外情况忽然发生，强调后果。"}, {"text": "一档", "is_correct": false, "explanation": "dàng 与 dàn 韵尾不同（-ang 与 -an），意思是一档节目。"}, {"text": "一站", "is_correct": false, "explanation": "zhàn 与 dàn 声母不同（zh 与 d），意思是一个站点。"}, {"text": "一担", "is_correct": false, "explanation": "dān（第一声）与 dàn（第四声）声调不同，意思是一挑（的量）。"}, {"text": "一段", "is_correct": false, "explanation": "duàn 比 dàn 多了 u，意思是一段（路程或时间）。"}], "explanations": {"一旦": "正确：一旦（yí dàn）表示假设意外情况忽然发生，强调后果。", "一档": "dàng 与 dàn 韵尾不同（-ang 与 -an），意思是一档节目。", "一站": "zhàn 与 dàn 声母不同（zh 与 d），意思是一个站点。", "一担": "dān（第一声）与 dàn（第四声）声调不同，意思是一挑（的量）。", "一段": "duàn 比 dàn 多了 u，意思是一段（路程或时间）。"}, "sentence_index": null, "correct_answer": "一旦"}, "level_3": {"options": [{"text": "一旦", "is_correct": true, "explanation": "正确：一旦出现危险，就大声叫，表示假设意外忽然发生，与语境相合。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”表示无奈地去做某事，不能修饰“出现危险”这种事件。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必然的要求，不能说“必须出现危险”，与语境不合。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”用于叮嘱，不能修饰“出现危险”，句意不通。"}], "explanations": {"一旦": "正确：一旦出现危险，就大声叫，表示假设意外忽然发生，与语境相合。", "只好": "搭配：“只好”表示无奈地去做某事，不能修饰“出现危险”这种事件。", "必须": "语义：“必须”表示必然的要求，不能说“必须出现危险”，与语境不合。", "千万": "语义：“千万”用于叮嘱，不能修饰“出现危险”，句意不通。"}, "sentence_index": 6, "correct_answer": "一旦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一旦他很努力，但是没有考上。", "explanation": "这里应该用〈虽然〉。一旦表示条件出现后随之发生，不表示让步，与“但是”搭配不通，应说“虽然他很努力，但是没有考上”。"}, {"text": "一旦天黑了，他还是坚持跑完了全程。", "explanation": "这里应该用〈尽管〉。一旦不表示让步，与“还是”搭配不通，应说“尽管天黑了，他还是坚持跑完了全程”。"}, {"text": "一旦下大雨，他都会去上学。", "explanation": "这里应该用〈不管〉。一旦不能表示无论何种情况都成立，应说“不管下大雨，他都会去上学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一旦停电，屋里就一旦很暗。", "corrected_sentence": "一旦停电，屋里就很暗。", "error_description": "重复误用：“一旦”只引出条件分句，不能再修饰“很暗”这一结果分句；多余的“一旦”应删去。正确应为：一旦停电，屋里就很暗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一旦错过车，我们才得等。", "corrected_sentence": "一旦错过车，我们就得等。", "error_description": "搭配错误：“一旦……就……”是固定搭配，表示一出现某情况就有某结果，“才”不能替代“就”。正确应为：一旦错过车，我们就得等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
