INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85943, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从来是说从以前到现在，一直都是这样。", "primary_collocate": null, "pronunciation": "cóng lái", "ipa": "tsʰʊŋ˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我家从来都是爸爸做饭。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路从来都很安静。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来都是第一个到学校。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来都很爱笑。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天从来都很冷。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班从来都是这样上课的。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从来都把家里打扫得很干净。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小店从来都很忙。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来都是这么说的。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从来都对我们很好。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从过去到现在一直如此（肯定说法，常用从来都）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8be57f03-7fb2-4413-ac65-d96db36736d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85943, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从来", "is_correct": true, "explanation": "正确：“从来都是”表示从过去到现在一直如此，与“都是”搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“都是”一贯如此的意思相反。"}, {"text": "再三", "is_correct": false, "explanation": "搭配：“再三”多修饰反复进行的动作（如劝告），不能修饰“都是”这类判断。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“一直都是爸爸做饭”的持续状态冲突。"}], "explanations": {"从来": "正确：“从来都是”表示从过去到现在一直如此，与“都是”搭配。", "偶尔": "语义：“偶尔”表示不常发生，与“都是”一贯如此的意思相反。", "再三": "搭配：“再三”多修饰反复进行的动作（如劝告），不能修饰“都是”这类判断。", "突然": "语义：“突然”表示事情忽然发生，与“一直都是爸爸做饭”的持续状态冲突。"}, "sentence_index": 0, "correct_answer": "从来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天我从来在忙。", "explanation": "这里应该用〈一直〉。从来说的是从过去到现在的一贯情况，不用来描述“这几天”这样的短时间状态。"}, {"text": "我从来在北京住过三年。", "explanation": "这里应该用〈曾经〉。从来强调一贯如此，不能与“住过三年”这种有限的经历搭配。"}, {"text": "天从来黑了。", "explanation": "这里应该用〈忽然〉。从来表示一贯的状况，不能用来描述突然发生的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从来", "is_correct": true, "explanation": "正确：“从来都把家里打扫得很干净”表示一贯如此，与“都”搭配。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指时间刚过去不久，不能表示从过去到现在一直如此。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然出现的变化，与“一直干净”的持续状态冲突。"}, {"text": "再也", "is_correct": false, "explanation": "搭配：“再也”要与否定词连用，不能用于“都把……”这样的肯定句。"}], "explanations": {"从来": "正确：“从来都把家里打扫得很干净”表示一贯如此，与“都”搭配。", "刚刚": "语义：“刚刚”指时间刚过去不久，不能表示从过去到现在一直如此。", "忽然": "语义：“忽然”表示突然出现的变化，与“一直干净”的持续状态冲突。", "再也": "搭配：“再也”要与否定词连用，不能用于“都把……”这样的肯定句。"}, "sentence_index": 6, "correct_answer": "从来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从来搬家了。", "explanation": "这里应该用〈已经〉。从来表示一贯的状况，不用来说明某个动作已经完成。"}, {"text": "他从来刚吃完饭。", "explanation": "这里应该用〈刚〉。从来表示一贯如此，不能与“刚吃完”这种刚发生的动作搭配。"}, {"text": "我从来学会了游泳。", "explanation": "这里应该用〈刚刚〉。从来表示一贯如此，不能用于刚刚发生的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从来没都很准时。", "corrected_sentence": "她从来都很准时。", "error_description": "否定词误用：“从来都”是肯定说法，表示一贯如此，中间不能插入“没”；应为“她从来都很准时”，去掉“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从来没都是最后一个离开办公室。", "corrected_sentence": "她从来都是最后一个离开办公室。", "error_description": "肯定的“从来都是”里不能插入否定词“没”，应删去“没”，说“从来都是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
