INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85953, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“问”是把自己不知道的事说出来，请别人告诉你。", "primary_collocate": null, "pronunciation": "wèn", "ipa": "wən˥˩", "syllable_count": 1, "sentences": [{"text": "我想问你一件事。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生问老师：“这个字怎么读？”", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不懂就问，这是好习惯。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问我明天有没有时间。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈问我晚饭想吃什么。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问过大家喜欢什么运动。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去问他，他一定知道。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子总爱问为什么。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问她哪里不舒服。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有问我，我也没有说。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "问了", "label": "体标"}, {"form": "问过", "label": "体标"}, {"form": "问问", "label": "重叠"}, {"form": "問", "label": "繁体"}], "register": "中性", "sense_fingerprint": "向人提出不知道的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe9379e-d00e-43eb-9305-1708c35ab005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85953, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "文", "is_correct": false, "explanation": "wén（第二声）与 wèn（第四声）声调不同，意思是文字、文章。"}, {"text": "问", "is_correct": true, "explanation": "正确答案：问（wèn），把自己不知道的事说出来，请别人告诉你。"}, {"text": "万", "is_correct": false, "explanation": "wàn（第四声）与 wèn 韵母不同（an 与 en），意思是一万。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn（第三声）与 wèn 韵母和声调都不同，意思是晚上。"}], "explanations": {"文": "wén（第二声）与 wèn（第四声）声调不同，意思是文字、文章。", "问": "正确答案：问（wèn），把自己不知道的事说出来，请别人告诉你。", "万": "wàn（第四声）与 wèn 韵母不同（an 与 en），意思是一万。", "晚": "wǎn（第三声）与 wèn 韵母和声调都不同，意思是晚上。"}, "sentence_index": null, "correct_answer": "问"}, "level_3": {"options": [{"text": "问", "is_correct": true, "explanation": "正确：问，请对方回答自己不知道的事，与“你”搭配，表示提问。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语应是商品，不能说“买一件事”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，“吃你一件事”不成立。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”的宾语是礼物，“送你一件事”与句意不符。"}], "explanations": {"问": "正确：问，请对方回答自己不知道的事，与“你”搭配，表示提问。", "买": "搭配：“买”的宾语应是商品，不能说“买一件事”。", "吃": "搭配：“吃”的宾语应是食物，“吃你一件事”不成立。", "送": "语义：“送”的宾语是礼物，“送你一件事”与句意不符。"}, "sentence_index": 0, "correct_answer": "问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈问我一个好消息。", "explanation": "这里应该用〈告诉〉。问是请人回答自己不知道的事，传递消息要用“告诉”。"}, {"text": "老师问了我一本词典。", "explanation": "这里应该用〈送〉。“问”不能带“一本词典”这类物品作宾语，给人东西要用“送”。"}, {"text": "他问了一幅画。", "explanation": "这里应该用〈画〉。“问”的对象是问题或要了解的事，不能说“问一幅画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85953, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "温", "is_correct": false, "explanation": "wēn（第一声）与 wèn（第四声）声调不同，意思是温暖。"}, {"text": "问", "is_correct": true, "explanation": "正确答案：问（wèn），把自己不知道的事说出来，请别人告诉你。"}, {"text": "稳", "is_correct": false, "explanation": "wěn（第三声）与 wèn（第四声）声调不同，意思是稳定。"}, {"text": "闻", "is_correct": false, "explanation": "wén（第二声）与 wèn（第四声）声调不同，意思是听见、闻到。"}], "explanations": {"温": "wēn（第一声）与 wèn（第四声）声调不同，意思是温暖。", "问": "正确答案：问（wèn），把自己不知道的事说出来，请别人告诉你。", "稳": "wěn（第三声）与 wèn（第四声）声调不同，意思是稳定。", "闻": "wén（第二声）与 wèn（第四声）声调不同，意思是听见、闻到。"}, "sentence_index": null, "correct_answer": "问"}, "level_3": {"options": [{"text": "问", "is_correct": true, "explanation": "正确：问，请他回答，与“他一定知道”的语境相呼应。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是物品或身体，不能带“他”表示请教。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理物品，与“他一定知道”的语义不相容。"}, {"text": "擦", "is_correct": false, "explanation": "配价：“擦”要求擦拭的对象是物体，“擦他”不成立。"}], "explanations": {"问": "正确：问，请他回答，与“他一定知道”的语境相呼应。", "洗": "搭配：“洗”的宾语是物品或身体，不能带“他”表示请教。", "修": "语义：“修”指修理物品，与“他一定知道”的语义不相容。", "擦": "配价：“擦”要求擦拭的对象是物体，“擦他”不成立。"}, "sentence_index": 6, "correct_answer": "问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他问了一首歌。", "explanation": "这里应该用〈唱〉。“问”表示请人回答，不能用来指唱歌。"}, {"text": "她每天都问日记。", "explanation": "这里应该用〈写〉。“问”不能带“日记”作宾语，写日记要用“写”。"}, {"text": "他在台上问了一场戏。", "explanation": "这里应该用〈演〉。“问”不能用于表演，演一场戏要用“演”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想问很清楚这件事的原因。", "corrected_sentence": "我想问清楚这件事的原因。", "error_description": "补语错误：结果补语“清楚”前不能加程度副词“很”，应说“问清楚”，不能说“问很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我问过过老师这个问题。", "corrected_sentence": "我问过老师这个问题。", "error_description": "体标错误：动词后只能带一个“过”，应说“问过老师”，不能重复说“问过过老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
