INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85954, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，请别人回答自己不明白的事；也指询问、探究。", "primary_collocate": null, "pronunciation": "wèn", "ipa": "wən˥˩", "syllable_count": 1, "sentences": [{"text": "他停下车，问一位老人怎么走。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问一下，这件衣服多少钱？", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走进店里问价钱。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你问清楚，明天几点开会。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去问一下，火车站怎么走。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打电话问了医院的开门时间。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到处问，才找到那家书店。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问清楚了事情的原因。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在问自己为什么要这样做。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问过售货员，这里没有卖。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "问了", "label": "体标"}, {"form": "问过", "label": "体标"}, {"form": "问问", "label": "重叠"}, {"form": "問", "label": "繁体"}], "register": "中性", "sense_fingerprint": "询问打听、探究", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe9379e-d00e-43eb-9305-1708c35ab005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85954, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "文", "is_correct": false, "explanation": "wén（第二声）与 wèn（第四声）声调不同，意思是文字、文章。"}, {"text": "问", "is_correct": true, "explanation": "正确答案：问（wèn），询问打听，探究不明白的事。"}, {"text": "万", "is_correct": false, "explanation": "wàn（第四声）与 wèn 韵母不同（an 与 en），意思是一万。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn（第三声）与 wèn 韵母和声调都不同，意思是晚上。"}], "explanations": {"文": "wén（第二声）与 wèn（第四声）声调不同，意思是文字、文章。", "问": "正确答案：问（wèn），询问打听，探究不明白的事。", "万": "wàn（第四声）与 wèn 韵母不同（an 与 en），意思是一万。", "晚": "wǎn（第三声）与 wèn 韵母和声调都不同，意思是晚上。"}, "sentence_index": null, "correct_answer": "问"}, "level_3": {"options": [{"text": "问", "is_correct": true, "explanation": "正确：问，向人打听，这里是“问路”，即向老人询问怎么走。"}, {"text": "扶", "is_correct": false, "explanation": "语义：“扶”是搀扶，与“问路”的意思不符。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“摸”不能带“一位老人怎么走”这样的内容，搭配不当。"}, {"text": "推", "is_correct": false, "explanation": "配价：“推”的宾语是人或物，不能接“怎么走”作内容。"}], "explanations": {"问": "正确：问，向人打听，这里是“问路”，即向老人询问怎么走。", "扶": "语义：“扶”是搀扶，与“问路”的意思不符。", "摸": "搭配：“摸”不能带“一位老人怎么走”这样的内容，搭配不当。", "推": "配价：“推”的宾语是人或物，不能接“怎么走”作内容。"}, "sentence_index": 0, "correct_answer": "问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他蹲在路边问了一只小猫。", "explanation": "这里应该用〈逗〉。问是请人回答或探究事情，不能用来指逗猫。"}, {"text": "工人问了这台机器。", "explanation": "这里应该用〈修〉。“问”指询问或探究事情，不能用于机器，修机器要用“修”。"}, {"text": "护士问了那支针。", "explanation": "这里应该用〈打〉。“问”不能用于针剂，给人打针要用“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85954, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "温", "is_correct": false, "explanation": "wēn（第一声）与 wèn（第四声）声调不同，意思是温暖。"}, {"text": "问", "is_correct": true, "explanation": "正确答案：问（wèn），询问打听，探究不明白的事。"}, {"text": "稳", "is_correct": false, "explanation": "wěn（第三声）与 wèn（第四声）声调不同，意思是稳定。"}, {"text": "闻", "is_correct": false, "explanation": "wén（第二声）与 wèn（第四声）声调不同，意思是听见、闻到。"}], "explanations": {"温": "wēn（第一声）与 wèn（第四声）声调不同，意思是温暖。", "问": "正确答案：问（wèn），询问打听，探究不明白的事。", "稳": "wěn（第三声）与 wèn（第四声）声调不同，意思是稳定。", "闻": "wén（第二声）与 wèn（第四声）声调不同，意思是听见、闻到。"}, "sentence_index": null, "correct_answer": "问"}, "level_3": {"options": [{"text": "问", "is_correct": true, "explanation": "正确：问，向人打听，这里是“到处问”，即四处打听。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不表示寻找的方式，“到处吃”与“找到书店”无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与寻找的方式不相容，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“到处洗”不能表示寻找，与“找到书店”搭配不当。"}], "explanations": {"问": "正确：问，向人打听，这里是“到处问”，即四处打听。", "吃": "语义：“吃”不表示寻找的方式，“到处吃”与“找到书店”无关。", "唱": "语义：“唱”与寻找的方式不相容，句意不通。", "洗": "搭配：“到处洗”不能表示寻找，与“找到书店”搭配不当。"}, "sentence_index": 6, "correct_answer": "问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他随手问了那扇门。", "explanation": "这里应该用〈关〉。“问”不能用于门这样的物体，关门要用“关”。"}, {"text": "公司问了那辆货车。", "explanation": "这里应该用〈开〉。“问”不能用于车辆，开货车要用“开”。"}, {"text": "医生问了那把手术刀。", "explanation": "这里应该用〈消毒〉。“问”不能用于器械，给手术刀消毒要用“消毒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想把他问一个问题。", "corrected_sentence": "我想问他一个问题。", "error_description": "把字句误用：“问”带双宾语时不用“把”，应说“问他一个问题”，不能说“把他问一个问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我问他了三次，他都没回答。", "corrected_sentence": "我问了他三次，他都没回答。", "error_description": "动态助词“了”位置错误：“了”须紧跟动词，应说“问了他三次”，不能说“问他了三次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黑", "is_correct": true, "explanation": "“黑”与“白”相对，同为颜色词，是反义词。"}, {"text": "绿", "is_correct": false, "explanation": "“绿”也是颜色，但与“白”不构成反义关系。"}, {"text": "快", "is_correct": false, "explanation": "“快”说速度，与“白”没有反义关系。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”说味道，与“白”没有反义关系。"}], "correct_answer": "黑", "explanations": {"黑": "“黑”与“白”相对，同为颜色词，是反义词。", "绿": "“绿”也是颜色，但与“白”不构成反义关系。", "快": "“快”说速度，与“白”没有反义关系。", "甜": "“甜”说味道，与“白”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黑", "is_correct": true, "explanation": "“黑”与“白”相对，同为颜色词，是反义词。"}, {"text": "大", "is_correct": false, "explanation": "“大”说大小，与“白”没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "“高”说高低，与“白”没有反义关系。"}, {"text": "长", "is_correct": false, "explanation": "“长”说长短，与“白”没有反义关系。"}], "correct_answer": "黑", "explanations": {"黑": "“黑”与“白”相对，同为颜色词，是反义词。", "大": "“大”说大小，与“白”没有反义关系。", "高": "“高”说高低，与“白”没有反义关系。", "长": "“长”说长短，与“白”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "白是像雪和牛奶那样的颜色。", "primary_collocate": null, "pronunciation": "bái", "ipa": "pai˧˥", "syllable_count": 1, "sentences": [{"text": "天上的云很白。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭是白的，酱油是黑的。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，脸色白得很难看。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一件白的，不要红的。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花是白的，那朵是黄的。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的毛又白又软。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪下得很大，外面都白了。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的牙齿很白。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的头发已经白了。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白的比黑的更容易脏。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "白：像雪和牛奶那样的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53fc934-9efd-4505-9f2d-9389e6da67ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "白", "is_correct": true, "explanation": "白 bái（第二声）是像雪和牛奶那样的颜色。"}, {"text": "百", "is_correct": false, "explanation": "百 bǎi（第三声）与 bái（第二声）声调不同，意思是一百。"}, {"text": "败", "is_correct": false, "explanation": "败 bài（第四声）与 bái（第二声）声调不同，意思是失败。"}, {"text": "排", "is_correct": false, "explanation": "排 pái 与 bái 声母不同（b 与 p），意思是排列。"}, {"text": "摆", "is_correct": false, "explanation": "摆 bǎi（第三声）与 bái（第二声）声调不同，意思是摆放。"}], "explanations": {"白": "白 bái（第二声）是像雪和牛奶那样的颜色。", "百": "百 bǎi（第三声）与 bái（第二声）声调不同，意思是一百。", "败": "败 bài（第四声）与 bái（第二声）声调不同，意思是失败。", "排": "排 pái 与 bái 声母不同（b 与 p），意思是排列。", "摆": "摆 bǎi（第三声）与 bái（第二声）声调不同，意思是摆放。"}, "sentence_index": null, "correct_answer": "白"}, "level_3": {"options": [{"text": "白", "is_correct": true, "explanation": "“天上的云很白”描写云的颜色，与“白”的颜色义相合。"}, {"text": "绿", "is_correct": false, "explanation": "语义：云一般不呈绿色，说“很绿”与句意不符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，不能用来形容云。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”说质地，云一般不说“硬”，搭配不通。"}], "explanations": {"白": "“天上的云很白”描写云的颜色，与“白”的颜色义相合。", "绿": "语义：云一般不呈绿色，说“很绿”与句意不符。", "甜": "语义：“甜”说味道，不能用来形容云。", "硬": "搭配：“硬”说质地，云一般不说“硬”，搭配不通。"}, "sentence_index": 0, "correct_answer": "白"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "柠檬熟了以后是白的。", "explanation": "这里应该用〈黄〉。柠檬成熟后是黄色，“白”指白色，颜色用错了。"}, {"text": "成熟的番茄是白的，一口咬下去很甜。", "explanation": "这里应该用〈红〉。番茄成熟后是红色，“白”指白色，颜色用错了。"}, {"text": "墨水是白的，写出来的字很清楚。", "explanation": "这里应该用〈黑〉。墨水是黑色的，“白”指白色，与“黑”混淆了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "白", "is_correct": true, "explanation": "白 bái（第二声）是像雪和牛奶那样的颜色。"}, {"text": "埋", "is_correct": false, "explanation": "埋 mái 与 bái 声母不同（b 与 m），意思是埋藏。"}, {"text": "抬", "is_correct": false, "explanation": "抬 tái 与 bái 声母不同（b 与 t），意思是抬起。"}, {"text": "拜", "is_correct": false, "explanation": "拜 bài（第四声）与 bái（第二声）声调不同，意思是拜访或行礼。"}, {"text": "牌", "is_correct": false, "explanation": "牌 pái 与 bái 声母不同（b 与 p），意思是牌子或卡片。"}], "explanations": {"白": "白 bái（第二声）是像雪和牛奶那样的颜色。", "埋": "埋 mái 与 bái 声母不同（b 与 m），意思是埋藏。", "抬": "抬 tái 与 bái 声母不同（b 与 t），意思是抬起。", "拜": "拜 bài（第四声）与 bái（第二声）声调不同，意思是拜访或行礼。", "牌": "牌 pái 与 bái 声母不同（b 与 p），意思是牌子或卡片。"}, "sentence_index": null, "correct_answer": "白"}, "level_3": {"options": [{"text": "白", "is_correct": true, "explanation": "“外面都白了”说的是雪落后地面变白，与“白”的颜色义相合。"}, {"text": "宽", "is_correct": false, "explanation": "语义：“宽”说宽窄，外面不能说“宽了”，与句意不合。"}, {"text": "粗", "is_correct": false, "explanation": "搭配：“粗”说粗细，不用来描述大范围的环境，搭配不通。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，与“雪下得很大”的描写不合。"}], "explanations": {"白": "“外面都白了”说的是雪落后地面变白，与“白”的颜色义相合。", "宽": "语义：“宽”说宽窄，外面不能说“宽了”，与句意不合。", "粗": "搭配：“粗”说粗细，不用来描述大范围的环境，搭配不通。", "慢": "语义：“慢”说速度，与“雪下得很大”的描写不合。"}, "sentence_index": 6, "correct_answer": "白"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天的树叶是白的，郁郁葱葱。", "explanation": "这里应该用〈绿〉。树叶是绿色的，“白”指白色，颜色用错了。"}, {"text": "乌鸦是白的，飞过天空很显眼。", "explanation": "这里应该用〈黑〉。乌鸦是黑色的，“白”指白色，与“黑”混淆了。"}, {"text": "熟透的草莓是白的，吃起来又甜又多汁。", "explanation": "这里应该用〈红〉。成熟的草莓是红色，“白”指白色，颜色用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的皮肤白像牛奶。", "corrected_sentence": "她的皮肤白得像牛奶。", "error_description": "“白”后接补语时要用“得”连接。“白像牛奶”不成句，应为“她的皮肤白得像牛奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爷爷的胡子了白。", "corrected_sentence": "我爷爷的胡子白了。", "error_description": "“白了”表示变成白色，“了”须紧跟在“白”后。“胡子了白”顺序颠倒，应为“胡子白了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54fa33ea-97a6-4cb8-8259-720f360ce513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“由于”是说一件事的原因，后面的事是因为它才有的。", "primary_collocate": null, "pronunciation": "yóu yú", "ipa": "jou˧˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "由于他生病了，今天没来上课。", "target_word": "由于", "complexity_tier": "T3", "furigana": "yóu yú", "sentence_source": "generated"}, {"text": "由于这里太吵，我没有睡好。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于下雨了，我们没有去公园。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于路上堵车，爸爸回来得很晚。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于他很努力，成绩提高了不少。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于我没带钥匙，只好在门口等。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于她会说中文，公司请她当翻译。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于价格太贵，很多人不买。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于大家都很忙，会议改到了下周。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于我不知道地址，找了很久。", "target_word": "由于", "complexity_tier": "T3", "furigana": "yóu yú", "sentence_source": "generated"}], "morphological_forms": [{"form": "由於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "引出原因分句的连词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe9379e-d00e-43eb-9305-1708c35ab005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "由于", "is_correct": true, "explanation": "正确答案。“由于”是连词，引出原因分句。"}, {"text": "犹豫", "is_correct": false, "explanation": "与“由于”只有第二个音节声调不同（yù，第四声），意思是拿不定主意，不是引出原因。"}, {"text": "优于", "is_correct": false, "explanation": "与“由于”只有第一个音节声调不同（yōu，第一声），意思是比……更好。"}, {"text": "幼鱼", "is_correct": false, "explanation": "与“由于”只有第一个音节声调不同（yòu，第四声），意思是还没长大的小鱼。"}, {"text": "犹如", "is_correct": false, "explanation": "与“由于”只有第二个音节声母不同（rú 与 yú 的声母为 r 与 y），意思是好像。"}], "explanations": {"由于": "正确答案。“由于”是连词，引出原因分句。", "犹豫": "与“由于”只有第二个音节声调不同（yù，第四声），意思是拿不定主意，不是引出原因。", "优于": "与“由于”只有第一个音节声调不同（yōu，第一声），意思是比……更好。", "幼鱼": "与“由于”只有第一个音节声调不同（yòu，第四声），意思是还没长大的小鱼。", "犹如": "与“由于”只有第二个音节声母不同（rú 与 yú 的声母为 r 与 y），意思是好像。"}, "sentence_index": null, "correct_answer": "由于"}, "level_3": {"options": [{"text": "由于", "is_correct": true, "explanation": "正确答案。“由于他生病了”引出今天没来上课的原因。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，这里前后没有转折关系。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”引出充分条件，表示有这一条件就够，与生病导致缺课的因果不符。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”要与“都”呼应，这里没有“都”，不通。"}], "explanations": {"由于": "正确答案。“由于他生病了”引出今天没来上课的原因。", "但是": "语义：“但是”表示转折，这里前后没有转折关系。", "只要": "语义：“只要”引出充分条件，表示有这一条件就够，与生病导致缺课的因果不符。", "无论": "搭配：“无论”要与“都”呼应，这里没有“都”，不通。"}, "sentence_index": 0, "correct_answer": "由于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下了一场大雪，由于我们没去爬山。", "explanation": "这里应该用〈因此〉。“由于”引出原因，不能引出结果；“我们没去爬山”是结果。"}, {"text": "我们努力学习，由于考上了大学。", "explanation": "这里应该用〈为了〉。“由于”引出已经发生的原因，“为了”引出目的；“考上大学”是目的。"}, {"text": "由于天气如何，我们都要去。", "explanation": "这里应该用〈无论〉。“由于”只引出原因，不能表示“不论怎样”的条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "由于", "is_correct": true, "explanation": "正确答案。“由于她会说中文”引出公司请她当翻译的原因。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，这里前后是因果关系，不是选择关系。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”引出不利的后果，与“她会说中文”的因果关系不符。"}, {"text": "因而", "is_correct": false, "explanation": "搭配：“因而”引出结果，前面要有原因分句，这里句首用它不通。"}], "explanations": {"由于": "正确答案。“由于她会说中文”引出公司请她当翻译的原因。", "或者": "语义：“或者”表示选择，这里前后是因果关系，不是选择关系。", "否则": "语义：“否则”引出不利的后果，与“她会说中文”的因果关系不符。", "因而": "搭配：“因而”引出结果，前面要有原因分句，这里句首用它不通。"}, "sentence_index": 6, "correct_answer": "由于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "由于下雨，我们还是去了公园。", "explanation": "这里应该用〈虽然〉。“还是”要求前文有转折，“由于”引出原因，不能表示让步。"}, {"text": "由于开会之前，我们先喝茶。", "explanation": "这里应该用〈在……之前〉。“由于”只引出原因，不能表示时间先后，应说“在开会之前”。"}, {"text": "他由于骑自行车上学。", "explanation": "这里表示交通方式，不是原因。“由于”只引出原因，不能用来说明交通方式，这里应去掉“由于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "因为由于忘了带伞，他淋湿了。", "corrected_sentence": "由于忘了带伞，他淋湿了。", "error_description": "“因为”和“由于”都引出原因，不能叠用。应去掉“因为”，写成“由于忘了带伞，他淋湿了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "由于的天气太热，我们不想出去。", "corrected_sentence": "由于天气太热，我们不想出去。", "error_description": "“由于”后面直接接原因，中间不能加“的”。应写成“由于天气太热”，不能说“由于的天气太热”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
