INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85962, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "广播或电视节目与现场事件同时播出。", "primary_collocate": null, "pronunciation": "zhí bō", "ipa": "tʂɻ̩˧˥ pwo˥", "syllable_count": 2, "sentences": [{"text": "电视台将直播明天的开幕式。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场音乐会由电台直播。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场救援行动已经直播了两个小时。", "target_word": "直播", "complexity_tier": "T3", "furigana": "nà chǎng jiù yuán xíng dòng yǐ jīng zhí bō le liǎng gè xiǎo shí.", "sentence_source": "generated"}, {"text": "晚会从八点开始直播。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会的比赛都在电视上直播。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台正在直播市长的讲话。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的足球比赛不直播。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次大会通过电视直播。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节目直播的时候，不能出错。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的演出会通过校园广播直播。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "直播了", "label": "体标"}, {"form": "直播过", "label": "体标"}, {"form": "直播间", "label": "复合"}], "register": "中性", "sense_fingerprint": "广播或电视节目与现场事件同步播出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8be57f03-7fb2-4413-ac65-d96db36736d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直播", "is_correct": true, "explanation": "正确：“电视台将直播明天的开幕式”表示与现场同步播出，与句意吻合。"}, {"text": "感冒", "is_correct": false, "explanation": "配价：“感冒”是不及物动词，不能带“开幕式”作宾语。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能接“开幕式”这类活动。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与电视台播出开幕式的意思无关。"}], "explanations": {"直播": "正确：“电视台将直播明天的开幕式”表示与现场同步播出，与句意吻合。", "感冒": "配价：“感冒”是不及物动词，不能带“开幕式”作宾语。", "修理": "搭配：“修理”的对象是器物，不能接“开幕式”这类活动。", "扔": "语义：“扔”指丢弃，与电视台播出开幕式的意思无关。"}, "sentence_index": 0, "correct_answer": "直播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影下周直播。", "explanation": "这里应该用〈上映〉。电影是预先制作好的，不与现场事件同步播出，不能说直播。"}, {"text": "这座桥是去年直播的。", "explanation": "这里应该用〈修建〉。直播的是正在发生的事件，建成的桥梁是实物，不能说直播。"}, {"text": "这本杂志昨天直播了。", "explanation": "这里应该用〈印刷〉。杂志是印刷品，不与现场事件同步播出，不能用直播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直播", "is_correct": true, "explanation": "正确：“今天的足球比赛不直播”表示比赛不与现场同步播出，与句意吻合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能接“比赛”作宾语。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织”指编织，与比赛播出的意思无关。"}, {"text": "倒", "is_correct": false, "explanation": "配价：“倒”不带“比赛”作宾语，不能说“不倒比赛”。"}], "explanations": {"直播": "正确：“今天的足球比赛不直播”表示比赛不与现场同步播出，与句意吻合。", "吃": "搭配：“吃”的对象是食物，不能接“比赛”作宾语。", "织": "语义：“织”指编织，与比赛播出的意思无关。", "倒": "配价：“倒”不带“比赛”作宾语，不能说“不倒比赛”。"}, "sentence_index": 6, "correct_answer": "直播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本词典是去年直播的。", "explanation": "这里应该用〈编纂〉。直播的是正在发生的事件，编好的词典是成品，不能说直播。"}, {"text": "剧组在山上直播了一部纪录片。", "explanation": "这里应该用〈拍摄〉。纪录片是事后剪辑好的，不与现场事件同步播出，不能直播。"}, {"text": "这部动画片每天直播一集。", "explanation": "这里应该用〈播放〉。动画片是预先制作的，每集不与现场事件同步，不能直播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电视台被直播这场比赛。", "corrected_sentence": "电视台将直播这场比赛。", "error_description": "“直播”是主动的播出动作，不能用“被”引出，应说“将直播”；“被直播”用法错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚会已经直播了完。", "corrected_sentence": "晚会已经直播完了。", "error_description": "结果补语“完”应紧接动词，写成“直播完了”；“直播了完”语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c23282-4484-40a5-9e29-58a24c942707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
