INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85963, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "表是戴在手上用来看时间的东西。", "primary_collocate": null, "pronunciation": "biǎo", "ipa": "pjɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他手上戴着一块新表。", "target_word": "表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的表慢了五分钟。", "target_word": "表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看一下表，现在几点了？", "target_word": "表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸送给我一块红色的表。", "target_word": "表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块表是爷爷留下来的。", "target_word": "表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把表忘在家里了，所以不知道时间。", "target_word": "表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天早上都看表，怕上课迟到。", "target_word": "表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块表很贵，我买不起。", "target_word": "表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的表坏了，不走了。", "target_word": "表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你看看我的表，现在是三点。", "target_word": "表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "只", "label": "量词"}, {"form": "手表", "label": "复合"}, {"form": "錶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "戴在手腕上用来看时间的计时器具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef460676-d34c-4183-9f71-67713f994839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85963, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "表", "is_correct": true, "explanation": "表（biǎo）指戴在手腕上用来看时间的手表，是正确答案。"}, {"text": "标", "is_correct": false, "explanation": "biāo（第一声）与 biǎo（第三声）声调不同，意思是标记。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn 与 biǎo 只差韵尾（n 与 o），声调相同，意思是扁平。"}, {"text": "保", "is_correct": false, "explanation": "bǎo 与 biǎo 少了介音 i，声调相同，意思是保护。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo 与 biǎo 只差介音 i，声调相同，意思是宝贝。"}, {"text": "膘", "is_correct": false, "explanation": "biāo（第一声）与 biǎo（第三声）只差声调，意思是脂肪层，如“膘肥”。"}], "explanations": {"表": "表（biǎo）指戴在手腕上用来看时间的手表，是正确答案。", "标": "biāo（第一声）与 biǎo（第三声）声调不同，意思是标记。", "扁": "biǎn 与 biǎo 只差韵尾（n 与 o），声调相同，意思是扁平。", "保": "bǎo 与 biǎo 少了介音 i，声调相同，意思是保护。", "宝": "bǎo 与 biǎo 只差介音 i，声调相同，意思是宝贝。", "膘": "biāo（第一声）与 biǎo（第三声）只差声调，意思是脂肪层，如“膘肥”。"}, "sentence_index": null, "correct_answer": "表"}, "level_3": {"options": [{"text": "表", "is_correct": true, "explanation": "“表”指戴在手上的手表，与“戴着”和“新”搭配，符合句意。"}, {"text": "手帕", "is_correct": false, "explanation": "搭配：“戴”用于手表、戒指等，不能说戴手帕。"}, {"text": "肥皂", "is_correct": false, "explanation": "语义：肥皂不是戴在手上的物品，与句中“戴着”不符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能戴在手上，句子说不通。"}], "explanations": {"表": "“表”指戴在手上的手表，与“戴着”和“新”搭配，符合句意。", "手帕": "搭配：“戴”用于手表、戒指等，不能说戴手帕。", "肥皂": "语义：肥皂不是戴在手上的物品，与句中“戴着”不符。", "饼干": "语义：饼干不能戴在手上，句子说不通。"}, "sentence_index": 0, "correct_answer": "表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的墙上挂着一个大表。", "explanation": "这里应该用〈钟〉。挂在墙上的计时器叫钟，表是戴在手腕上的小型计时器。"}, {"text": "请你在这张表上签名。", "explanation": "这里的〈表〉指表格，不是戴在手上的手表。"}, {"text": "我买了一本表。", "explanation": "这里应该用〈块〉。手表用“块”计量，“本”用于书册，不能用于手表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85963, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "表", "is_correct": true, "explanation": "表（biǎo）指戴在手腕上用来看时间的手表，是正确答案。"}, {"text": "镖", "is_correct": false, "explanation": "biāo（第一声）与 biǎo（第三声）只差声调，意思是飞镖。"}, {"text": "瞟", "is_correct": false, "explanation": "piǎo 与 biǎo 只差声母的送气与否（p 与 b），声调相同，意思是斜着眼看。"}, {"text": "渺", "is_correct": false, "explanation": "miǎo 与 biǎo 只差声母（m 与 b），韵母与声调相同，意思是微小、渺茫。"}, {"text": "鳔", "is_correct": false, "explanation": "biào（第四声）与 biǎo（第三声）只差声调，意思是鱼鳔。"}], "explanations": {"表": "表（biǎo）指戴在手腕上用来看时间的手表，是正确答案。", "镖": "biāo（第一声）与 biǎo（第三声）只差声调，意思是飞镖。", "瞟": "piǎo 与 biǎo 只差声母的送气与否（p 与 b），声调相同，意思是斜着眼看。", "渺": "miǎo 与 biǎo 只差声母（m 与 b），韵母与声调相同，意思是微小、渺茫。", "鳔": "biào（第四声）与 biǎo（第三声）只差声调，意思是鱼鳔。"}, "sentence_index": null, "correct_answer": "表"}, "level_3": {"options": [{"text": "表", "is_correct": true, "explanation": "“表”指手表，可以用来看时间，与“看”和“怕上课迟到”的语境相符。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“看”不与“面包”搭配，早上看面包与“怕迟到”的语境无关。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不能用来查看时间，与“怕上课迟到”的语境不符。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：看报纸与“怕上课迟到”的语境无关，报纸不是用来看时间的东西。"}], "explanations": {"表": "“表”指手表，可以用来看时间，与“看”和“怕上课迟到”的语境相符。", "面包": "搭配：“看”不与“面包”搭配，早上看面包与“怕迟到”的语境无关。", "手套": "语义：手套不能用来查看时间，与“怕上课迟到”的语境不符。", "报纸": "语义：看报纸与“怕上课迟到”的语境无关，报纸不是用来看时间的东西。"}, "sentence_index": 6, "correct_answer": "表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房里的表响了，该关火了。", "explanation": "这里应该用〈计时器〉。厨房里定时响的是计时器，戴在手上的表不这样用。"}, {"text": "我家的水表坏了，要找人来修。", "explanation": "这里的〈表〉指测量用量的仪器，如水表、电表，不是戴在手上看时间的表。"}, {"text": "我写了一封信，以表谢意。", "explanation": "这里的〈表〉是动词，意思是表示，与名词“手表”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈送了我一本表。", "corrected_sentence": "妈妈送了我一块表。", "error_description": "“表”指手表，量词应用“块”，不能用“本”（“本”用于书籍等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶手腕上穿着一块旧表。", "corrected_sentence": "奶奶手腕上戴着一块旧表。", "error_description": "“表”戴在手上，应用动词“戴”，不能用“穿”（“穿”用于衣服、鞋袜等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9388185-a00f-442b-8554-3a2e1e3ae740') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关", "is_correct": true, "explanation": "正确答案。“开空调”与“关空调”是反义词，“关”表示使机器停止运转。"}, {"text": "写", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“写”表示写字。"}, {"text": "读", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“读”表示看着文字发出声音或理解文字。"}, {"text": "跑", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“跑”表示快速移动。"}], "correct_answer": "关", "explanations": {"关": "正确答案。“开空调”与“关空调”是反义词，“关”表示使机器停止运转。", "写": "与“开”的这一义项没有反义关系，“写”表示写字。", "读": "与“开”的这一义项没有反义关系，“读”表示看着文字发出声音或理解文字。", "跑": "与“开”的这一义项没有反义关系，“跑”表示快速移动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“开”是把关着的东西打开，或者让机器动起来（包括驾驶车辆）。", "primary_collocate": null, "pronunciation": "kāi", "ipa": "kʰaɪ˥", "syllable_count": 1, "sentences": [{"text": "屋里很黑，请开灯。", "target_word": "开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想看新闻，请开电视。", "target_word": "开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他会开车，常送我上班。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太冷了，请开空调。", "target_word": "开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水太热，你把水龙头开小一点。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸开了灯，屋子一下子亮了。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开着车，一边听音乐。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把风扇开着，我去买点水。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你开门，我忘了带钥匙。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我开过这种车，很容易。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了", "label": "完成体"}, {"form": "开着", "label": "持续体"}, {"form": "开过", "label": "经历体"}, {"form": "开开", "label": "重叠"}, {"form": "開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开：打开关着的东西，或使机器、电器运转（包括驾驶车辆）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe9379e-d00e-43eb-9305-1708c35ab005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“开”是动词，表示打开关着的东西，或使机器、电器运转。"}, {"text": "该", "is_correct": false, "explanation": "与“开”只有声母不同（g 与 k，g 不送气），意思是应该。"}, {"text": "拆", "is_correct": false, "explanation": "与“开”只有声母不同（ch 与 k），意思是把连接的东西分开。"}, {"text": "呆", "is_correct": false, "explanation": "与“开”只有声母不同（d 与 k），意思是发呆、呆板。"}, {"text": "嗨", "is_correct": false, "explanation": "与“开”只有声母不同（h 与 k），是叹词，表示打招呼。"}], "explanations": {"开": "正确答案。“开”是动词，表示打开关着的东西，或使机器、电器运转。", "该": "与“开”只有声母不同（g 与 k，g 不送气），意思是应该。", "拆": "与“开”只有声母不同（ch 与 k），意思是把连接的东西分开。", "呆": "与“开”只有声母不同（d 与 k），意思是发呆、呆板。", "嗨": "与“开”只有声母不同（h 与 k），是叹词，表示打招呼。"}, "sentence_index": null, "correct_answer": "开"}, "level_3": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“请开灯”表示请把灯打开。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关灯”与“屋里很黑”的要求相反，屋里黑时应该开灯。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象不能是“灯”，“吃灯”不通。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等，“戴灯”不通。"}], "explanations": {"开": "正确答案。“请开灯”表示请把灯打开。", "关": "语义：“关灯”与“屋里很黑”的要求相反，屋里黑时应该开灯。", "吃": "搭配：“吃”的对象不能是“灯”，“吃灯”不通。", "戴": "搭配：“戴”用于帽子、眼镜等，“戴灯”不通。"}, "sentence_index": 0, "correct_answer": "开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太冷了，我开了一件大衣。", "explanation": "这里应该用〈穿〉。“开”用于门窗、机器等，不能用于衣服；穿衣服要用〈穿〉。"}, {"text": "太冷了，我想开一杯热水。", "explanation": "这里应该用〈倒〉。“开”表示使机器、电器运转，不能用于倒水；倒热水要用〈倒〉。"}, {"text": "太冷了，我们开了一个决定。", "explanation": "这里应该用〈做〉。“开”不能跟“决定”搭配，做决定要用〈做〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“开着车”表示正在驾驶车辆，“一边听音乐”与之相符。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“车”作宾语，“睡着车”不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲等，“唱着车”不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，“写着车”不通。"}], "explanations": {"开": "正确答案。“开着车”表示正在驾驶车辆，“一边听音乐”与之相符。", "睡": "配价：“睡”是不及物动词，不能带“车”作宾语，“睡着车”不通。", "唱": "搭配：“唱”的对象是歌曲等，“唱着车”不通。", "写": "搭配：“写”的对象是文字，“写着车”不通。"}, "sentence_index": 6, "correct_answer": "开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开了眼睛，看见了窗外的雪。", "explanation": "这里应该用〈睁开〉。“开”不能直接跟“眼睛”搭配表示睁眼。"}, {"text": "谜底开了，大家都很惊讶。", "explanation": "这里应该用〈揭开〉。“开”不能用于谜底，揭开谜底要说“揭开”。"}, {"text": "他开了这个疑问，还没有想明白。", "explanation": "这里应该用〈解开〉。“开”不能直接跟“疑问”搭配，解答疑问要说“解开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把空调开小一个。", "corrected_sentence": "请把空调开小一点。", "error_description": "错误：“开小”后面的程度补语应用“一点”，不能用量词“个”。正确：“请把空调开小一点。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种车我开得不了。", "corrected_sentence": "这种车我开不了。", "error_description": "表示不能做某事的可能补语，否定形式是“开不了”，不能说“开得不了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85968, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谢", "is_correct": true, "explanation": "正确答案。“花开”与“花谢”是反义词，“谢”指花朵凋落。"}, {"text": "吃", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“吃”表示进食。"}, {"text": "写", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“写”表示写字。"}, {"text": "唱", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“唱”表示发出歌声。"}], "correct_answer": "谢", "explanations": {"谢": "正确答案。“花开”与“花谢”是反义词，“谢”指花朵凋落。", "吃": "与“开”的这一义项没有反义关系，“吃”表示进食。", "写": "与“开”的这一义项没有反义关系，“写”表示写字。", "唱": "与“开”的这一义项没有反义关系，“唱”表示发出歌声。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85968, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关", "is_correct": true, "explanation": "正确答案。“开门”与“关门”是反义词，“商店十点才开门”的反面是“关门”。"}, {"text": "买", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“买”表示购买。"}, {"text": "读", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“读”表示看着文字发出声音或理解文字。"}, {"text": "跑", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“跑”表示快速移动。"}], "correct_answer": "关", "explanations": {"关": "正确答案。“开门”与“关门”是反义词，“商店十点才开门”的反面是“关门”。", "买": "与“开”的这一义项没有反义关系，“买”表示购买。", "读": "与“开”的这一义项没有反义关系，“读”表示看着文字发出声音或理解文字。", "跑": "与“开”的这一义项没有反义关系，“跑”表示快速移动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，使关闭的东西张开、打通；也指启动、开始，也指花朵绽放。", "primary_collocate": null, "pronunciation": "kāi", "ipa": "kʰaɪ˥", "syllable_count": 1, "sentences": [{"text": "我没带钥匙，请你开门。", "target_word": "开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天热，我想开窗。", "target_word": "开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想说话，可是开不了口。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，花都开了。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店九点开，晚上十点关。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在学校旁边开了一家小书店。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开着，我直接走了进去。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太闷，请你把窗户开大一点。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路开了以后，去山里很方便。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店十点才开门，我们先去喝茶吧。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了", "label": "完成体"}, {"form": "开着", "label": "持续体"}, {"form": "开过", "label": "经历体"}, {"form": "开开", "label": "重叠"}, {"form": "開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开：使关着的东西张开、打通，或开始经营，或花朵绽放", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe9379e-d00e-43eb-9305-1708c35ab005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85968, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“开”是动词，表示使关着的东西张开、打通，或开始。"}, {"text": "该", "is_correct": false, "explanation": "与“开”只有声母不同（g 与 k，g 不送气），意思是应该。"}, {"text": "拆", "is_correct": false, "explanation": "与“开”只有声母不同（ch 与 k），意思是把连接的东西分开。"}, {"text": "呆", "is_correct": false, "explanation": "与“开”只有声母不同（d 与 k），意思是发呆、呆板。"}, {"text": "嗨", "is_correct": false, "explanation": "与“开”只有声母不同（h 与 k），是叹词，表示打招呼。"}], "explanations": {"开": "正确答案。“开”是动词，表示使关着的东西张开、打通，或开始。", "该": "与“开”只有声母不同（g 与 k，g 不送气），意思是应该。", "拆": "与“开”只有声母不同（ch 与 k），意思是把连接的东西分开。", "呆": "与“开”只有声母不同（d 与 k），意思是发呆、呆板。", "嗨": "与“开”只有声母不同（h 与 k），是叹词，表示打招呼。"}, "sentence_index": null, "correct_answer": "开"}, "level_3": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“请你开门”表示请对方把门打开。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关门”与“没带钥匙、要进门”的意思相反，关门会把人挡在外面。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿”不能以“门”为宾语，“拿门”不通。"}, {"text": "找", "is_correct": false, "explanation": "搭配：“找”的对象是人或物，“找门”不能表示打开门。"}], "explanations": {"开": "正确答案。“请你开门”表示请对方把门打开。", "关": "语义：“关门”与“没带钥匙、要进门”的意思相反，关门会把人挡在外面。", "拿": "搭配：“拿”不能以“门”为宾语，“拿门”不通。", "找": "搭配：“找”的对象是人或物，“找门”不能表示打开门。"}, "sentence_index": 0, "correct_answer": "开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天到了，花都开会了。", "explanation": "这句中的“开”被理解为召集会议，花不能召集会议；这里的“开”指花朵绽放。"}, {"text": "春天到了，花都开药了。", "explanation": "这句中的“开”被理解为医生开具处方，花不能开处方；这里的“开”指花朵绽放。"}, {"text": "春天到了，花都开刀了。", "explanation": "这句中的“开”被理解为做手术，花不能做手术；这里的“开”指花朵绽放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“门开着”表示门是打开的状态，“我直接走了进去”与之相符。"}, {"text": "锁", "is_correct": false, "explanation": "语义：“锁着”表示门被锁住，与“我直接走了进去”矛盾。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等，不能以“门”为宾语。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，“穿着门”不通。"}], "explanations": {"开": "正确答案。“门开着”表示门是打开的状态，“我直接走了进去”与之相符。", "锁": "语义：“锁着”表示门被锁住，与“我直接走了进去”矛盾。", "戴": "搭配：“戴”用于帽子、眼镜等，不能以“门”为宾语。", "穿": "搭配：“穿”用于衣服、鞋袜，“穿着门”不通。"}, "sentence_index": 6, "correct_answer": "开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开了一个誓言，要永远不再抽烟。", "explanation": "这里应该用〈立〉。“开”不能跟“誓言”搭配，立誓言要说“立下”。"}, {"text": "妈妈开了一首诗，读给我们听。", "explanation": "这里应该用〈读〉。“开”不能用于诗，读诗要说“读”。"}, {"text": "他开了一个微笑，看起来很开心。", "explanation": "这里应该用〈露出〉。“开”不能用于表情，露出微笑要说“露出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
