INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "实施高等教育的学校，招收高中毕业生，培养专门人才。", "primary_collocate": null, "pronunciation": "dà xué", "ipa": "ta˥˩ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "他考上了北京的一所大学。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学有很多外国老师。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在大学学习法律。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学的图书馆又大又新。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高中毕业以后，他想去大学学习。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那所大学今年招了三千个高中毕业生。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学的老师常常带学生做研究。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离这所大学很近，走路十分钟。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在大学里认识了很多朋友。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学在全国很有名。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "大學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "高等教育的学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe9379e-d00e-43eb-9305-1708c35ab005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85974, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大雪", "is_correct": false, "explanation": "xuě（第三声）与 xué（第二声）声调不同，意思是大雪（节气名）。"}, {"text": "大学", "is_correct": true, "explanation": "正确答案：大学（dà xué），指实施高等教育、招收高中毕业生的学校。"}, {"text": "大写", "is_correct": false, "explanation": "xiě（第三声）与 xué 韵母不同（ie 与 üe），声调也不同，意思是大写字母。"}, {"text": "大选", "is_correct": false, "explanation": "xuǎn（第三声）与 xué 韵母和声调都不同，意思是全国性的选举。"}], "explanations": {"大雪": "xuě（第三声）与 xué（第二声）声调不同，意思是大雪（节气名）。", "大学": "正确答案：大学（dà xué），指实施高等教育、招收高中毕业生的学校。", "大写": "xiě（第三声）与 xué 韵母不同（ie 与 üe），声调也不同，意思是大写字母。", "大选": "xuǎn（第三声）与 xué 韵母和声调都不同，意思是全国性的选举。"}, "sentence_index": null, "correct_answer": "大学"}, "level_3": {"options": [{"text": "大学", "is_correct": true, "explanation": "正确：大学指高等教育的学校，可以“考上”，与量词“所”搭配。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站不招生、不考试录取，“考上”不能用于车站。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不招生、不培养学生，与“考上”的意思矛盾。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市不是教育机构，不能用“考上”来表示进入。"}], "explanations": {"大学": "正确：大学指高等教育的学校，可以“考上”，与量词“所”搭配。", "车站": "语义：车站不招生、不考试录取，“考上”不能用于车站。", "公园": "语义：公园不招生、不培养学生，与“考上”的意思矛盾。", "超市": "语义：超市不是教育机构，不能用“考上”来表示进入。"}, "sentence_index": 0, "correct_answer": "大学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "被告下个星期要在大学接受审判。", "explanation": "这里应该用〈法院〉。审判要在法院进行，大学是学校，不能说“在大学接受审判”。"}, {"text": "这架飞机十分钟后在大学降落。", "explanation": "这里应该用〈机场〉。飞机要在机场降落，大学是学校，不能作为飞机降落的地方。"}, {"text": "这列火车十分钟后在大学进站。", "explanation": "这里应该用〈车站〉。火车要在车站进站，大学不是车站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85974, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大象", "is_correct": false, "explanation": "xiàng（第四声）与 xué 韵母不同，声调也不同，意思是大象。"}, {"text": "大学", "is_correct": true, "explanation": "正确答案：大学（dà xué），指实施高等教育、招收高中毕业生的学校。"}, {"text": "大笑", "is_correct": false, "explanation": "xiào（第四声）与 xué 韵母和声调都不同，意思是大声笑。"}, {"text": "大小", "is_correct": false, "explanation": "xiǎo（第三声）与 xué 韵母和声调都不同，意思是大小、尺寸。"}], "explanations": {"大象": "xiàng（第四声）与 xué 韵母不同，声调也不同，意思是大象。", "大学": "正确答案：大学（dà xué），指实施高等教育、招收高中毕业生的学校。", "大笑": "xiào（第四声）与 xué 韵母和声调都不同，意思是大声笑。", "大小": "xiǎo（第三声）与 xué 韵母和声调都不同，意思是大小、尺寸。"}, "sentence_index": null, "correct_answer": "大学"}, "level_3": {"options": [{"text": "大学", "is_correct": true, "explanation": "正确：大学指高等教育的学校，老师和学生在其中教学、做研究。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，不是教学机构，与“带学生做研究”冲突。"}, {"text": "商店", "is_correct": false, "explanation": "搭配：“老师”通常与学校或培训机构搭配，“商店的老师”不成立。"}, {"text": "剧院", "is_correct": false, "explanation": "语义：剧院不培养学生，不会出现“学生做研究”的情况。"}], "explanations": {"大学": "正确：大学指高等教育的学校，老师和学生在其中教学、做研究。", "工厂": "语义：工厂是生产场所，不是教学机构，与“带学生做研究”冲突。", "商店": "搭配：“老师”通常与学校或培训机构搭配，“商店的老师”不成立。", "剧院": "语义：剧院不培养学生，不会出现“学生做研究”的情况。"}, "sentence_index": 6, "correct_answer": "大学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我哥哥今年才上高一，在北京一所大学读书。", "explanation": "这里应该用〈高中〉。大学只招收高中毕业生，高一学生还在高中读书。"}, {"text": "我妹妹没念过高中，初中毕业后就直接在北京的大学读书。", "explanation": "这里应该用〈高中〉。大学只招收高中毕业生，初中毕业后要先读高中，不能直接进大学。"}, {"text": "我女儿今年六岁，正在一所大学读一年级。", "explanation": "这里应该用〈小学〉。大学招收高中毕业生，六岁的孩子应读小学一年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他考上了上海的一个大学。", "corrected_sentence": "他考上了上海的一所大学。", "error_description": "量词错误：“大学”的量词应用“所”，不能说“一个大学”，应说“一所大学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥明年要上过大学。", "corrected_sentence": "我哥哥明年要上大学。", "error_description": "体标错误：“过”表示已经有过的经历，句中说的是明年的事，不能用“上过”，应说“要上大学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3d6906-90a4-4a66-bbe3-0689e1d1809f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
