INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在国家、组织或团体中担任领导职务的人。", "primary_collocate": null, "pronunciation": "lǐng dǎo rén", "ipa": "liŋ˨˩ tɑʊ˨˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "各国领导人今天在北京见面。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位国家领导人明天会去中国。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的领导人开了一个大会。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人谈到了经济问题。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个组织的领导人。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界领导人一起讨论天气问题。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的领导人明年就会选出来。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导人在电视上说了几句话。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想成为国家的领导人。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位领导人很受人们喜欢。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "領導人", "label": "繁体"}, {"form": "国家领导人", "label": "复合"}], "register": "中性", "sense_fingerprint": "领导人：国家、组织或团体中担任领导职务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f931a9f9-e62e-44dc-9fd3-572b2af66ba9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领导人", "is_correct": true, "explanation": "正确。“各国……”修饰的是能够“见面”、代表国家的人，只有“领导人”符合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人，不能代表国家见面。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：“饭馆”是场所，不能作为“各国”的见面主体。"}, {"text": "政策", "is_correct": false, "explanation": "搭配：“政策”不能与“见面”搭配，见面的主体应是人或代表。"}], "explanations": {"领导人": "正确。“各国……”修饰的是能够“见面”、代表国家的人，只有“领导人”符合。", "石头": "语义：“石头”不是人，不能代表国家见面。", "饭馆": "语义：“饭馆”是场所，不能作为“各国”的见面主体。", "政策": "搭配：“政策”不能与“见面”搭配，见面的主体应是人或代表。"}, "sentence_index": 0, "correct_answer": "领导人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同是两国的领导人。", "explanation": "这里误把〈领导人〉用于文件。领导人指担任职务的人，合同是文件，应说〈协议〉。"}, {"text": "这次会议来了一座领导人。", "explanation": "这里应该用〈位〉。指人的领导人用“位”，“座”用于山、楼等大型物体。"}, {"text": "北京是两国的领导人。", "explanation": "这里误把〈领导人〉用于地点。领导人指担任职务的人，城市是地点，不能担任职务；指城市应说〈首都〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领导人", "is_correct": true, "explanation": "正确。“选出来”的对象是担任职务的人，只有“领导人”符合。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”是时间，不能被选出担任职务。"}, {"text": "合同", "is_correct": false, "explanation": "搭配：“选出来”不能用于“合同”，只能用于人或职务。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是人，不能被选出担任职务。"}], "explanations": {"领导人": "正确。“选出来”的对象是担任职务的人，只有“领导人”符合。", "夏天": "语义：“夏天”是时间，不能被选出担任职务。", "合同": "搭配：“选出来”不能用于“合同”，只能用于人或职务。", "歌曲": "语义：“歌曲”不是人，不能被选出担任职务。"}, "sentence_index": 6, "correct_answer": "领导人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那本书的领导人很受人们喜欢。", "explanation": "这里应该用〈作者〉。领导人指担任职务的人，书的写作者要用“作者”。"}, {"text": "这次会议来了一件领导人。", "explanation": "这里应该用〈位〉。指人的领导人用“位”，“件”用于物品。"}, {"text": "那首歌是人们喜欢的领导人。", "explanation": "这里误把〈领导人〉用于作品。领导人指担任职务的人，歌曲是作品，应说〈作品〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议请来了一只国家领导人。", "corrected_sentence": "会议请来了一位国家领导人。", "error_description": "错误形式是“一只国家领导人”，正确形式是“一位国家领导人”。“国家领导人”指人，量词应用“位”，“只”只用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位国家领导人们都来了。", "corrected_sentence": "几位国家领导人都来了。", "error_description": "错误形式是“几位国家领导人们”，正确形式是“几位国家领导人”。“几位”已表示复数，“领导人”后面不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209d29c1-2922-4e7c-9120-77607a69b885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
